window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_047"]={"n":"张宁","dyn":"明","poems":[{"t":"襄阳乐","f":"七言律诗","c":["襄阳女儿夜行游，牵衣把袂大堤头。","歌声未歇笑声起，唱处无情闻处愁。","珠珰玉佩摇春绿，北渚南湖相间属。","至今荆楚宦游人，犹唱襄阳《大堤曲》。"]},{"t":"士女图为张宗大题二首 其一","f":"七言律诗","c":["吴城士女越样妆，笼冠盘髻销金裳。","东风淡荡桃李月，看花不语情何长。","女伴相将牵稚子，庭院无人花正芳。","春阳宛宛白日暮，空抱花枝归洞房。"]},{"t":"题姚公绶山水小幅","f":"五言律诗","c":["幽意写不尽，万山深更深。","白云无出处，绿树漫成林。","啼鸟醒人梦，流泉净客心。","何当随钓艇，看弈草堂阴。"]},{"t":"重游金粟寺有作","f":"五言律诗","c":["溪深通小艇，山峻路层台。","林叶经霜尽，河冰近午开。","閒云僧出定，旧雨客重来。","扰扰浮生路，经过知几回。"]},{"t":"感事二首 其一","f":"七言律诗","c":["羽书昨夜报居庸，百万雄师下九重。","天子垂衣临大漠，群臣端笏扈元戎。","禁中已乏回天谏，阃外谁成辟地功。","千古澶渊扶日毂，令人长忆寇莱公。"]},{"t":"感事二首 其二","f":"七言律诗","c":["宝马朱轮接上游，时危谁解奉天忧。","鼎湖龙去英雄尽，剑阁云深日月愁。","玉辇已随边地草，青山依旧汉宫秋。","元勋野死潼关破，误国何人更首丘。"]},{"t":"送史明古过访还吴江","f":"七言律诗","c":["一灯新火映邻扉，话尽残更未解衣。","元亮老嗟芜业改，无功生怯醉乡非。","天孤远雁和云断，风急春潮带雨飞。","暂尔相逢便相别，只应清梦送君归。"]},{"t":"题伍公矩桂林别意册后","f":"七言律诗","c":["五岭行云七泽风，东将入海汎鸿濛。","生还却笑征南老，往事空惊塞上翁。","万里归心孤碛雁，廿年春梦五更钟。","曲江院里看花伴，物色于今尽不同。"]},{"t":"莫愁乐","f":"五言绝句","c":["金雀玉搔头，生来唤莫愁。","自从欢去后，不出石城游。"]},{"t":"满江红 题碧梧翠竹送李阳春","f":"古风","c":["一曲清商，人别后，故园几度。","想翠竹、碧梧风采，旧游何处。","三径西风秋共老，满庭疏雨春都过。","看苍苔、白石易黄昏，愁无数。","峄山阳，淇水路。","误佳期，空跌蹉。","叹舞鸾鸣凤，归来迟莫。","冷淡过如西涧草，凄迷番作江东树。","且留取、素管候冰丝，重相和。"]},{"t":"南山有椿颂寿胡廷慎父母 其一","f":"楚辞体","c":["南山有椿，其本秩秩。","有美哲人，德音藉藉。","南山有椿，其叶穰穰。","有美哲人，其福洋洋。","哲人之配，如兄弟矣。","天监定尔，俾偕老矣。","哲人之彻，克世德兮。","帝督不忘，胥将赉兮。","百禄是集，万寿是锡。","如冈如陵，永保皇极。"]},{"t":"南山有椿颂寿胡廷慎父母 其二","f":"古风","c":["北堂有萱，净闿斯植。","乐只君子，柔贞惟一。","北堂有萱，雨露其滋。","乐只君子，寿考维祺。","凤之鸣矣，凰式和止。","既安且宁，家室固止。","子之生也，母式教之。","如圭如璋，显克肖之。","百禄是迓，万寿是介。","如冈如陵，夫子是载。"]},{"t":"鸣鹿颂","f":"古风","c":["鹿鸣呦呦，于山之幽。","载背载呼，言善其俦。","维体泽泽，维角戢戢。","匪外之防，维内之则。","相彼麟凰，寔郊寔薮。","释是町疃，乐此灵囿。","以礼为罗，以爵为縻。","匪罗匪縻，周行之归。","展也佳宾，胡不云来。","式燕以遨，乐只有仪。","文王不已，惠然来思。"]},{"t":"重建温国文正公祠堂颂","f":"古风","c":["堂宇翼翼，子孙之式。","于昭穆清，先祖孔怿。","既合既具，笾豆有奕。","维垣维屏，陟降有秩。","不庶以靡，先□之则。","绵绵夏邑，逖逖温国。","勿替嗣之，永世无斁。"]},{"t":"六礼有将式克语之三加有辞式克御之死丧之威翕共与之饮食言笑肃慎祇之增增来仍式谷以之毋俾此邦不竞谓之 其一","f":"古风","c":["伊厥肇基，实既于强。","不腆后人，孰搆孰堂。","骏美弗传，忧心京京。","载服于田，载艺于桑。","亦有良朋，于橐于囊。","硕果不食，先业用光。"]},{"t":"六礼有将式克语之三加有辞式克御之死丧之威翕共与之饮食言笑肃慎祇之增增来仍式谷以之毋俾此邦不竞谓之 其二","f":"古风","c":["何晦于夕，何著于昕。","举或坠之，事必式因。","毋安于易，毋恤于艰。","念敬尔守，祀事孔陈。","先公有言，予岂不闻。","冥冥积德，在我后人。"]},{"t":"履霜操","f":"楚辞体","c":["天降繁霜兮隆冬，嗟不隩处兮行逢。","饥寒迫切兮心冲冲，仰长号兮望穹窿。","儿命当终兮天鉴儿衷。"]},{"t":"上之回","f":"古风","c":["上之回，雍甘泉。","风云翕从，寒暑推迁。","驰北戎，驱南蛮。","率东瓯，走西滇。","周德四海安八埏，岁来巡行千万年。"]},{"t":"战城南","f":"古风","c":["战城南，死城北。","为子死父臣死国。","朱轮不疾驰，铁骑不徐行。","宁为结缨死，不学投戈生。","辱身降俘，委骨泥沙。","他人不论级，自己不遗名。","嗟哉新安与长平。"]},{"t":"将进酒","f":"古风","c":["将进酒，思未央。","俎豆具，宾客臧。","秬鬯实中尊，醴齐汲行觞。","百拜不及醉，酬酢德以将。","欢乐难具陈，言好不能忘。","夏歌述明训，周书有遗防。","持此为君寿，千春永无荒。","将进酒，思未央。"]},{"t":"有所思","f":"古风","c":["有所思，江之浔。","云汉寂寥阒，山岭郁嵚岑。","手持连城玉，袖置双南金。","见止未卒献，繁声变清琴。","咫尺万里远，一往难重寻。","有所思，思何深。"]},{"t":"临高台","f":"古风","c":["临高台，天中央。","白玉作柱，黄金为梁。","台端有嘉宾，台下启周行。","周行四达，佳宾相望。","投弓惜鹄，鸣凤来翔。"]},{"t":"艾如张","f":"古风","c":["艾而张罗，蒐以狩，宁干戈。","安不忘危，厉不伤和。","三面尽解如雀何。"]},{"t":"君马黄","f":"古风","c":["君马黄，臣马玄。","君马来自宛，臣马始离燕。","君马骋六飞，臣马厄孤骞。","六飞遥遥行上天，孤骞拘絷无由前。","安能日随御，矩步相周旋。"]},{"t":"春江花月夜","f":"五言律诗","c":["春水绿堪染，春花红欲然。","月华金涣漾，夜气玉暄妍。","交绕回文锦，联笼飞步仙。","赏心逢美景，欢娱正妙年。"]},{"t":"江陵女","f":"五言绝句","c":["白苧裁娘衫，茜练作娘裙。","情随吴江水，梦阻越山云。"]},{"t":"乌栖曲","f":"七言绝句","c":["乌桕树上夜乌栖，黄茆舍里晓鸡啼。","鸡啼未了乌飞去，锦帐佳人不知曙。"]},{"t":"采桑渡","f":"七言古诗","c":["采桑渡头采桑女，渡近黄河滞行旅。","女逢行客怀故欢，客逢桑女思家园。","家园桑叶共谁采，应念三江行路难。"]},{"t":"杨叛儿","f":"五言古诗","c":["依依白门柳，袅袅柔条芳。","藏乌犹未稳，便解绾愁肠。","侬有博山炉，欢为沈水香。","灰冷气长馥，绣帐七宝床。","新亭别离客，江宁故旧乡。","愿随枯杨老，莫作飘花狂。"]},{"t":"拔蒲","f":"五言古诗","c":["拔蒲水中央，未拔郎已别。","深拔断蒲根，浅拔断蒲叶。","叶断犹可将，根断心永绝。"]},{"t":"西乌夜飞","f":"七言绝句","c":["月明夜永乌西飞，瀼瀼白露沾乌衣。","无树可匝将畴依，东有挟弹乌安归。"]},{"t":"常林欢","f":"七言律诗","c":["桃林花落胭脂香，宣城酒熟珍珠光。","岘山汉水时来往，欢意不及常林长。","晨鸡唱歇啼莺晓，锦荐牙床春睡好。","天寒日暮未还家，梦中犹怯荆蛮道。"]},{"t":"江南弄","f":"古风","c":["采莲采菱双棹行，游女绰约朝云轻。","阳春和寡，吹凤笙，奏龙笛。","按秦筝。","鼓赵瑟。"]},{"t":"张静娘采莲曲","f":"七言古诗","c":["兰桡桂桨横江浦，玉露金波花正吐。","莲步初从掌上移，柳腰新罢盘中舞。","腰纤步窄不胜衣，雾縠烟绡飏欲飞。","雨歇朝云降巫女，月明秋水现湘妃。","莲房已实莲茎短，幽思伤心悄停腕。","弱腹羞看翠葆圆，柔肠暗逐冰丝断。","眼前歌舞易淹留，只恐风光不到头。","翠袖香销红艳冷，无人重上采莲舟。"]},{"t":"玉树后庭花","f":"五言律诗","c":["雅鬓含黛亸，蛾眉凝翠妆。","羞花娇笑语，赛玉软温香。","逢春惜易往，爱极使情伤。","后庭歌艳曲，前殿发清商。"]},{"t":"乌夜啼","f":"五言古诗","c":["日夕众喧寂，群鸟皆冥栖。","如何屋上乌，夜半哑哑啼。","屋中有思妇，不寐候晨鸡。","惊闻夜啼声，色喜情不怡。","明当有恩赦，揽衣出中闺。","曾闻孝慈乌，不类鹜与鹥。","复屋验兴周，登城知遁齐。","物兆有先见，由来事堪乩。","为语夜啼乌，止止无东西。"]},{"t":"子夜四时歌 其一 春歌","f":"五言古诗","c":["采桑南陌遥，摘柘西涧远。","春蚕已三眠，夫婿洛与宛。","安得缲织成，裁衣待君返。"]},{"t":"子夜四时歌 其二 夏歌","f":"五言古诗","c":["淼淼吴江津，悠悠越溪渚。","南风递荷香，洄溯三百里。","不见荡舟人，难随采莲女。"]},{"t":"子夜四时歌 其三 秋歌","f":"五言古诗","c":["捣衣出虚榭，停杵登西楼。","月色烂如昼，千山今夜秋。","游子不顾返，时节空淹留。"]},{"t":"子夜四时歌 其四 冬歌","f":"五言古诗","c":["岁晏时气肃，寒风透帏床。","镜敛双蛾蹙，被拂孤鸳翔。","玉关路千里，不如寒夜长。"]},{"t":"丁都护","f":"古风","c":["衣襟敛袭，明器充如。","丁都护。","杞梓桐柏，狸首斑如。","丁都护。","北山石椁，纻絮斮漆乎。","丁都护。","若堂若防马鬣乎。","丁都护。","菟裘营丘嬴博乎。","丁都护。","东西南北可识欤。","丁都护。","千秋万年可无虞。","丁都护。","死者乐土，生者安居。","丁都护。","夫骨有托，终以宁妾躯。","丁都护。"]},{"t":"凤台曲","f":"五言律诗","c":["吹箫来凤凰，弄玉偶箫史。","音声迭谐和，形体忽轩举。","彩云不复聚，华月照故址。","空遗千载名，流落无极止。"]},{"t":"公莫舞","f":"古风","c":["公莫舞，公莫舞。","剑光翕赫，衣袖屡举。","上摩头颅下足跗，前迎后送随仰偻。","挥霍星辰激风雨。","庄不停，伯不语。","白蛇中断夜哭妪，五色龙文气如许。","两虎自为雠，秦鹿去无所。","鸿门一时公莫舞。"]},{"t":"独漉篇","f":"古风","c":["独漉独漉，水清泥浊。","清犹可濯，浊则云涸。","鸿雁随阳，载居载翔。","不辑于行，而竞稻粱。","朱弦清琴，轸玉徽金。","逖矣同心，空此好音。","龙剑之合，精光辉熙。","试而无施，不如睽离。","寥寥旷野，以腊以春。","有来斯亲，孰知其人。"]},{"t":"淮南王篇","f":"古风","c":["淮南王，好长生。","秘书充栋，方士盈庭。","丹符断玉籍，左道迷中行。","刀圭发狂疾，几杖遗深情。","形气不复完，云雨何由兴。","便便小山客，讳死誇飞升。","君不见桥山葬，轩辕浪说垂髯登。","衡阳亦同逝，无士不流声。","至今犹慕淮南名。"]},{"t":"平陵东","f":"古风","c":["朝望平陵东，暮望平陵东。","松柏摧为薪，豺鼠化飞熊。","苍天不憖遗我公，我不能救将何从。","生人一何多，天道犹未终。","旦复旦，平陵东。"]},{"t":"巫山高","f":"古风","c":["巫山高，高不极。","瞿塘险，深莫测。","欲济无梁，奋飞无翼。","南人思南北思北，心怀中土何由适。","徘徊日暮云，怅望阳台侧。","远道未能归，何因念朝夕。"]},{"t":"薤露八章挽沈希仁父","f":"楚辞体","c":["萎彼薤斯，零露瀼瀼。","嗟我怀人，于焉徬徨。","萎彼薤斯，零露湛湛。","嗟我怀人，劳心惆怅。","闻古圣善，赙丧助昏。","乃如之人，实获我心。","匪沽则名，中心寔殷。","闻古圣善，简所因兮。","乃如之人，所可徵兮。","受言怀之，姑将亲兮。","维凤有毛，维麟有趾。","亶其然乎，善人是予。","维此善人，于彼窀穸。","彼苍者天，胡不尔吊。","翳彼大荒，祝㮚茫茫。","黾勉同心，玄冠绛裳。","绳其归思，我怀则降。","翳彼旷宇，濮铅脩阻。","礿祠馨香，宁兹寝处。","绳其格思，无尔嗣苦。"]},{"t":"题所画鸡鹅图二首 其一","f":"五言律诗","c":["昔我怀父母，初鸣即晨兴。","一从侍清禁，出门始闻声。","烹膳日已远，起舞欣时平。","胶胶风雨宵，寤寐伤馀情。"]},{"t":"题所画鸡鹅图二首 其二","f":"五言律诗","c":["独行澹无俦，拳立如有待。","饥唼水中蒲，渴仰石边濑。","宁随鸥鹭閒，不伍凫鹜态。","山阴久萧条，毛羽复谁爱。"]},{"t":"方洲八景八首 其一 柳塘春雨","f":"五言律诗","c":["新柳绕芳塘，柔风送时雨。","润草及西堂，增波接南浦。","得句起遐思，赠别怀旧侣。","回首灞陵桥，潇潇几行旅。"]},{"t":"方洲八景八首 其二 杏圃朝霞","f":"五言律诗","c":["春深花正开，天晴海初曙。","霞光云际来，艳色溢蓬宇。","明明碎锦坊，淡淡秋容圃。","聊因旦晚欢，妍丽安足数。"]},{"t":"方洲八景八首 其三 莲池叠翠","f":"五言律诗","c":["池中荷欲花，池上水初漫。","初看水上微，旋觉香不断。","一曲密藏鸥，万柄娇倚岸。","莫唱采莲歌，江南时节换。"]},{"t":"方洲八景八首 其四 麦陇翻云","f":"五言律诗","c":["时平田里安，麰麦被丘陇。","芃芃翠浪翻，蔪蔪绿云涌。","肥硗力虽殊，刈穫日可拱。","欲赋两岐歌，周诗更堪咏。"]},{"t":"方洲八景八首 其五 稻畦垂颖","f":"五言律诗","c":["农人告方及，秋事忽已成。","黄云被田野，白日寒光晴。","父老喜丰年，鼓缶过我行。","平生任经理，对此馀深情。"]},{"t":"方洲八景八首 其六 菊径凝香","f":"五言律诗","c":["田下去来久，三径行复期。","采采黄金花，照我头上丝。","含英抱幽馥，佳会良在兹。","羊肠九折坂，蔓草应正滋。"]},{"t":"方洲八景八首 其七 梅林雪霁","f":"五言律诗","c":["閒来好幽事，值此梅雪晴。","深林百草尽，野水寒烟生。","怡然发孤笑，婉恋有馀情。","冰霜六七载，永念孤山行。"]},{"t":"方洲八景八首 其八 竹坞晴风","f":"五言律诗","c":["菉竹蔽深坞，岁晚多阴风。","爱此旭日喧，万玉摇玲珑。","吟眸展清眄，倦耳生馀聪。","因之怀劲草，声色吾何从。"]},{"t":"赠陆汝谦","f":"五言古诗","c":["吾闻古神医，秦越扁鹊氏。","洞识阴阳机，妙达天地秘。","生人无前功，用术陋专技。","遇妇作女医，遇幼擅童稚。","或以伤疹称，所用随所至。","一一底工巧，何虑千古计。","古道既云远，时医极流弊。","造弓不顾甲，治外不恤内。","仁术化忍心，人命可轻试。","汝谦陆先生，三世名家裔。","动有古人风，一洗庸劣气。","余生坐迍蹇，有子方两岁。","乳哺失调摄，疾病遄以继。","惊风搐四体，鱼口双目闭。","群医竞叹息，束手坐相视。","先生徐徐来，驾言勿惊悸。","下榻夜尚迟，从容解金匮。","一投邪风疏，再下壮热退。","三服乃如常，下床作儿戏。","幽谷阳春回，大旱甘雨坠。","中年复有子，无乃仁人惠。","作诗表深功，庶以将薄意。"]},{"t":"寄谢浚僧官","f":"五言古诗","c":["浚公夙儒雅，自少偶业白。","天空一鹤举，海阔閒鸥立。","平生怯诗魔，老拙降未得。","清高逼休远，典雅超复泐。","虚堂戛鸣球，清啸闻月夕。","前年被徵荐，浮杯度京国。","樗栎厌青黄，尘泥混空色。","明珠堕浊水，皓镜悬土壁。","昔忝青云交，今逢白头客。","颇忆去年春，正卧投老疾。","清风故人远，旧雨深巷寂。","空谷音方隐，月门敲正急。","苔阶印只履，蓬户卓尔锡。","欣然起相携，冁尔冠屡侧。","吹灯照残夜，对酒忘畴昔。","岁月能几何，离旷非一日。","乌兔互驰逐，子亥忽流易。","元正十日初，复此得消息。","缄书遣高第，慇勤问眠食。","春林白团茶，秋圃紫苞栗。","仪多物兼备，岁去情转极。","时来得颠印，自愧非愈轼。","再拜送来使，开门日初出。","向来车马路，草长没行屐。"]},{"t":"对雨","f":"五言律诗","c":["草木已时萎，时菊方敷荣。","林空晚色净，日暮孤烟横。","仰荫修竹枝，俯挹蒙泉清。","岁月忽复易，采撷伤吾情。"]},{"t":"画云鸿振羽图题送陈掌教","f":"五言古诗","c":["东方有佳士，文质何彬彬。","昔为待沽玉，今备充廷珍。","朗诵商周诗，默会羲文神。","言词夙华雅，步履弥精纯。","初疑鹿鸣晚，为感鸿飞循。","江干寡俦侣，磐石多来宾。","矰缴既云远，稻粱安足勤。","进止各有节，险易常相因。","弦琴古坛树，载艺清池芹。","眷兹十年来，渐觉寒毡春。","陵陆日已迈，逵路日已臻。","祥云动四表，孤征戾中旻。","奋逐鹍鹏风，扬随鸾凤尘。","峨峨金阙楼，溶溶玉河津。","刷翎补干羽，万舞仪章新。"]},{"t":"爱兰","f":"五言律诗","c":["禀性无俗尚，爱此山泽芳。","拔葵艺周圃，分植置中堂。","入室有佳士，纫佩非私裳。","时好岂足贵，德馨谅难忘。"]},{"t":"重画云鸿振羽图题赠王良臣","f":"五言古诗","c":["翩翩渐鸿羽，一举从江干。","再举次磐石，三举逢平原。","升木良有得，陟陵竟无患。","不愿腾上远，但愿遵飞安。","祥云动四表，天逵浩漫漫。","孤征戾中霄，振翮偕鸳鸾。","联行两阶下，仪羽纷回盘。","云深日五色，万舞充华观。","巢居怀往事，凝望起长叹。"]},{"t":"送别沈履德","f":"五言古诗","c":["园花发朝艳，谷鸟遗春音。","岂无旦夕佳，倏忽流光阴。","幽居寡时好，感子时过临。","冥言启孤愤，高步超烦襟。","夙昔怀远道，遄别悲来今。","对酒不及醉，眷此故情深。"]},{"t":"云谷","f":"五言律诗","c":["閒云翳空谷，日夕生幽阴。","中有高世士，结屋云之深。","飞锡天外风，润泽寰中霖。","贞居聊自适，变化吾何心。"]},{"t":"正统戊辰闻福建感而有作","f":"五言古诗","c":["平衍说荆淮，险危闻陇蜀。","奈何吴魏间，汉氏犹鼎足。","况兹三山地，鼠窃弗盈蹴。","凭陵肆劫坏，鸱义歼人族。","譬犹负隅虎，据险势莫触。","食尽无后援，鼎俎咀其肉。","复闻圣天子，推心置人腹。","渠恶疾见尸，丑类将自服。","贼死匪所叹，致尤何太毒。"]},{"t":"见雨雪叹戊辰冬","f":"五言古诗","c":["日夕将天兵，闻已度淮水。","黎庶仰虹霓，雨雪何不止。","北军利高亢，值此非所喜。","行师有纪律，日须五十里。","南风吹铁衣，却走泥没趾。","锈涩剑锋回，塺疏弓力弛。","况不便舟船，经涉殊未已。","指日布阳春，顽阴悉飘委。"]},{"t":"王师至浙人情恟惧感而记之","f":"五言古诗","c":["厥哉南闽贼，远冒明王师。","军声动白日，淮海相逶迤。","群县务驰逐，民庶日何疲。","兵车恣横决，帷箔不可支。","岂知阳春日，坚冰乃相随。","我闻行师要，爱须威克之。","马嘶不敢骄，况尔部下为。","天子有休命，借问大将谁。"]},{"t":"怀恩楼为王宗勋赋","f":"五言古诗","c":["萱草生北堂，朝见夕已萎。","慈乌返故巢，鸣声一何哀。","感此时物喧，悠然动遐思。","况当慈母没，缅怀耿嗟咨。","赤子将入井，安能悟乖离。","营营愿襁褓，依依眷孩提。","周全乳哺艰，三年免于怀。","宵缝念儿寒，晨炊畏儿饥。","游子日已远，母心增伤悲。","殷勤二十载，为子有室家。","奈何白日晚，流光忽西驰。","明月照高楼，疏棂起凉飔。","徬徨中夜长，俯叹泪交颐。","慨彼泉下人，相见未有期。"]},{"t":"刘公觐毕姻诗勉之","f":"五言古诗","c":["飞飞鸳鸯鸟，比翼湖之涯。","生年不满百，燕婉当及时。","东邻有处女，春秋盛容姿。","一朝辞父母，托身游侠儿。","岂无百两将，而乃荡子妻。","妍华不自好，终身抱馀悲。","况君良家子，衣冠能自持。","母穷毕日欢，负此远大期。","辛壬与癸甲，斯文良在兹。"]},{"t":"答姜文进","f":"五言律诗","c":["瀰瀰江中水，黯黯江上树。","眷彼同心人，胡为忽异处。","驾言从扁舟，积雨不可渡。","愿随双黄鹄，庶以相会晤。"]},{"t":"赠柴取中","f":"五言古诗","c":["东风扇微和，万卉敷春阳。","盈盈桃李花，烂然竞容光。","绵绵路傍草，根株亦交相。","及时起凉飙，零落随秋霜。","争如谷中兰，清标压群芳。","虽无艳冶姿，而有冷淡香。","奈何岁华晚，保此故意长。","伤哉绿绮琴，纫佩罗衣裳。","视彼同心人，德音实难忘。"]},{"t":"夜宿斗门与朱氏原兼呈再从叔","f":"五言古诗","c":["予生二十年，始解访同族。","缅想姑祖亲，悲喜相交属。","如何百年内，情好复断续。","登堂思高曾，入门拜伯叔。","弟妹相惊呼，问是几世服。","源远末益分，膏泽犹未沐。","倾家出相见，喜气溢肠腹。","场头禾黍登，牖中酒醴熟。","端不为盘餐，聊以慰情曲。","我本季世孙，今当远行役。","生年能几何，欢会宁可复。","同姓古所敦，去去勿尘俗。","感激忠孝心，因之以相告。"]},{"t":"林居秋兴","f":"五言古诗","c":["凉风起天末，新凉入丘墟。","晏坐当前楹，陶然读吾书。","俯视庭草萎，仰看浮云舒。","山气日夕佳，灌木阴以敷。","轩冕岂不贵，而乐自有馀。","愿子保令终，因之相与娱。"]},{"t":"挽钟处士","f":"五言古诗","c":["丹山有灵鸟，文采相颉颃。","饥餐琅玕实，渴饮瑶池浆。","清音谐韶乐，锦羽映朝阳。","飞飞燕雀群，俯仰被馀光。","颠风折梧桐，鸣凤忽摧伤。","孤凰抱哀思，辑羽不复扬。","徘徊念同侣，躯命倏销亡。","翩翩九苞雏，览德岐山冈。","皇皇奋南征，哀鸣激中肠。","容华不自爱，宁辞关塞长。","死者不复生，龟麟总茫茫。","愿言勿残毁，阿阁正相望。"]},{"t":"黄主事挽诗","f":"五言古诗","c":["闻有高世士，筑室章贡间。","弱冠失父母，门户一线悬。","独立无人境，巍然亘前山。","起视丘垤群，坐我千仞巅。","娶妻良家女，生子当世贤。","煌煌五色诏，星星双鬓斑。","如何两楹奠，一梦起长叹。","伤哉同室亲，躯命不复延。","泣尽继以死，携手入重泉。","嗟彼未亡人，区区何独难。"]},{"t":"永思堂为刘廷宾赋","f":"五言古诗","c":["哀门历多故，生当元宋间。","高曾及祖考，累世事更迁。","风尘浩无际，兵车日豗喧。","羁危不自保，趋走恒穷年。","丧乱忽已平，营业亦周旋。","欢娱不经目，忧伤閟重泉。","昔常念寒燠，高居复华裀。","弱息久穷嫠，儿女日以殷。","缅怀颠沛时，门户朽索缘。","湍流一解手，宗祀付沈渊。","于焉涉艰阻，乃欲遗曾玄。","胡为祔祫馀，双亲中道捐。","远慕已无日，近哭悲终天。","沧波渺东注，白日中霄悬。","悠悠穹壤间，遐感何时諠。"]},{"t":"艺兰为王本诚作","f":"五言古诗","c":["猗猗谷中兰，言艺君子堂。","过门不入室，彼美自芬芳。","弹冠结素履，振策循周行。","我心惄如饥，觏止谅已降。","容颜挹清润，言笑闻馨香。","同心未卒语，欲去仍徬徨。","眷恋终日夕，宾主已相忘。"]},{"t":"滹沱冰合图","f":"五言律诗","c":["人心久思汉，帝主自有真。","多难启弘业，独此邯郸人。","穷蹙白登围，仓猝滹沱水。","河冰纵不合，光武亦不死。"]},{"t":"苍松轩","f":"五言律诗","c":["种竹绕轩居，清素聊自爱。","虽无桃李颜，不改冰霰态。","孤松色不殊，六月寒尚在。","倏然三径幽，凝碧如有待。"]},{"t":"为姚公绶题丹丘","f":"五言律诗","c":["东方有奇士，自号丹丘生。","超世立于独，宛若来蓬瀛。","言从黄石公，再从赤松子。","终始意斯在，幻境焉足跂。"]},{"t":"友兰","f":"五言律诗","c":["公门盛桃李，世路多荆榛。","温温爱兰交，吾思见其人。","伊人日已远，比物不盈畹。","同心澹忘言，岁月殊可晚。"]},{"t":"梅古春寿藏诗","f":"五言古诗","c":["郁郁凤凰山，生气何连延。","有美清修士，遗世希神仙。","高情出茫昧，独见超虚玄。","仰瞻山木花，俯视重冈旋。","凿石启幽閟，种槚待芳妍。","夙怀瑕丘乐，预见佳城悬。","聚散本元造，寿夭谁能专。","桥山有高冢，王乔亦遗阡。","乘鸾与跨凤，刀圭终弃埙。","何如一生死，坦率穷高年。"]},{"t":"武澄梦萱卷","f":"五言古诗","c":["母在萱自好，母亡萱尚存。","萧疏北堂下，花叶空晨昏。","盈盈眼中泪，默默心上酸。","眼泪犹可拭，心酸伤肺肝。","安得百丈根，沿情及幽原。"]},{"t":"怡菊周德辉卷","f":"五言古诗","c":["严君去云久，手植已成荒。","促戚远行归，顾眄心徬徨。","言薙蔓草芜，再汲清池潢。","玄功不遐弃，时及仍芬芳。","故物幸兹在，慰悦如有将。","见此聊相慰，笑舞襕斑裳。"]},{"t":"画舫清游","f":"五言律诗","c":["摇摇书画船，渺渺三江水。","朝披越㠐云，暮听吴门雨。","高深洞玄黄，招邀尽青紫。","所愧子长游，吾行未能止。"]},{"t":"草虫杂图四十二首为伍佥宪题 其一","f":"五言律诗","c":["何人涉江采，得此霜前芳。","花残见晚色，叶净流潭光。","长路远莫致，故意不可忘。","欲辍畹中蕙，共佩罗衣裳。"]},{"t":"草虫杂图四十二首为伍佥宪题 其二","f":"五言律诗","c":["南山有佳色，束篱阒无人。","朝为头上花，暮作车下尘。","谁与念恒节，培溉当良辰。","落落竟何语，把玩聊相亲。"]},{"t":"草虫杂图四十二首为伍佥宪题 其三","f":"五言律诗","c":["翛翛苦竹枝，岁晏未凋谢。","络纬绕其颠，促织鸣其下。","秋声入荒林，寒气逗虚榭。","何人赋无衣，悽恻坐长夜。"]},{"t":"草虫杂图四十二首为伍佥宪题 其四","f":"五言律诗","c":["漏石倚空苍，弱草飏残碧。","眷彼飞来双，栩栩飘复集。","鸿鹄志万里，松柏挺千尺。","洪纤各有定，非分焉所得。"]},{"t":"草虫杂图四十二首为伍佥宪题 其五","f":"五言律诗","c":["么红雨馀葩，疏绿风中筱。","虽无尤物丽，得借此君好。","栽培良有待，开落恒可保。","嗟彼桃李花，采折随媚草。"]},{"t":"草虫杂图四十二首为伍佥宪题 其六","f":"五言律诗","c":["形色已葳垂，风神未萧瑟。","所愧落英空，还思旧根发。","时来已若兹，岁去犹尔若。","殊胜汎相逢，随人满头插。"]},{"t":"草虫杂图四十二首为伍佥宪题 其七","f":"五言律诗","c":["茵蔯欲成蒿，蘼芜亦云谢。","水涨污耶深，时蛰看已化。","纤腰尚蜿蜒，弱翅举复下。","婉转如有情，追逐不能罢。"]},{"t":"草虫杂图四十二首为伍佥宪题 其八","f":"五言律诗","c":["暑雨滋宿蘖，五月南风生。","时当长养节，奋臂将谁撄。","奔辙岂足当，黄雀方营营。","幽居事玄穆，相对悲群情。"]},{"t":"草虫杂图四十二首为伍佥宪题 其九","f":"五言律诗","c":["尘境何扰扰，草野何茫茫。","清泉白石处，几许堪徜徉。","兰荃既荣秀，蒿莸绝交相。","宜人不在多，百亩空芜荒。"]},{"t":"草虫杂图四十二首为伍佥宪题 其十","f":"五言律诗","c":["今日胡不怡，过眼青春空。","纷纷萧艾中，见此万绿红。","蜻蜓从何来，当午停芳丛。","物情谅有得，吾意亦从容。"]},{"t":"草虫杂图四十二首为伍佥宪题 其十一","f":"五言律诗","c":["飞蛾值芳时，飘舞来复去。","因风快循绕，逢花亦延伫。","虽临扑逐威，不解摧掠虑。","人意久安閒，相忘不知处。"]},{"t":"草虫杂图四十二首为伍佥宪题 其十二","f":"五言律诗","c":["尺蠖已辞茧，橘虫方化生。","夭夭隰上枝，碧绿纷敷荣。","覆载大有造，动植各相成。","天机一流动，幽思穆无声。"]},{"t":"草虫杂图四十二首为伍佥宪题 其十三","f":"五言律诗","c":["趯趯草间虫，芃芃石边蔓。","跳跃烟冥霏，飘飖翠云乱。","时当绮窗纱，或近青玉案。","卑微宁足论，寂阒聊一眄。"]},{"t":"草虫杂图四十二首为伍佥宪题 其十四","f":"五言律诗","c":["野草绿满地，无名自纤妍。","不采亦不夭，幽与閒相便。","光风濯灵雨，蛱蝶来翩跹。","咄彼周昉图，百态空骚然。"]},{"t":"草虫杂图四十二首为伍佥宪题 其十五","f":"五言律诗","c":["晚家南山陲，独卧西涧草。","牛羊所不践，樵伐非故道。","叶落秋蛾稀，苔滋候虫少。","烟消夕阳下，林薄淡如扫。"]},{"t":"草虫杂图四十二首为伍佥宪题 其十六","f":"五言律诗","c":["蜻蜓多品类，此种最灵黠。","翅翕尾低垂，暂息即飞越。","颇忆童稚年，扑捉伤暑热。","至今图画间，隐手欲轻蹑。"]},{"t":"草虫杂图四十二首为伍佥宪题 其十七","f":"五言律诗","c":["清霜萎茂草，天以虫鸣秋。","股动羽亦振，随处声啾啾。","书斋闭疏雨，木落青灯幽。","掩卷不成诵，感物令心愁。"]},{"t":"草虫杂图四十二首为伍佥宪题 其十八","f":"五言律诗","c":["草振蝶双飞，蝶下草交动。","无情如有情，形势偶相閧。","貌与心不亲，情好久焉用。","悠悠笑相逢，栩栩庄叟梦。"]},{"t":"草虫杂图四十二首为伍佥宪题 其十九","f":"五言律诗","c":["露白水花红，江空草烟暝。","閒鸥忽惊去，见此孤蚱蜢。","吐沫禁无声，卑飞水中影。","虫沙与猿鹤，由来未深省。"]},{"t":"草虫杂图四十二首为伍佥宪题 其二十","f":"五言律诗","c":["飞行罕同俦，性质好幽处。","点水缓捎花，乘风暂停午。","疑回睛屡移，敛息翅频举。","慎尔遇贪夫，求珠瘗当户。"]},{"t":"草虫杂图四十二首为伍佥宪题 其二十一","f":"五言律诗","c":["短翅不高飞，长踦不善走。","跳踉并蟏螽，局缩居泽薮。","三孱不满隅，匹处竟无偶。","彼亦何人斯，蠢尔亦可丑。"]},{"t":"草虫杂图四十二首为伍佥宪题 其二十二","f":"五言律诗","c":["园蔬叶垂尽，练裙弊无馀。","轻扬两飘翅，清嗅双长须。","本质夙如此，变不忘其初。","襕斑五色文，支离守荒芜。"]},{"t":"草虫杂图四十二首为伍佥宪题 其二十三","f":"五言律诗","c":["淅沥蒹葭雨，依微杨柳烟。","翅薄轻纱过，晴隐硝珠圆。","宁当狎雌絷，莫受蛛丝缠。","与物本无患，陈生有遗篇。"]},{"t":"草虫杂图四十二首为伍佥宪题 其二十四","f":"五言律诗","c":["阴阴莞柳树，嘒嘒孤鸣蜩。","惊风飒吹撼，奋翅飞迁乔。","托体虽得所，防患亦须周。","吟风饮清露，此道终逍遥。"]},{"t":"草虫杂图四十二首为伍佥宪题 其二十五","f":"五言律诗","c":["文蛾好明死，乌鲗以蔽彰。","争如草上飞，无用亦无防。","渴饮零露华，逝借晨风扬。","何如蜉蝣群，朝生夕云亡。"]},{"t":"草虫杂图四十二首为伍佥宪题 其二十六","f":"五言律诗","c":["春林盛朝爽，秋圃有暮色。","萧疏丛薄中，缘沿何役役。","凤鸟不时见，良骥须远历。","斑斑被体文，甘老榛莽泽。"]},{"t":"草虫杂图四十二首为伍佥宪题 其二十七","f":"五言律诗","c":["苍茫青草池，霢霂黄梅雨。","清冷脱洿下，润泽非斥卤。","鸣声慎烦聒，跳跃宜审处。","临深纵无危，坐井非善举。"]},{"t":"草虫杂图四十二首为伍佥宪题 其二十八","f":"五言律诗","c":["去彼蜣螂秽，超居风露清。","蜕囊半未脱，健臂已前撑。","潜蛟起泥滓，厉璞登琼英。","大小分已定，变化同其情。"]},{"t":"草虫杂图四十二首为伍佥宪题 其二十九","f":"五言律诗","c":["蟋蟀已在堂，鼠妇已在室。","凉风蕙草时，胡见幽阴物。","仓皇若无依，短褐露肘膝。","天荒岁年暮，感此三叹息。"]},{"t":"草虫杂图四十二首为伍佥宪题 其三十","f":"五言律诗","c":["露滴葡萄寒，宵鸣一何急。","鸡啼天欲曙，络纬不盈尺。","深闺有思妇，远道多倦客。","惊闻长夜声，掩泪心促刺。"]},{"t":"草虫杂图四十二首为伍佥宪题 其三十一","f":"五言律诗","c":["景物此何处，野塘秋色中。","山花惊暮雨，芦叶抱寒虫。","旷望知谁到，幽居重此逢。","怀人不可见，双鬓感飞蓬。"]},{"t":"草虫杂图四十二首为伍佥宪题 其三十二","f":"五言律诗","c":["金谷多奇花，蝶满谢即去。","荒园久空疏，蜂蝶亦安素。","迟回杞菊秋，栖息松桂暮。","所以君子交，清澹只如故。"]},{"t":"草虫杂图四十二首为伍佥宪题 其三十三","f":"五言律诗","c":["原野多蔓草，墟泽饶鱼虫。","一枝与一体，入笔殊元踪。","生憎红紫态，未觉丹青工。","坐我林塘下，衣袂生华风。"]},{"t":"草虫杂图四十二首为伍佥宪题 其三十四","f":"五言律诗","c":["风高芦叶残，赢露失其翳。","鸣蜩已绝响，犹奋双斧臂。","犹豫多积疑，蜂虿无却虑。","君子尚勇决，成败焉足计。"]},{"t":"草虫杂图四十二首为伍佥宪题 其三十五","f":"五言律诗","c":["飞来锦纹蝶，采翅何翩翩。","山花吐碧蕊，相映亦相妍。","动植互生化，寒暑频推迁。","生绡有遗迹，日日当吾前。"]},{"t":"草虫杂图四十二首为伍佥宪题 其三十六","f":"五言律诗","c":["蝶有恋花情，花无留蝶意。","东风三月时，总为春流丽。","还开亦还落，欲去还不去。","默诵过墙诗，重门草深处。"]},{"t":"草虫杂图四十二首为伍佥宪题 其三十七","f":"五言律诗","c":["意会自成趣，景触良宜时。","过影如见人，飞音若我遗。","荒閒寂寞滨，独悟胜群思。","此兴复不浅，名物空何为。"]},{"t":"草虫杂图四十二首为伍佥宪题 其三十八","f":"五言律诗","c":["尔雅列名称，埤雅伸疏义。","恢恢造化功，独此亦难备。","况当画史传，舐墨随手至。","骊黄牝牡间，不必问形似。"]},{"t":"草虫杂图四十二首为伍佥宪题 其三十九","f":"五言律诗","c":["动听非谇语，适目无妖妍。","诗求句律外，画索丹青前。","尺素竟何物，居然得天全。","相彼能事者，殆欲忘朱铅。"]},{"t":"草虫杂图四十二首为伍佥宪题 其四十","f":"五言律诗","c":["乐水不论船，乐山不问树。","不求画中物，惟耽画中趣。","想当含毫时，粉墨不待具。","眼光落缣素，但觉风雨至。"]},{"t":"草虫杂图四十二首为伍佥宪题 其四十一","f":"五言律诗","c":["滕王去云远，谢逸今何之。","形迷有声画，影落无声诗。","低回罗扇风，旋绕簪花枝。","转眼忽不见，芹香满清池。"]},{"t":"草虫杂图四十二首为伍佥宪题 其四十二","f":"五言律诗","c":["形色既有托，音声寂无闻。","乍出草莽中，昂藏若离群。","涵濡竹露华，饱挹山花薰。","时哉忽如许，彼美空云云。"]},{"t":"沈启南云山图","f":"五言古诗","c":["晨兴具壶榼，言往山中游。","倚棹陟崇冈，舒眺写我忧。","阴云翳四垂，举目迷岩丘。","人生百年事，行止天为谋。","欢荣间悲辱，强半成淹留。","眷兹山水怀，所遇亦已酬。","自从混沌凿，土石穷雕锼。","镌坚伐危厉，辇筑连洼湫。","幸此玄黄间，元气常通流。","时当巧丽馀，忽与鸿蒙游。","行看晦暝甚，转觉巉岩幽。","情景两相化，风雨飘虚舟。"]},{"t":"吴德翼永思诗","f":"五言古诗","c":["夭夭岩下椿，嫩发方自好。","终风激零雹，凋拉何太蚤。","伤哉三尺孤，形影为枯槁。","虚室若悬磬，遗业忽如扫。","遑遑二十年，赖此王父考。","昔如风中蓬，零落随野草。","今如辕下车，奋脱即远道。","登堂泣孤帏，陟岵见归鸟。","荣枯不相代，忧伤已终老。"]},{"t":"送欧员外","f":"五言古诗","c":["蓟城有名士，美盛元无前。","手抉云汉华，身交文锦妍。","目烂明月珠，口涌悬河泉。","幽思入玄默，清臭纷兰荃。","初辞鹿鸣宴，再坐琼林筵。","朝主地官事，暮副郎中权。","骐骥志万里，鸿鹄怀高骞。","良金与美玉，适用无停延。","遥遥吴越乡，雨涝如尧年。","雍雍少司徒，王命来旬宣。","行哉自求辅，得此堂中贤。","六属倡九牧，一士当三千。","蒙冲籍篙楫，禆曲严中坚。","激扬水趋壑，鼓振雷行天。","钧衡赖持举，皇度资纯全。","遂令泥滓民，复业膏腴田。","一朝十二解，芒锐犹森然。","裴向多谏议，之问馀诗篇。","时登两峰月，暂汲西湖烟。","双旌即归路，一束携行编。","加餐赤日饭，稳著青云鞭。","行舟如有问，干事江南旋。"]},{"t":"为胡文晖题幽篁石菊图","f":"五言古诗","c":["故人归田园，几许见秋节。","修篁荫中林，时菊丛以发。","冉冉烟中花，萧萧石边叶。","秀色如可餐，幽馨寒不绝。","时有素心人，同来醉明月。"]},{"t":"何都宪一乐堂","f":"五言古诗","c":["椿萱茂迟秀，棠棣偕春芳。","煌煌锦绣衣，烨烨斑斓裳。","恩封日以至，甘旨日以将。","齐眉粹荣养，竞爽时行藏。","载歌蓼莪咏，载诵鸰原章。","前修有遐感，而我承馀康。","欣抃不能已，万事真相忘。"]},{"t":"丛蕙图","f":"五言古诗","c":["二月忽已迈，庶草三春时。","九畹有馀秀，百亩多芳蕤。","光风转幽馥，湛露增华滋。","筼筜拂琨璞，揭车被留夷。","朋从汇如故，气质相交䕻。","手抚宣尼琴，再诵骚人词。","时哉未终老，荪芷来何迟。"]},{"t":"凝香阁画菊","f":"五言律诗","c":["幽斋绝秾纷，时菊閒以洁。","少好淡春芳，敷荣及秋节。","髧鬈宁尔妆，袪袂无所撷。","枯索绕残枝，天寒满庭月。"]},{"t":"清燕室画菊","f":"五言律诗","c":["佳节良易迈，贞姿益清芳。","根依昆玉固，色并淇筠苍。","终忘白衣酒，特立金娥霜。","幽馨不出户，憔悴含馀香。"]},{"t":"一山为沈兑秀才题","f":"五言律诗","c":["人言一拳石，积累成丰隆。","为山将九仞，篑缺亏前功。","巍巍圣与贤，养正由童蒙。","登泰小天下，卓立超群峰。"]},{"t":"和陈宪副扫墓诗","f":"五言古诗","c":["游宦日已久，先陇多违离。","寥寥古东门，值此洪流时。","颓垣走狐兔，宰木寒无枝。","及目心隐只，俯仰泪交颐。","野祭已非古，况复无恒期。","恩封夙有泽，贫丧空无施。","徬徨不能返，日落凄风悲。"]},{"t":"南山荣寿诗寿杨方伯父怡梅翁","f":"五言古诗","c":["维南有崇山，盘亘自终古。","高当翼轸间，广与衡岳旅。","中有千岁梅，生长元得所。","英华彻寰区，贞素贯寒暑。","开花玉香丛，结子金色颗。","德馨椒桂俦，滋味鼎鼐主。","繁葩尽芬馥，再实愈清楚。","荣封异秦松，拔萃超庾土。","上与山同跻，下与地常处。","蟠桃与庄椿，千岁可能数。","焉知世奇树，亿祀老玄圃。","卓哉同春翁，怡怡并遐祜。"]},{"t":"四月二日西湖再汛四首 其一","f":"五言古诗","c":["春去才一日，天宇寻清和。","湖草犹碧色，湖水馀澄波。","安能对佳山，不饮空嵯峨。","邻船留宿欢，皓齿发清歌。","推窗动孤笑，吾意其蹉跎。"]},{"t":"四月二日西湖再汛四首 其二","f":"五言律诗","c":["沿舟望湖亭，蹑屐栖霞岭。","孤山久寂寥，荒冢郁清迥。","渚蘋清不香，湖水浑未瑩。","悠悠登荐心，长叹逐游泳。"]},{"t":"四月二日西湖再汛四首 其三","f":"五言古诗","c":["乐天唐诗杰，子瞻宋文豪。","平生宦游事，山水遗清高。","何人继芳躅，保障心思劳。","坐令百折堤，土木连平皋。","虽无百年固，已足千金牢。","茫茫荡游子，醉谑空呶呶。"]},{"t":"四月二日西湖再汛四首 其四","f":"五言古诗","c":["西湖天下奇，登泛极寒暑。","晨行暮酣归，昏遽一如许。","何殊浪游客，对此汎交主。","面接情不通，日醉鸡与黍。","谁哉神识高，偕协如索与。","茫茫丹青家，忽忽歌曲侣。","安能千日游，玄晏坐风雨。"]},{"t":"为仲彦晖题戴文进画","f":"五言律诗","c":["故人归田园，风景如未别。","时菊老馀芳，疏篁晏高节。","皇皇枝上花，潇潇石边叶。","安得素人心，清尊对明月。"]},{"t":"为徐公举题甘谷图","f":"五言律诗","c":["南阳古甘谷，菊绕渊泉清。","居人饮其流，白发咸康宁。","明徵谅无爽，穆穆中庸生。","君当衍馀泽，为我延颓龄。"]},{"t":"陆汝嘉慕橘","f":"五言律诗","c":["伯父去已远，遗植森成行。","哀哀抚育恩，见树生悲伤。","所愧为人后，凋落迷前芳。","愿言慎伐剪，念彼椿萱长。"]},{"t":"画舫清游卷","f":"五言律诗","c":["摇摇书画船，渺渺三江水。","朝披越峤云，暮听吴门雨。","高深洞玄黄，招邀尽青紫。","所愧子长游，吾行未能止。"]},{"t":"松泉为朱彦明赋","f":"五言古诗","c":["亭亭山上松，挺挺凌云标。","涓涓山下泉，混混东归流。","根源夙有托，高远群无俦。","洵美山中人，寓迹山之幽。","栽培与盈进，比则事藏修。","朝登玄鹤岑，夕汲青蘋洲。","巢居漱芳润，亦足忘吾忧。"]},{"t":"王汉昭招予社友辈赏雪即席纪事","f":"古风","c":["癸丑至乙卯，连岁无快雪。","新冬十月来，晴久犹郁热。","蚊蝇振时声，雷电迷夏节。","晚麦未出土，春卉复舒结。","老夫坐空斋，感此心隐切。","仲冬十踰八，风?夜慄冽。","黎明未启户，帘牖光洞彻。","庭乌栖不啼，窦犬走欲蹶。","昏眸眩珠霏，短发耀琼屑。","寒疑银海翻，冻讶玉楼合。","昨日方袒跣，今晨被重褐。","如行炎都深，忽上冰山绝。","吾闻阴阳机，寒燠恶凌夺。","天吏秉常运，旋斡何太捷。","事若久旱馀，甘雨大沾洽。","行期十年丰，底用三尺叠。","故人同老怀，鸡黍充宿业。","欣开北海尊，笑广南州榻。","酬酢乱觥筹，诙谐连稗阖。","罐唱叱郑妓，羔饮诧党妾。","狂怀锦瑟醉，渴罄凤团啜。","客思暝未阑，主意夜不辍。","似有暗香来，援毫待明月。"]},{"t":"兰竹篇","f":"五言古诗","c":["幽兰发深谷，修篁生茂林。","托根偶相并，香霭凌繁阴。","逢时苦不早，霜雪纷相侵。","耻为桃李妍，眷怀金石心。","幸此平安意，起坐弦吾琴。"]},{"t":"咏张汝庸环秀楼","f":"五言律诗","c":["人境苦尘俗，高居山水区。","轩楹出岑蔚，窗户凌清虚。","左挹群木华，右眄云烟舒。","日夕有佳趣，萧爽真吾庐。"]},{"t":"玩芳亭","f":"五言律诗","c":["东风吹野花，秋雨败蘼草。","彼美亭中芳，静植恒自好。","阶兰閒更香，篱菊淡如扫。","我欲掇其英，幽怀不堪道。"]},{"t":"小蓬壶","f":"五言律诗","c":["弱水不可航，神山未知处。","閒居与世隔，仙境忽已遇。","百岁等须臾，万事归傲睨。","丹丘信自有，大小焉足计。"]},{"t":"长春境","f":"五言律诗","c":["迟迟松柏林，郁郁山水窟。","依依久住人，宛宛旧游客。","人客不改心，山木不改色。","彼哉同州庸，华蘼何所择。"]},{"t":"葡萄二首 其一","f":"五言律诗","c":["邛竹与枸酱，追逐秋风来。","离宫郁相望，异物纷栽培。","遂令凉州牧，斗酒遗诙谐。","伤哉出关卒，不及枯株回。"]},{"t":"葡萄二首 其二","f":"五言律诗","c":["草龙骄正眠，骊珠烂将堕。","清露溥花间，凉风生叶下。","悠悠日观翁，萧萧友云者。","我欲掇其英，阳春和应寡。"]},{"t":"杨廷宪修障海塘妙得古法但百世之工非朝夕可致所冀增高倍厚坚表实里迟之以岁月庶可持久诗以寄之","f":"五言古诗","c":["吾闻浙江潮，涌撼世莫比。","回流趣盐官，一射数百里。","海盐当其冲，适际东北趾。","何年作长防，去郭数丈许。","叠石类悬崖，壁立瞰其涘。","刳中实外障，高岸湮入水。","表里河海间，相隔才一指。","譬如溃瓜形，皮好肉已毁。","潮来石奋角，潮缩石拔齿。","时平渐离缺，风迅遽披靡。","工役岁无涯，漂荡日常耳。","皇皇鱼鳖民，藐藐轩裳子。","剥床不及肤，解牛未得理。","岂无达务才，遗我徒好语。","使君人中英，万物备一已。","询咨度豁如，瞻顾心隐只。","秦鞭竟空谈，汉縆无用此。","轩然巨鳌侧，坦若长坡迤。","罅漏互蔽亏，力势相并倚。","盈不与潮斗，缩不随浪委。","肉厚骨不疏，腹饱背复偻。","何期既倒阔，忽见急流砥。","但恐述者能，不类创智美。","速成功易隳，举重力易弛。","安得百使君，历岁如大禹。"]},{"t":"水南别业四首 其一","f":"五言古诗","c":["幽居异前业，喜无尘俗喧。","东风扇微和，忽此春事繁。","游鱼汎深沼，好鸟鸣檐端。","布谷正及时，呼童理荒园。","群动各有为，予生固多般。","感之欲自见，对景已忘言。"]},{"t":"水南别业四首 其二","f":"五言古诗","c":["远村暑气薄，衡门绝尘鞅。","禾黍满污邪，松篁翳林莽。","富贵复何心，琴弈偕所往。","起诵康衢谣，悠然发遐想。","薰风自南来，坐我羲皇上。","慨彼河上翁，所乐异天壤。"]},{"t":"水南别业四首 其三","f":"五言古诗","c":["夙昔爱林壑，遂怀泉石居。","下焉安所适，上焉荷唐虞。","无穷毕日欢，耻与放浪俱。","此意不自昧，付之耕凿馀。","秋凉入林薄，时复课儿书。","先民有遗诏，经训乃菑畬。"]},{"t":"水南别业四首 其四","f":"五言古诗","c":["白发念婚嫁，此虑已陶然。","匪复事生业，烝尝讵能捐。","怅望终南山，缅怀清渭川。","良时易流迈，穷约心所安。","严阴閟深谷，飞雪层崖巅。","引酒聊自酌，被褐终吾年。"]},{"t":"为邵同府题山水图","f":"五言古诗","c":["秋风吹乱云，凉露润修竹。","林深枫叶静，石烂雨苔复。","青山断平野，流水泻虚谷。","菀彼山中幽，怅此暮行独。","希声振清啸，灏气凝远目。","澄光发精爽，空翠袭巾服。","时看夕鸟举，偶晤春莽宿。","功名忽如遗，志念聊可复。","俯视尘中人，扰扰随转毂。"]},{"t":"沈用权月桂图","f":"五言古诗","c":["月中有奇树，百丈何茏璁。","岁年等蟠桃，樛结扶桑同。","下垂白玉苞，上发黄金丛。","翘翘最高枝，花色赪霞红。","我昔至其所，顾眄迷仙踪。","高攀不可及，屈折聊相从。","归来抱馀馥，气韵归鸿蒙。","一登阊阖门，再致昆崙峰。","芬敷及朝槿，断谢随秋蓬。","至今怀袖间，敛缩心冲冲。","有美青云彦，飞策凌虚空。","逍遥广庭晏，彳亍嫦娥宫。","含咀玉杵霜，披拂纤阿风。","手持斫月斧，气吐经天虹。","奋掇连根株，五色俱收笼。","拔茆采葑菲，类举无遗功。","愿子即长路，吾行已途穷。"]},{"t":"送陈彦章还温州","f":"五言律诗","c":["悠悠远行休，忽忽垂老别。","一去湖山空，百会亲故绝。","凉风吹鬓丝，颜意各惨切。","永毕同心欢，忘言共明月。"]},{"t":"朱彦明新居","f":"五言古诗","c":["椿庭日已远，萱室怀深忧。","岂不念故庐，听此行道谋。","嗟彼喧杂区，居子非良繇。","一劳堪久逸，三迁遂吾求。","经营与缔造，冀足光前猷。","正寝卓跂立，旁居翼相周。","祠室具笾豆，斋阁陈箕裘。","南荣叙亲友，北堂荐时羞。","苟美载论语，过侈遗春秋。","慈颜日迟暮，良偶方徽柔。","房闼肃清密，户牖森绸缪。","声色起淫荡，势利生仇雠。","祸福相倚伏，贫富潜周流。","君子常抑畏，小人肆张诪。","孝弟与忠信，自足禦戈矛。","升堂有端士，入室无狂浮。","不见陵上柏，远翠凝疏标。","不见路傍桃，妖艳侵行眸。","居养易移习，内外须交修。","愿保安宅固，千春永馀休。"]},{"t":"为王瑞之作雪图附诗以寄","f":"五言古诗","c":["岁序行已周，天寒日将暮。","门户了无营，山林阒如故。","彤云被层空，时雪纷已堕。","玄冥涤群华，过眼一纯素。","风恬晚声寂，古气塞窗户。","贞居久遗旷，值此忽超悟。","呼鱼烟外汀，沽酒桥北路。","烹鲜酹华月，妇子环榻坐。","清歌振冥寂，真态忘陋固。","悠悠百年中，清赏亦有数。","劳思竟何禆，快意欣所遇。","犹怀见睨馀，流想鸿迹去。","望望剡溪舟，苍茫是何处。"]},{"t":"画元章拜石图附一诗","f":"五言古诗","c":["吾闻周人拜，九辩各有则。","空稽犹简易，振肃仪已极。","礼达百不烦，力致一可惜。","苏卿抗匈奴，郑从厉绝域。","亚夫辞介胄，汲黯服长揖。","生死矢不移，宠辱安所恤。","云胡后来者，软媚等难剧。","望尘伏床下，不复论曲直。","黠以谄公卿，愚以祈老佛。","颓流逐靡风，扫地尽古迹。","元章夙奇荡，动止异俗习。","强项难苟俛，扪膝不轻屈。","自从辞君亲，久不为是役。","落落无为乡，寥寥不齐邑。","伊谁与为礼，见此孤立石。","飒焉松风生，隐只云雾出。","踞如猛虎化，厉若老蛟蛰。","彷佛入鲁庙，正我缄口客。","又疑千秋亭，翁仲失其一。","终知混沌凿，倏忽委灵骨。","欣然命袍笏，雅拜情孔适。","物我了相忘，恭傲吻无隙。","清狂讵如许，深意将有激。","全胜彼昏人，仆仆贾危慝。","但恐违中庸，行怪不可率。"]},{"t":"赵千里小景二首 其一","f":"五言律诗","c":["庭院寂无人，冥怀共谁语。","和风入蓬户，桃李似无主。","妍华岂足怜，幽旷真足与。","呼童抱瑶琴，静对松篁雨。"]},{"t":"赵千里小景二首 其二","f":"五言律诗","c":["茂树荫碧草，莓苔连砌青。","山童拥敝帚，洒扫当前楹。","行吟白鹤词，坐览黄庭经。","良时苟未迈，笑傲终吾生。"]},{"t":"张叔厚谢安渊明图二首 其一","f":"五言律诗","c":["度量本知识，器局先文艺。","款笑息群嗔，泠汲止馀沸。","优游别墅棋，閒逸东山妓。","时方竞名达，出处有馀地。"]},{"t":"张叔厚谢安渊明图二首 其二","f":"五言律诗","c":["翩翩晋徵士，夙志山与泽。","心远趣自高，松菊亦何物。","斗酒不身致，况此名利役。","冥鸿在万里，岂为督邮迫。"]},{"t":"袁可筠风水永怀","f":"五言古诗","c":["皋鱼感风木，立哭悲其亲。","哀哀千载下，予复同兹辰。","林木一何多，天风一何疾。","本是无情吹，能令有情泣。","风水有时息，逝者无归期。","依微耳中响，绸缪心内思。","心思不暂缓，岁月忽已远。","落叶下庭闱，山荒夕阳晚。"]},{"t":"为吴玉甫侍御题芙蓉图","f":"五言古诗","c":["志士怀寂寥，佳人念迟暮。","本与秋风期，不悟春已去。","嫣然如有情，暄妍发寒素。","红摇碧潭水，绿掩黄叶树。","垂垂翠帐烟，冉冉锦城路。","试问涉江人，相思在何处。"]},{"t":"宝剑篇","f":"七言古诗","c":["干将在匣神鬼惊，土花绣涩含苍精。","千年地下灵不死，万丈烛天牛斗横。","壮夫入佩心相许，唾手功名轻一缕。","倚天长笑气食牛，誓斩楼兰扫尘雾。","归来献馘朝宸旒，奋言先落佞臣头。","河清海晏颂声作，乞身复向西山陬。","我歌宝剑声如吼，飒飒英风生两肘。","丈夫作事贵轩昂，肯向蓬门甘老丑。"]},{"t":"和孙廷珍侍御短檠歌","f":"七言古诗","c":["中庭烧檠多更长，金缸列钱绕屋光。","红荧朱烬耿欲灭，酒酣试问西堂凉。","美人矜醉炷罗带，照拂氍毹铺绣床。","东邻少年曳裙客，收束韦编二三策。","呻吟佔毕短檠空，光青夜寒秋月白。","佳儿在后翁在前，轰雷震起双龙眠。","凤膏不复延骄恣，绿幕绡红烟扫翠。","短檠犹照旧时人，翻惜长檠便沦弃。"]},{"t":"送张永清下第南归","f":"七言古诗","c":["长安花落莺声老，送别都门心草草。","白璧由来惜暗投，俗眼相看不知好。","读书十载未成名，落日辞家仗剑行。","飞腾已遂丈夫志，离别无为儿女情。","黄金高台插天起，台下行人思郭隗。","千里元从骏骨来，躁进纷纷徒已尔。","负郭田荒草蔓滋，嫂不停机妻不炊。","一朝唇颊惊六国，腰间金印何累累。","纵横游说非吾有，汗简功名在人手。","干将未出狱中泥，犹有神光射牛斗。","出门有碍情悽恻，不是长安看花日。","进退枯荣事偶然，欣戚何须动颜色。","冠盖相逢自有期，君归应惜少年时。","浮云流水天涯路，回首令人千万思。"]},{"t":"题钓鱼图勉许瑛","f":"古风","c":["生不见渭水渔翁发垂白，欲事纶竿死岩泽。","一朝天子梦中求，兆协非熊年八十。","又不见子陵垂钓富春山，万事无心天地閒。","客星一夕犯帝位，羊裘拥入鹓鸾班。","古人出身有如此，却笑今人徒已尔。","生意何须南亩田，世情付与东流水。","况汝持身当有为，读书正遇少年时。","饭囊酒袋人不数，凤雏麟子真吾师。","我昔成童游泮学，雪案萤窗自磨琢。","但愿才名播缙绅，焉知冻馁填沟壑。","迩来踪迹虽淹留，襟怀不作青云愁。","丈夫处世贵廓落，何用浮鸥一钓舟。"]},{"t":"伍子胥渡江图","f":"七言古诗","c":["壮气横空欲吞楚，半夜函关出虓虎。","城中追骑若行云，泉下孤臣泪如雨。","江头立马寒飕飕，江神吐泣皇天愁。","捐躯甘作异乡鬼，誓死肯忘同天雠。","何来老父伤羁阻，舣棹招摇夜相渡。","百金宝剑辞不收，万石功名草头露。","雄兵一旦下吴台，楚国山河半草莱。","旧主已随烽火遁，将军犹入故宫来。","秦庭泣血昭王返，白苧歌长越兵远。","夫差夜饮欲烹龙，句践宵衣正尝胆。","零落䲭夷百战身，姑苏麋鹿漫伤神。","君看楚郢鞭尸客，应是吴门抉目人。"]},{"t":"庚午秋日游忠显寺寺僧设酒殽款曲甚至临别出画马小图一幅索予赋诗予既被酒奋笔以寓所怀","f":"七言古诗","c":["房星夜堕渥洼水，八尺龙骧就中起。","一朝职贡入天闲，蹀躞康庄五云里。","尾长窣地香尘浮，目光夹镜寒不流。","千金之价不足数，顷刻万里能周游。","奚官牵出连钱动，仰首长鸣金勒重。","乌骓赤兔尚腾骞，骥騄乘黄伏翔踊。","玉门关外苜蓿肥，黄尘白草相依微。","何当汗血向沙漠，奋身霄汉随龙归。"]},{"t":"送赵士英下第南归","f":"古风","c":["薰风五月都门道，送客临岐心草草。","天涯转觉故人稀，对酒难忘旧乡好。","忆惜随君歌鹿鸣，风流文采超群英。","当时科第已晚出，岂谓岁月犹相仍。","浮云聚散十四载，华发青衫走湖海。","造物婴儿解弄人，连城美价宜深待。","蹇余三举偶春闱，西抹东涂空耳为。","一从窃禄黄门下，几度怀君沧海湄。","前年待试留京阙，旅馆琴尊共谐洽。","金印犹迟相国归，貂裘又作还家别。","知君怀抱世所无，冰瓯玉碗青珊瑚。","平生慨慷伏奇节，得失岂肯轻欢呼。","朅来浪迹长安陌，剔隐钩玄恣抺索。","下穷元宋上羲皇，大者经纶小占策。","醉酣咳唾落珠玑，三峡词源百万师。","盛唐诗句何冲澹，西汉文章宗典彝。","向人掩口谈科举，不肯低头随进取。","今学宁知古学醇，誉则为忧憎则喜。","君不见贾生一岁屡超迁，鹏上承尘才少年。","梁灏登科尽头白，位望虽迟年八十。","疾随美恶互乘除，天壤生成无弃物。","何况君怀越世才，云霄有路待君来。","明年五月薰风动，准拟乘舟海上回。"]},{"t":"为刘浚渊同年题古松图","f":"七言古诗","c":["云山高高凌紫空，上有偃蹇千年松。","苍颜不变太古雪，密叶晴翻长夏风。","玄萝紫蔓阴相翳，错落盘根枝著地。","月明白鹤误飞来，烟散青牛忽无处。","由来奇物重冥搜，变化追寻未可留。","徂徕山下黄尘暮，太谷坡前碧草秋。","只今廊庙求梁栋，梓柏楩楠皆入贡。","会见巉岩出万牛，茯苓琥珀皆登用。"]},{"t":"送仲指挥南还","f":"七言古诗","c":["去年送君春已过，花落莺啼蓟门路。","今年仍作远游人，风雪还家岁行暮。","滦河半夜渡层冰，千里淮扬十日程。","杨子江头沽酒宿，蓟门树里听鸡行。","到家应近元宵节，细柳营边新草发。","刀斗无声清夜长，旌旗有影蛮烟绝。","去年携酒送君时，有约封侯来更迟。","今年复送长安客，却忆从前送别诗。"]},{"t":"听鹤老人云山图","f":"七言律诗","c":["东方欲白天冥冥，宿云未敛朝烟生。","前山后山半昏晓，千树万树迷阴晴。","淋漓元气寒犹湿，上下苍茫太初色。","房山去后已无人，野屋荒林见遗迹。"]},{"t":"刘廷器云山图","f":"七言古诗","c":["风流太守竹鹤翁，平生雅重真襄公。","公方司马掌邦政，邂逅相见都门中。","酒酣为写江南意，超忽家园坐中致。","清风未许北窗眠，白头持赠东床婿。","高堂素壁悬清秋，举目直欲穷冥搜。","天高地迥望不极，水漠山冥看欲愁。","初疑苕溪二三月，桑柘连村雨时歇。","阴晴未定禁蚕天，烟火萧条来往绝。","又疑西湖夜向晨，朝氛宿霭迷空尘。","隔林灯火读书晓，满地落花风雨春。","兴来欲趁扁舟渡，苍茫不见行人处。","鸥波亭上是耶非，放鹤坡头到曾未。","连云天栈乱石滩，处处逢人行路难。","鉴湖盘谷远莫及，安得此境终盘桓。","何翁山水真足数，此幅由来倍清古。","粗毫淡墨意自适，未必经营心独苦。","子昭舜举直细工，元晖彦敬高同风。","世间能事不受迫，识画惟有青鞋翁。"]},{"t":"边景昭画马为刘廷器题","f":"七言古诗","c":["陇西边生写生者，拓得唐时紫骝马。","赤骠青骢却不前，白鼻乌骓价斯下。","想见开元全盛时，海宇无尘战争罢。","七十万疋锦成阵，十二天闲沫流赭。","从来主管张万福，底用诛求王母寡。","民间自可一缣易，官里或许儒臣假。","众中骏逸知几何，此马翻然空冀野。","天机只许九方识，骨法直须曹霸写。","未辞羁絷欲腾骧，步入艰难便閒雅。","当时死骨亦奇货，此画千金如土苴。","眼前谁是按图人，苜蓿秋风漫盈把。"]},{"t":"为伍公矩题画二首 其一","f":"七言律诗","c":["晴空澹澹飞鸟没，野水连天月初出。","人间天上不胜秋，一片烟波夜如日。","杜陵老病卧孤舟，醉倚蓬窗看水流。","满怀灏思无人会，惟有清光照白头。"]},{"t":"为伍公矩题画二首 其二","f":"七言律诗","c":["荒林野树连高障，青山半出青云上。","谁分折水下昆崙，一道垂流几千丈。","纷纷短发吹秋风，注目可似青鞋翁。","高山流水知音少，却忆庐山五老峰。"]},{"t":"为孙宗礼题画","f":"古风","c":["巍峨泰岳当空起，齐鲁苍茫青未已。","东连奎壁下平林，白石神鸡鸣泺水。","近峰砥柱高插天，远山如砺含苍烟。","就中绝壁千万仞，青萝紫蔓垂飞泉。","上方楼阁凌霄汉，叠榭回廊环赤岸。","桧柏阴森灏气深，杉松半映岚光见。","依微下界入芳蹊，蹊上人家四望迷。","树影匝檐晴亦雨，鸟声当户歇还啼。","野桥鸣濑通幽谷，小径荒凉闭茆屋。","屋底幽人不出门，十年心事书千束。","清风明月澹悠悠，野鹤林猿寂寞秋。","英华不与世同泯，意气直欲穷冥搜。","云雷一旦生林壑，凤翼腾霄虬奋角。","石田花野迹萧疏，青琐黄门事轩豁。","自从恩谴赋西行，万里关河百感生。","落日咸阳一回首，尽是乡山离别情。","今年天上阳春布，赐归却踏来时路。","旧游松菊未全芜，去日门墙尚如故。","北山何必诮移文，南亩还应卧白云。","晓雨移舟鸥近渚，晚凉开圃鹿成群。","从来宦达怜长往，得失荣枯共萧爽。","白璧终藏志已非，赤松相候真成妄。","君不见郑子真，平生散逸无怀民。","又不见贺季真，鉴湖一曲辞朝绅。","穷通出处只如此，高尚岂必双朱轮。","古人风致何殊绝，昭代求贤甚如渴。","彦博衰微尚入朝，仲舒老去犹持节。","重来事业不须期，招隐诗成欲寄迟。","乱峰残雪梅花夜，好忆咸阳西去时。"]},{"t":"刘缓斋同甲会诗","f":"七言古诗","c":["潞公昔为同甲会，四老煌煌尽时贵。","如何不见布衣人，可是名高绝流辈。","功名富贵如浮云，眼前谁是无怀民。","康衢却喜儿童语，寿域须教草木春。","太平四海归皇极，道统光华连出日。","一百年来养育恩，普天率土皆头白。","海滨野老何萧然，风流不让他人前。","十人六百二十岁，同甲相看真自怜。","僧非凡僧俗非俗，踪迹虽殊志相足。","圭璋璜瑾与璠玙，总是良田万金玉。","就中一老何雍容，鸡群野鹤孤飞鸿。","丰姿不减紫芝叟，文采或遇青藜翁。","锦肠沁透金壶墨，鬓丝半映笼鹅白。","赤壁山前醉月明，垂虹亭下眠秋夕。","江南十月天未霜，寒花晚节生馀香。","重阳无雨一冬霁，十有九日如春阳。","楚芳老禅好奇事，便托丹青写幽思。","相邀同甲赴同盟，遇水乘舟陆乘骑。","山殽野簌充行厨，传觞促令相歌呼。","林间似有鬼神动，青天湛若星辰孤。","功名富贵知何有，万事纷纷尽刍狗。","千年一度黄河清，几人解饮同年酒。","古来戊子与甲辰，大小雌雄何足陈。","清风素节图中事，一笑浑忘洛下春。"]},{"t":"欧时熙家山图","f":"古风","c":["我闻庐陵风景天下无，孤峰耸绝凌荆吴。","东南两山互昏晓，日月重冈森蔽亏。","龙洲却过太和县，武峰卓立香城居。","地灵宜有杰人出，举目便觉江河殊。","六一仙翁呼不起，高节清风照桑梓。","乡里于今说故家，诗书有泽遗孙子。","芬芳玉树被中庭，辟易名驹在千里。","黄甲题名气吐虹，太微执法心如水。","远别庭闱今几年，孤云望断旧山川。","青阳宛宛白日暮，一顾魂魄俱茫然。","馀情散入大江水，归梦正落幽林前。","林中老人年七十，面渥童颜发凝漆。","华屋山中宰相家，锦衣天上神仙客。","生儿蚤入鹓鹭行，投老不忘山水窟。","百岁优游自可期，故园风物正芳时。","悠悠忠孝丈夫事，荣枯利达真儿嬉。","太行山上瞻云客，应有房陵西去思。"]},{"t":"听潮轩","f":"七言古诗","c":["海门荡荡天风来，云潮千里如山推。","空雷隐地雨将作，万鼓齐伐车喧㒮。","初疑群蝇争振翼，忽若洪炉沃汤液。","风回籁歇如渐远，兵马萧萧走勍敌。","年去年来似有期，春秋长落几人思。","天涯共道初来惧，梦里空惊夜雨时。","海滨老禅得幽趣，禅居正近潮来处。","山空水落境无人，地迥天高岁云暮。","尘缘断绝双耳清，天机自动非人声。","上方钟梵随风散，下界楼台孤月明。","风微月朗众将定，将定犹闻心转静。","来非有为去无情，留连世韵何须听。","见说空轩百事无，音声色相尽成虚。","禅家自有西来话，莫向中洲说六如。"]},{"t":"松竹梅图","f":"七言古诗","c":["西风吹满空山雪，草木摧残众芳歇。","方春三月二月时，锦片韶华逐飞叶。","岁寒心契百年期，凌云老干凝烟枝。","萧条墙角半枯树，何事忽见琼瑶姿。","寒香晚色迷幽绿，半入前溪半茆屋。","翠禽啼梦蛰龙惊，白鹤叫霜仪凤宿。","秦封晋逸两悠悠，人在西湖已倦游。","炎凉不改固穷节，老大真成时辈羞。","炎凉老大随时至，毕竟谁非与谁是。","惟有从来铁石心，风烟雪月都相似。","红尘满道踏歌声，谁向穷荒访旧盟。","陇头不寄平安报，湘曲应孤驿使行。","明堂近复来梁栋，筱簜琅玕尽登用。","却疑羌笛妒人来，一曲关山又三弄。"]},{"t":"夏仲昭万竹图为师知县题","f":"七言古诗","c":["昆山老叟仙中人，清和洒落无纤尘。","平生富贵不足道，笔挽造化回阳春。","坡真可妙真堪惜，老息森严露形迹。","鸥波亭外寂无人，九龙山气凌秋碧。","山气凌秋势薄天，凝云挟雾快腾骞。","巉岩峭壁几千仞，此老直欲穷其巅。","金闺琐闼瀛洲路，宣德年来誇独步。","名高价重不复疑，世间托笔应无数。","枝干依稀丛叶同，天机妙解却难工。","就中一片飞白石，烂然琢玉寒玲珑。","蹇予最好潇湘景，见画令人发深省。","曲处疑闻爽籁生，深中似觉阴风冷。","深曲低昂路郁纡，幽情欲尽似还馀。","三湘逐客归来未，二女游魂今在无。","从来能事不受迫，醉里兰亭难再得。","使君此幅自何来，万金宝剑连城璧。","半窗疏影对愁眠，斑管春寒诗思牵。","玉蝉吟吸鹧鸪雨，文绡细簇玻璃烟。","却思京国频相见，自谓相求当不厌。","岂料公归绿野堂，至今误我鹅溪绢。","江南菉竹漫成林，山县鸣琴白昼阴。","他日使君江北去，披图应忆岁寒心。"]},{"t":"为李典史题画","f":"七言古诗","c":["古饶山水称浮梁，地灵人杰多才良。","君家兄弟晚挺出，总是碧海青琳琅。","石田荒疏茆屋小，夜读朝耕共探讨。","半壁残灯雨榻秋，一犁破土烟村晓。","慈孝相承上下宜，鸣鸡乳犬亦熙熙。","一家伯仲自师友，九奏琴瑟谐埙篪。","难兄蚤作青云客，枳棘鸾凰应暂息。","难弟三登举子场，至今犹敛冲霄翼。","敛翼冲霄会有期，鸰原一诵一兴思。","吴云楚月路千里，并入彭城风雨时。","天涯会合由来少，感慨悲歌空复老。","椎牛屠狗事区区，燕赵何能豁怀抱。","离别相将会合疏，故园三径未应芜。","凭谁远汲淮淝水，为写安丰董氏图。"]},{"t":"士女图为张宗大题二首 其二","f":"七言律诗","c":["芙蓉迎秋木樨蚤，开到黄花秋欲老。","涉江人远雁来迟，零落东篱为谁好。","小娃扶幼步车轻，闻语回头心懊恼。","曲房深闭绿苔生，何处寒衣月中捣。"]},{"t":"松石流泉图","f":"七言律诗","c":["徂徕山人十八公，石丈夜堕仙人峰。","淋漓元气收不起，地脉似与天河通。","万牛力尽神鞭断，海水茫茫平欲漫。","不如流落此山中，地老天荒共相伴。"]},{"t":"再游吴兴有怀岳文机太守翁载道大尹","f":"七言古诗","c":["东风荡入层崖里，溪上新添半篙水。","蘼芜酝暖绿初齐，杨柳眠寒柔未起。","粉墙红杏启雕甍，逢人误问沤波亭。","道场山下苏湾路，斜阳映醉登西陵。","旧游不忘年华改，桃李无情春十载。","诗社壶觞不再同，醉翁琴鹤今何在。","桑梓年年发故丘，老怀多病念并州。","暮云望断河阳树，旧雨独上元龙楼。","十年往事今如此，此后重来复何似。","惟有溪山对客閒，鸟啼花落将幽思。"]},{"t":"张复阳山水图为李信题","f":"七言古诗","c":["南山道人天发机，平生墨妙探幽微。","胸中山水自许大，千仞复振冈头衣。","笔锋未下见丘壑，欲挽关荆驱李郭。","一种荒閒寂寞乡，苍茫蓊郁烟霏落。","目断寒涛不尽山，寥寥宇宙一人间。","夕阳欲送晚色至，寒意暗逐秋潮还。","秦宫汉殿知何有，玉帐牙樯今在否。","前人已往后人哀，忙地何如閒地久。","孤云起尽水穷津，潭影山光相照贫。","超然坐到无言处，风雨不动天长春。","道人此意无人识，一幅生绡露遗迹。","惟有风流李谪仙，汪洋宦海閒鸥立。"]},{"t":"夏圭风雨图","f":"七言律诗","c":["长风吹折巅崖树，江色愁阴雨声暮。","苍茫野艇晚惊潮，交楫横篙无住处。","何人倚岸汎虚舟，风雨不动如安流。","酒酣袒侧蓬窗底，忽忆瞿塘五月秋。"]},{"t":"题秋江远棹图","f":"七言古诗","c":["澄波练净天同色，万仞苍山垂绝壁。","丹枫白榆相映寒，一片秋光九江碧。","溶溶漾漾何时休，寥寥漠漠湘潭游。","夕阳欲落未落处，都是人生离别愁。","杜陵老病孤舟远，瘦影临江衣带缓。","时平结伴好还乡，野渡无人天又晚。","乘桴击楫事堪嗟，锦缆牙樯不到家。","天风去顺来还便，高兴还须八月槎。"]},{"t":"纪事","f":"七言古诗","c":["成化壬辰秋七月，海涛腾风石塘决。","桑田夜变陆成川，一望边沙烟火绝。","青苗白屋随奔流，红颜皓首尸横丘。","一身虽存六亲尽，至今乱骨无人收。","己午年来岁云愈，乙未严寒冰雪冱。","无端申酉魃为殃，两度风涛迅如许。","河流作卤蝤蛑生，咸风著树枝条零。","苗方秀实水将涸，丰稔不及荒年登。","今年夏月久不雨，清昼耘苗夜车水。","可怜枵腹不支劳，近海膏腴半枯死。","虹蜺目断心焦劳，炎风吹云天宇高。","谁知飓母肆狂虐，平地掇入钱塘潮。","溪腾谷沸雨川迸，城坏堤摧风转盛。","大家浥漏小家漂，不顾田畴顾身命。","因思去岁初阳逢，雷轰电掣当严冬。","如何六月忘溽暑，一雷不振翻为风。","崇朝极夜力不息，潜启蓬窗看天色。","东方欲白西未明，可是龙王听河伯。","莫黑匪乌赤者孤，有子死父妻死夫。","下车泣罪知何意，卿尹当思日月图。"]},{"t":"为张都阃宗大题画四首 其一","f":"七言律诗","c":["东风凝寒柳丝软，细草新篁绿犹浅。","去岁光阴看又来，桃花红胜前人脸。","前人已老桃花开，茆茨布褐行相偎。","琴书满座溪山在，花落閒庭生绿苔。"]},{"t":"为张都阃宗大题画四首 其二","f":"七言律诗","c":["绿槐夹道熏风起，庐阜东南云昼晦。","雷轰雨泣鬼神惊，一泻奔流几千里。","五云山下六月寒，九曲滩头清海翻。","只应三峡桥边暮，长有诗人坐石阑。"]},{"t":"为张都阃宗大题画四首 其三","f":"七言律诗","c":["斜阳淡淡澄江晚，渚蓼江蘋映葭菼。","蓬窗风飏钓丝轻，竹炉茗熟茶烟淡。","沙平浦远雁行孤，人在潇湘八景图。","平生自得江湖趣，不是烟波旧钓徒。"]},{"t":"为张都阃宗大题画四首 其四","f":"七言律诗","c":["蓝关路断无行迹，悬弧城深夜如日。","当年辛苦近何如，为探梅花问消息。","月香水影诗未成，折花且让枝头横。","不知白鹤归来未，开却柴扉待月明。"]},{"t":"赤壁图","f":"七言律诗","c":["江空露白残烟收，水光月影摇清秋。","风流宾主东南美，一舸夜汎鸿濛洲。","酒酣欲叩冯夷宅，俯仰江山小今昔。","兴阑孤鹤过蓬窗，不觉东方又生白。"]},{"t":"秋意","f":"七言律诗","c":["烟霏雾淡西风晓，水净山空秋意蚤。","江南云物岁行周，空谷佳人念将老。","山行有虎川蛟螭，登高目送孤鸿飞。","田园不改桑榆盛，见说陶潜蚤已归。"]},{"t":"渥洼马歌","f":"七言律诗","c":["何物偃强暴厉长，权奇俶傥生歌章。","蒲梢西极沓相举，天闲十二皆龙骧。","羌胡喜蹴骅骝步，贰师成功宛初破。","边塞年年战骨新，锦辔雕鞍只如故。"]},{"t":"送刘廷信兄归闽","f":"七言古诗","c":["时秋七月凉风度，有客鸰原问归路。","富春山下云欲开，钱塘江头潮未大。","潮落潮生自往还，南来北去几人閒。","悠悠名利总如此，谁解盘回兄弟间。","君家伯仲称联璧，古色深沉气温栗。","五千文字老书生，十二山川大方伯。","廊庙江湖事偶然，悲欢离合各悬悬。","萋迷春草池塘梦，落寞对床风雨眠。","去年曾托南飞雁，有约今春定相见。","看穷纸上万金书，不及灯前半时面。","昼语连宵向夕晨，青浓翻忆故园春。","平生本抱丘壑志，长袖怕沾车马尘。","到家时节应重九，丹荔黄柑菊花酒。","邻翁野老笑相迎，又是浮生一开口。","鸿鹄冲霄奋羽翰，从今不苦鹡鸰难。","会须培植堂前树，待弟归同白首欢。"]},{"t":"和丘伍二同年赓唱诗","f":"古风","c":["丘仲深，伍公矩，元是长安看花侣。","三百人中十数人，当时知己聊如许。","仲深南海旧文英，千仞冈头丹凤鸣。","五经腹笥刘原父，三峡词源苏长卿。","可与言人百无二，磨钝剸烦公矩事。","清商却对痼聋弹，利器翻从顽石试。","蹇予同醉杏园春，东抹西涂白发新。","十年谏苑阳城晚，半载滁州永叔贫。","国子先生六堂表，冠佩还家塞翁好。","青史名悭素业孤，进退无凭独吾老。","尺有所短寸有长，舍用未必精邪良。","士无贤愚无所遇，荣枯得失当相忘。","江东云，渭北树，仲深不来公矩去。","西风晚急茂林空，望断斜阳旧游处。"]},{"t":"左时翊云山烟水图","f":"七言古诗","c":["悬岩绝壑峰峦古，碧梓丹枫隔幽浦。","蓬户晨开薜荔烟，渔舟夜泊芦花雨。","暮去朝来水石间，寥寥尘境几人閒。","斜阳又度桑榆影，风露欲经蒲柳颜。","岘山盘谷人归久，故宅残碑今在否。","牢落功名纸上书，消除光景杯中酒。","古往今来事共然，山川游览自年年。","还应剩取春风兴，留赏黄花晚节天。"]},{"t":"夏圭松涛怪石图 其一","f":"七言律诗","c":["巨灵凿山翻地轴，老龙槎牙奋空谷。","茫洋灏气溢不收，一道奔腾鬼神哭。","吕梁洪上孤月明，徂徕黛色参天横。","黄河一泻几千里，人道天潢东向倾。"]},{"t":"夏圭松涛怪石图 其二","f":"七言律诗","c":["青阳使者肤如铁，玄冥老翁头似雪。","云根丈人势敌虎，狭路相逢不相协。","六和塔下天风来，孔明庙前云未开。","仰天俯地望不极，却忆西游滟滪堆。"]},{"t":"瀑布图","f":"七言律诗","c":["绿阴庭宇生南风，醉倚曲阑幽思浓。","平生不到水帘洞，一坐便忆香炉峰。","怪来诗思清人骨，水草林花助萧飒。","烟霞满地暮忘归，长啸一声山月白。"]},{"t":"王若水石榴枇杷图 其一","f":"七言律诗","c":["凉风萧飒红锦裳，翠袍渐染胭脂香。","琅玕枝重压欲折，青女欲拆珍珠囊。","金钢碾碎鸦鹘石，绛绡迸出玲珑色。","葡萄酒尽蔗浆空，一颗灵丹透诗骨。"]},{"t":"王若水石榴枇杷图 其二","f":"七言律诗","c":["东州奇花凌早寒，吴山月廊夜半酣。","何人误作上林赋，病骨却思黄蜡丸。","同时不数杨家果，三寸吴湘空万颗。","会须载酒醉西园，一树黄金压枝堕。"]},{"t":"并笛图","f":"七言古诗","c":["被里鸳鸯春睡足，蛾眉补尖凝黛绿。","沉香亭下鹿眠花，倦倚东皇吹紫玉。","翠鬟亸香薰柘黄，左拍酥肩右按腔。","宫娃张板候节下，花奴缓舞随声扬。","流宫变羽都在口，纵横半借君王手。","就中一指忽差移，风惊别调凄凉久。","蜀江烟水接华清，并辔何如并笛情。","可怜一曲升平调，弄作鸾铃哀怨声。"]},{"t":"为张佥宪题画松","f":"古风","c":["九疑山中十八公，元气结聚非人工。","精求本许周庙致，偶遇不受秦人封。","寒来暑往年华暮，酷月蒸林雪围布。","柔芳弱蔓几枯荣，老干槎牙只如故。","东风吹和春雨零，萋迷碧草连根青。","野猿林鹤相对晚，时有山人寻茯苓。","东阁同心美如玉，音信寥寥渭如澳。","金粉香飘花上黄，虬须紫簇枝间绿。","采花酿酒枝插头，仰援紫藟俯碧流。","盘根错节终不试，犹胜野断横中沟。","枝头满，酒盈瓮，为君起舞冈陵颂。","造化生材会有期，莫入丁生醉时梦。"]},{"t":"尹编修家山图","f":"古风","c":["泰和城外云亭乡，逢原书屋遥相望。","东园别墅图书静，恩庆高堂雨露香。","堂中才子金闺客，身在云霄志岩泽。","一路寒山万木秋，满林风雨孤琴夕。","閒来杖策蹑龙岩，绝壁飞来紫翠涵。","笔架峰前寻药草，城头岭上望秋潭。","日斜回首先公墓，双凤迥峦拥高树。","童子曾闻鹤吊年，居人尚识牛眠处。","红尘满路世悠悠，得失荣枯共白头。","清风明月不须买，宝马朱轮空自忧。","君不见平泉庄上生禾黍，金谷园中绝歌舞。","盘谷愚溪直等閒，留得诗文照今古。","三径黄花手自栽，年年秋雨一番开。","功成身退应何日，预报云山归去来。"]},{"t":"送茌平王秀才","f":"七言古诗","c":["忆昔春闱赴京邸，落日停车马周里。","风尘客路一相逢，空谷足音殊可喜。","下第南归各一天，重来又是六经年。","君家兄弟情如旧，呼酒张灯开夜筵。","明朝再唱阳关曲，屈指韶华今十六。","琐闼追思日似年，碧云怅望人如玉。","渭北江东白雁疏，屋梁残月暮窗虚。","天涯消息有时有，梦里神交无处无。","对床风雨今何夕，一见令人动颜色。","但觉情怀只旧时，不知岁月非前日。","盍簪未已又言归，椿树凝霜雁影微。","阳和乍入官桥柳，寒气偏多游子衣。","难兄已荷轩裳贵，嗟尔年来尚衿佩。","秋风八月桂花时，准拟都门重相会。"]},{"t":"癸卯寓杭戏写目送飞鸿手挥五弦图潦草为婢子所笑因题与女玉祥收为刘氏清话","f":"七言古诗","c":["九月十五住杭州，潇潇风雨生离愁。","閒寻败笔作图画，生纸烂墨伤昏眸。","小鬟立侍笑欲倒，走入幽闺向娘道。","山头颓似土灰堆，树根乱若蓬蒿草。","空中四鸟飞横斜，笔浓大如赤老鸦。","乌纱素服一閒客，坐看去鸟弹琵琶。","我生不是丹青者，适兴投情恣挥写。","等閒涂抹岂足言，便有旁观说高下。","何况嵇康妙绝伦，清谈旷视能容身。"]},{"t":"胡廷晖院景","f":"七言律诗","c":["游丝落红春赏罢，金屋琼楼敞如画。","乳燕双鸣午梦醒，曲阑半露蔷薇架。","太液池头花正开，水香清逐南薰来。","冰山雪舰无人到，共听朱弦歌阜财。"]},{"t":"魏仲礼金笔院景四首 其一","f":"七言律诗","c":["琼芳玉烂春如画，金屋娉婷晚妆罢。","紫垣星象照千门，天上人间共清夜。","金莲炬促双步摇，铜龙咽尽蝇声嚣。","衾裯未暖闻鱼钥，起候宫车视早朝。"]},{"t":"魏仲礼金笔院景四首 其二","f":"七言律诗","c":["罘罳玉馆未垂络，水殿玲珑澄碧落。","綵扇翻香蛱蝶轻，绡衣簇翅蜻蜓薄。","钓天画永无纤埃，水晶帘动南薰来。","三千粉黛放将尽，十二楼台閒自开。"]},{"t":"魏仲礼金笔院景四首 其三","f":"七言律诗","c":["画屏银烛秋光淡，宝篆金炉香夜旦。","昭阳前殿月华沉，长信宫中漏声断。","晨辞同辇别椒房，纨扇凉多未忍藏。","梧桐露重桂风急，吹作芙蓉叶上霜。"]},{"t":"魏仲礼金笔院景四首 其四","f":"七言律诗","c":["氍毹衬满貂闱密，月光斜透墁香壁。","人炉内障旷前闻，酎酒枭羹荷殊锡。","内间时报五更筹，一点银灯过御沟。","边衣连夜催刀尺，明发传呼焚雉裘。"]},{"t":"题刘士元骢马行春诗卷","f":"古风","c":["骢马来，行自燕。","权奇俶傥步骤妍，初辞仗御下天闲。","横绝四极周三边，万骑却走孤云骞。","朝驰蓟门道，暮刷吴山巅。","苗藿塞场水溢川，金鞍宝凳白玉鞭。","生不为秣饮，羹饰焉足怜。","方瞳流光彻幽玄，騣尾拂掠开风烟。","仰天一长鸣，万籁寂不喧。","形声气态众殊调，劳逸动息时相缘。","乘艰履险意閒缓，足迹所至豺狼跧。","山川草木忽变色，幽谷似觉阳春旋。","角端乐生豸恶奸，凤至图出人文宣。","神物自与元化会，匹力上佐龙行天。","未可按索骊黄间。","骢马还，行至燕。"]},{"t":"朱彦明母慈节诗","f":"古风","c":["妾年二十馀，谁信终孀长独居。","妾子方乳哺，急水浮沤岂能固。","妾甘冻馁儿长成，冰壶玉洁阶兰荣。","儿能读书妾终老，良人瞑目黄泉道。"]},{"t":"为翁载道同年题望云图","f":"古风","c":["云飞处，泸之浔，朝朝暮暮生幽阴。","天高地迥望不极，长风落日愁人心。","忆昔童稚年，慈颜蚤相背。","萱花再发椿株荣，白首青毡望儿贵。","儿今已贵双亲存，萧条菽水违晨昏。","吴中烟水空回首，三峡哀猿啼断魂。","君门万里从来语，翻笑庭闱今复尔。","悠悠忠孝两迟回，却望孤云泪如雨。","踌蹰未已云飘扬，欲飞无翼川无梁。","儿心愿作西郊雨，万里随云下故乡。"]},{"t":"王孟端竹","f":"古风","c":["九龙山人王孟端，风流博雅人称难。","漫胸锦绣消不得，化作万个青琅玕。","中山兔老鲛绡白，马肝香透金壶汁。","风回赤壁浪痕平，云黯苍梧雨声急。","铁钩锁金错刀邯，郸学步真儿曹大。","河一决泻千里崩，崖触处生惊涛世。","人岂识，真和假，白雪词高和应寡。","坡仙儋耳未还家，落日临风思老可。"]},{"t":"贺李用经得子效柏梁体","f":"七言古诗","c":["古燕豪杰中朝儒，列卿柱史人间无。","廷平执法及乘舆，泗州推官夜治书。","储祥积庆久不渝，来休下瑞相昭符。","长庚孕秀腾天衢，嵩岳降神钟地区。","熊罴入梦九鹤趋，五老列曜纷前敷。","茏葱佳气蔼门闾，一片清冰出玉壶。","初傅丹山五色雏，又讶鲁国连城玙。","无乃合浦千金珠，英气烨烨声呱呱。","目光流电雪作肤，头角峙玉云拥颅。","伏犀入项四辅俱，罹计插鬓秀且疏。","金木耸贴润复纡，天庭高广顾地枢。","孤峰立笔双井腴，一水环仰中沟虚。","神采气骨画不如，断蓬为矢桑为弧。","九州四海当长驱，英物自与常人殊。","吾闻宗元谪番禺，反顾无嗣悲穷居。","又闻康节四十馀，得子尚虑贤与愚。","君今早应梁栋输，眼底复见圭章储。","前程莫问荣与枯，万事已足将何须。","便应列宴开行厨，烹龙庖凤传笙竽。","起舞蹴踏红氍毹，酒酣击碎青珊瑚。","与君旧是瀛洲徒，春风玉殿同传胪。","浮云流水南北途，故乡遇旧增欢娱。","喜来忘却尔汝呼，落笔故使璋獐诬。","听声知贵名当余，汤饼上座事属渠。","他年归来驷马车，记取堂下三槐株。"]},{"t":"松涧秋声图为婿刘希仁题","f":"七言古诗","c":["嵩高山下秋风起，万壑萧飕碧云里。","黄河之水天上来，一泻昆崙几千里。","竹炉茗熟惊涛生，春蚕食叶缲车声。","风回忽若九韶舞，箫鼓琴瑟相和鸣。","茫茫古意翻新调，里耳皇荂嗑然笑。","天地从来有正声，伶伦老去谁堪道。"]},{"t":"为刘廷器题松竹二图 其一","f":"七言律诗","c":["荒烟满地凝稠绿，一片秋声振浮玉。","苍梧云重泣湘灵，翠袖天寒倚空谷。","西林三径闭松关，江潭游子何时还。","凤凰来仪九功叙，伶伦老去邹生閒。"]},{"t":"为刘廷器题松竹二图 其二","f":"七言律诗","c":["严霜作衅百草黄，春红秋绿纷成荒。","穷阴不变太古色，老节直与层霄昂。","徂来天高岱宗远，万牛不见空山晚。","造化生材自有宜，行人落日生悽惋。"]},{"t":"题林良枯木喜鹊图","f":"七言古诗","c":["金门画史番禺仙，意与物化搜冥玄。","风流妙得写生趣，落笔便可追黄筌。","陟里素薄玄霜隰，海枯纲烂珊瑚黑。","风烟满树忽飞来，野色苍茫向人立。","运斤游刃纷驰驱，横斜顺逆皆乘除。","平生阿堵最难处，毛羽不理精神馀。","浮丘道士怜奇货，素壁高悬三日卧。","解令化石恐还生，莫学张家便椎破。"]},{"t":"游春图","f":"七言律诗","c":["请君停鞭驻君骑，一曲春歌劝君醉。","去年今日看花时，人面桃花在何处。","柳桥花坞春光深，村娃唤酒娱春心。","明朝再向村中过，满地落花芳树阴。"]},{"t":"一径野花落孤舟春水生画","f":"七言律诗","c":["林外春阴晓风作，门径幽深野花落。","东家春色过西家，井口篱根乱漂泊。","溪头新水绕门生，扁舟一叶轻如萍。","杜陵老病烟波远，欲载诗愁过洞庭。"]},{"t":"送庄瑩中吴谣三绝 其一","f":"七言绝句","c":["见说仙郎赋远游，嘉兴西北是苏州。","鸳鸯湖上春来水，别思相随到处流。"]},{"t":"送庄瑩中吴谣三绝 其二","f":"七言绝句","c":["禾稼青时省我耕，禾稼黄时君远行。","收禾输官剩作酒，壶浆三月候行旌。"]},{"t":"送庄瑩中吴谣三绝 其三","f":"七言绝句","c":["君是江潮天上来，侬如渔艇趁潮开。","潮若去时侬便苦，朝朝日日望潮回。"]},{"t":"题平湖陆廷仪鸰原耕隐诗卷","f":"古风","c":["瓯窭满湖南，污耶满湖北。","湖边隐者眷同心，却向湖头结书屋。","屋中经训乃菑畬，释耕互答鸰原诗。","三监不仁万世戒，而我与尔何当知。","稻黍登场先馈祀，大小输官入城市。","城市无人识姓名，归向高堂贺安止。","堂中老人太古风，钁铄更似田家翁。","贻谋燕翼苦不远，尚愿孙辈超群庸。","老人摩挲抱孙说，长大还守湖田业。","勉学而翁与若翁，兄弟不分耕不辍。"]},{"t":"赋得怀姑苏送人归长洲","f":"古风","c":["怀姑苏，隔千里，风景繁华似流水。","去年雨水溢田畴，野草不生禾尽死。","黄童白发拥道周，朱颜绿鬓无人收。","阊闾门外夜深处，饥魂饿魄声啾啾。","城中大家称万石，坐食人多徵借急。","新廪生尘旧廪空，纵有黄金何处籴。","市廛罗绮贱如泥，吴蚕薄熟难为丝。","公家租赋虽停止，官府征徭仍旧时。","长安贵人游侠客，骑马行行过阡陌。","回头笑指虎丘山，却道繁华犹似昔。","九重天子念穷庐，太守新乘使者车。","巡治敕分都御史，平衡全任老尚书。","君归为我询同里，故宅多应换新主。","隐山桥下水茫茫，去任舍冤死生苦。"]},{"t":"郡太守齐公殁既为近律以悼司勋沈先生少予言作薤歌","f":"古风","c":["薤上露，何瀼瀼。","古人去后今人伤。","北邙山头日无光，悲风萧萧生白杨。","金玉充前除，一去不得将。","专城五马贵，穹碑映斜阳。","惟馀父母心，黎庶增凄凉。","长淮水流云路长。","薤上露，何瀼瀼。"]},{"t":"送刘指挥邦彦袭职南还","f":"七言古诗","c":["将军少年才且武，二十辞家见明主。","自陈功伐拜天颜，带砺山河自先祖。","祖死辕门父守边，风沙凌厉雪盈颠。","据鞍不复清时用，抚剑徒怀旅力愆。","繇来勋业期无替，韬略传家世相继。","圣主方思禦侮材，兵曹共识干城器。","天书薄暮出黄门，平旦寻承世袭恩。","金带镂花明晓日，锦衣盘兽结春云。","明朝便踏南归路，马首青山天外树。","鸿鹄冲霄关塞长，云霞出海江天曙。","君归为我问边隅，倭夷伺间今何如。","晨操夜守五千卒，披坚执锐寒无庐。","吮痈死士古来有，况复青春读书久。","不见江南干事人，弈叶登墙传不朽。"]},{"t":"题画","f":"七言律诗","c":["天空水阔饶风露，秋入溪山无尽处。","红叶低垂隔浦霜，白鸥飞落无人渡。","荡漾空明一钓舟，烟蓑雨笠下中流。","心情物色知多少，手展青编还自收。"]},{"t":"葡萄图","f":"古风","c":["紫苏步幛流苏短，露淡风清秋未满。","舞凤翎翻翠解苞，蟠龙骨瘦殊垂颔。","青葱苜蓿锦石榴，枝交蔓引弥山丘。","骅骝不至仙槎远，空有卉物遗中洲。","君不思凉州一斗犹轻换，西行千骑归无半。"]},{"t":"柳塘为吴江题","f":"七言古诗","c":["东风吹林杨柳长，依依袅袅迷横塘。","密叶藏春莺语早，飞花扑地燕衔忙。","塘中水添时雨足，飏绿浮青近华屋。","屋底閒人醉出游，桂棹兰桡泛深曲。","坐听林外桔槔声，行近渔舟和濯缨。","青藜杖缓檐阴合，白苧衣凉潭气清。","荒闻境物堪长保，鸿雪鸦烟情未了。","不及西湖十里香，犹胜芜城两堤草。"]},{"t":"自写松泉图题以寄意","f":"古风","c":["若欲穷黄河源，星槎虎符行路难。","若欲登蓬莱山，列仙真宰当玄关。","劲风弱水不堪即，飘如落叶辞柯还。","故乡迢迢沧海曲，十里青山一茆屋。","山下泉声日夜闻，山头树色阴晴绿。","树色泉声春复秋，归云过月共悠悠。","乾坤遗我古来物，世间万事皆浮沤。","閒时倚望终晨夕，转眼光阴真顷刻。","劳逸悲欢各自迷，千古浮生如一日。","如一日，无穷期，醉人已醉醒人知。","凉风潇潇吹鬓丝，松烟竹露含清滋。","高山流水从前意，绿绮无弦弹向谁。"]},{"t":"层峦秋霁为诸立夫题","f":"七言古诗","c":["秋风吹云秋雨晴，群山涤翠群峰明。","天光下际泽气隐，一碧万仞青螺横。","山高石峻无蘼草，桂馆兰房净如扫。","振谷天球练瀑飞，障林霜锦丹枫绕。","采蘋谁汎小兰舟，急水回塘不自由。","云端笙鹤来何晚，涧底荆薪人白头。"]},{"t":"题刘公瑞松琴卷","f":"古风","c":["君不闻沉香亭前鸣羯鼓，翻厌丝桐污人耳。","新声媚质两浮靡，世好难凭每如此。","屏山隐者爱幽寻，山下青松横素琴。","纷纷红紫久无色，消尽人间金革音。","蒿莱满地迷烟雨，一曲吴讴乱宫羽。","钟期长往梓人亡，日落天低秋思苦。"]},{"t":"汪佥宪母孺人寿意图","f":"七言古诗","c":["丹丘石室芙容峰，金辉玉烂瑶华宫。","三千绰约风埃表，十二雕栊云雾中。","地灵天保人时好，元气融熙人不老。","咽嗽玄和玉液泉，茹餐沆瀣金光草。","南州阿母婉清妍，前身恐是宫中仙。","凝真不藉姮娥药，度世暂别昆崙天。","尔来三万六千日，海屋筹盈才九十。","富贵元无薄命人，神仙自有长生骨。","画堂六月南风凉，水晶帘捲龙涎香。","兰孙桂子焕人瑞，凤冠鸾诰回天章。","何人索隐钩玄藏，方丈瀛洲忽相傍。","灵贶无声入画图，寿徵有象开屏障。","南岳夫人宿驾还，麻姑东海未离山。","惟应西母云軿近，自捧蟠桃荐白环。"]},{"t":"画兰为李载章大尹赋","f":"古风","c":["君不见春风二月三月天，桃红李白纷妖妍。","清歌妙舞欢未了，落英满地生愁烟。","又不见天南海北荒村道，极目萋迷总芳草。","牵愁引恨不知名，可惜流年为情老。","人生光景何匆忙，欢娱易过哀思长。","楚乡旧忆今无恙，湘江水碧湘山苍。","晴日宜晴雨宜雨，幽谷年年悄无侣。","荣枯喜乐两超然，老去心期只如许。","岁月悠悠忽复残，微霜欲度晓风寒。","依悽共结同心约，淡薄谁将冷眼看。","百亩幽芳连九畹，佳人一去何时返。","旧游衣佩向谁边，白石野篁孤月晚。","草色逢春处处芳，公门桃李满康庄。","惟应老谢庭前植，卒岁长含雨露香。"]},{"t":"唐人钩栏图","f":"古风","c":["君不闻天宝年中乐声技，歌舞排场逞新戏。","教坊门外揭碑名，锦绣钩栏如鼎沸。","初看散末起家门，衣袖郎当骨格存。","咬文嚼字澜翻舌，勾引春风入座温。","年少书生果谁氏，弄假成真太相似。","左呼右闹只自如，博带峨冠竟谁是。","众中突出净老狂，东涂西抹何狼獊。","解令笑者变成哭，直教閒处翻成忙。","粉头行首临后出，眼角生娇眉弄色。","从前人物空自哗，一顾广场皆寂寞。","障中挝鼓外击锣，初来队子后插科。","朱衣画裤纷相剧，文身倛面森前傩。","拿生院本真足数，触剑吞刀并吐火。","千奇百巧忽不前，满地桃花细腰舞。","酒家食店拥娼楼，玉壶翠釜蒸馒头。","稠人广座日卓午，捧盏擎柈争劝酬。","眼中不类心中事，嬉笑相同饥饱异。","可怜乐极易生愁，回首斜阳忽无处。","悲欢离合总虚空，好恶妍媸变幻中。","世间万事皆如此，何必钩栏看画工。"]},{"t":"题沈石田云山图","f":"七言律诗","c":["青山白云无处无，幽人写作云山图。","山荒树老云不散，落日未没春愁弧。","蘼芜满地王孙去，莺燕无声春已暮。","容谷佳人白发新，清明寒食伤心过。"]},{"t":"葡萄歌","f":"古风","c":["君不见贰师城外行人稀，葡萄满目秋离离。","初年托根古城下，岁久漫与城垣齐。","城下居人日争树，伐干分根不知数。","一叶寒声动地秋，尽入城中酒家去。","万里征车大宛回，离宫别观一时栽。","苜蓿榴花烂相照，知是将军西域来。","火云亭亭天伏暑，满架繁阴凉似水。","屋里蛟人坐泣閒，海底苍龙蟠不起。","眷兹岁月几悠悠，捲蔓何人入具丘。","雨露不忘中夏泽，冰霜长保故园秋。","故园风景今宁好，名马千金野田草。","惟有年年客土春，至今犹说汉朝人。"]},{"t":"陈启阳风雨二竹图 其一","f":"七言律诗","c":["落红满地春将半，细雨斜风玉零乱。","槿篱萝屋两三枝，翠袖低垂白石烂。","太液池边万岁山，上林几许非人间。","掖垣埤闼春阴里，记得题诗晚直閒。"]},{"t":"陈启阳风雨二竹图 其二","f":"七言律诗","c":["春风淡荡湘中林，桃红李白春光深。","林隅菉竹密如栉，罗绮不到蘼芜侵。","羲和南驭西风蚤，劲节青青老还好。","君看旧日竞春芳，不及湘林路傍草。"]},{"t":"刑科钱士义升山西参议临行以流泉小幅求题书此见意","f":"七言律诗","c":["洞门高阁春多雨，凤沼无尘涨新水。","九天空翠润生香，一道微茫清彻底。","分流日夕响成雷，白石苍松飞浪催。","馀波万里沾枯槁，始信黄河天上来。"]},{"t":"为张彦晖写兰竹题","f":"七言律诗","c":["悬崖照水生丛兰，杜若洲空修竹寒。","光风夜转吹不落，国香倒拂青琅玕。","涉江远道谁堪采，晚节平安应未改。","梦中犹自忆同心，楚乡风雨知何在。"]},{"t":"一笑山琴月盘倚醉石","f":"古风","c":["迢迢郁林州，渺渺扶馀国。","截断洞庭波，苍茫古颜色。","空庭悬磬白日孤，四无完壁生蘼芜。","残刓败纽钟鼎破，棱层断骨蛟龙枯。","不堪元亮眠，不下元章拜。","醉来半倚醒半凭，侧对青山不相碍。","弹琴声益清，候月影先在。","空山寂无人，兀立如有待。","昔为谁家物，今为吾所爱。","今来古往复几年，问石不语心茫然。","失亦不足悲，得亦不足怜。","世间万物皆暂有，大梦未觉争媸妍。","李文饶，牛僧孺，爱物何同爱身异。","间关进退互不持，纵有珍奇焉足计。","载鼓纷亭操，载歌谪仙词。","青天湛湛知音少，一曲秋风两鬓丝。"]},{"t":"文与可雪竹为刘挥使题","f":"七言古诗","c":["阴风吹云时物换，六花漫空大成片。","琅玕冻折凤翻巢，素羽离披玉零乱。","淇隈晚霁天籁寂，湘浦宵寒旅行断。","长川巨挺千亩荒，曲水幽丛数竿短。","清如映诵老儒绅，劲如瘦马蓝关人。","羝窖天荒节犹立，鹅池路险戈前陈。","一寒范叔故如此，半死袁生未是贫。","事当忧患见君子，时到否塞回阳春。","虔心苦节终无改，毅色英标暂如晦。","九成合乐笙簧齐，四海同文简书在。","进登廊庙更华显，退处山林亦潇洒。","不遇凄凉冷落时，宁知远大坚贞态。","湖州太守时宗工，奎光斗气交茏葱。","文章不减中古士，画法稍过东坡翁。","高堂素壁三日卧，毛骨彷佛临严冬。","晴云秋月尘埃断，鉴定还须问潞公。"]},{"t":"为吴汝辉题杏花鸡","f":"七言古诗","c":["枝上杏花红尽吐，枝下鸣鸡日当午。","千花万花锦作堆，大鸡小鸡雁成侣。","落英点羽浮霞轻，华风不动香尘生。","群雏狎母竞啄逐，孤雄竦眄缘花行。","东君为恐春归蚤，暗促晨声报春晓。","狂蜂浪蝶却不来，惜花又怕春情扰。","牝牡埘楼健息滋，栽培秀实趁芳时。","伏烹奋门耽花老，却笑长安游侠儿。"]},{"t":"吴汝辉任月山公子醉归图","f":"古风","c":["清秋灏气连山区，贵游子弟行相娱。","崇光艳色凌丘隅，景物似与寻常殊。","文鱼泳跃珍禽呼，金池琼岛周模糊。","老树眩若红珊瑚，被服绮丽云霞敷。","冠履美好玉带纡，雕鞍宝马交通衢。","青黄赤白紫驳卢，骥騄骝駥騋騊駼。","矫如游龙捷飞狐，一一尽是千金驹。","上骑五色馀仆夫，窄襟短后缨曼胡。","矬帻隘袖杂裯襦，锦囊绣襆垂流苏。","武仪文具步技俱，负乘总是苍头奴。","想当初筵列行厨，新丰美酒千斛沽。","兴来一饮三百壶，出门初旭归及晡。","去已矜肆归豪粗，一人醉俛先群徂。","一人却顾回头颅，一人偃促思长驱。","一人酣偻如曲瓠，中有甚者双夹扶。","垂首鞠背同擒俘，行从辐集高阳徒。","瓶倾罍罄恣啜餔，叫呶突兀口嗫嚅。","蹙立睥睨行连?，攀鞍捋臂掀长须。","前不辟人后不趍，溷亵不异鸡与凫。","月山老手写此图，无乃作鉴昭蒙愚。","诗书明训慎勿孤，一日湎丧终身污。","君不见嘉宾式燕醉若拘，五陵游荡无时无。"]},{"t":"赵千里赤壁图","f":"七言古诗","c":["大江东去飞涛急，故垒西边壁垂赤。","玉堂学士天上人，两度随携漫游客。","放歌一曲下中流，洞箫倚和言更詶。","清风明月不须买，欲与元化相周游。","酒酣袒卧蓬窗窄，不觉东方已生白。","再来又是孟冬时，过眼江山忽殊色。","披荒履险登崔嵬，划然长啸山应颓。","回舟荡入鸿濛里，时有孤鹤横江来。","平生到处多佳遇，海市登舟亦奇事。","文章变态发雕龙，意象飘飘梦中是。","铁骑长驱欲闭关，前珠后壁焕斓斑。","伯驹图画鲜于字，二赋长流天地间。","巢松幽人吕山下，收藏不惜千金价。","清秋明月画楼开，应有虹光彻长夜。"]},{"t":"题山水画","f":"七言古诗","c":["东风雨足春芳早，天鸡一声春已晓。","阳乌飞立扶桑颠，紫气虹光绕云表。","南山焕耸青巑岏，北山突兀苍龙盘。","飞泉出峡山欲动，眼前似觉天河翻。","松山桧柏连崖嶂，楼阁亭台迷远望。","行居坐作总优閒，断隔红尘几千丈。","松飘晴雪落鸥沙，想像吴兴学士家。","墨妙亭中调舞鹤，碧澜堂外泊浮槎。","抱琴有客穿花坞，吠犬鸣鸡日将午。","主人闻客未褰裳，童子迎宾倏开户。","白雪阳春曲暂停，好乘清兴共高登。","蓬莱方丈知何处，羡门安期焉可凭。","江山风月应长在，山下游人岁更改。","已见朱颜换白头，未会桑田变沧海。","古往今来事共然，荣枯开落事相缘。","不如遍历佳山水，日日相携上酒船。"]},{"t":"渔村图","f":"七言律诗","c":["荒山野水通渔浦，浦山渔家隔芳屿。","放棹晨炊北渚烟，联蓬夜宿西岩雨。","停罾晒网收鸬鹚，彷佛潇湘日暮时。","不知何处乘桴伴，犹唱三洲估客词。"]},{"t":"看桃图","f":"古风","c":["枝上花，花下人。","红芳与绿鬓，颜色骄青春。","花开满枝还结子，人生莫作浪游身。"]},{"t":"和张汝弼赠黄时英韵","f":"七言律诗","c":["垂杨茂草西湖路，有客携诗笑相顾。","平生解作子长游，一举能轻季伦富。","三江风月五陵花，软红香土迷繁华。","当时壮观老犹在，欲凌倒景餐晨霞。"]},{"t":"三月十四日婿刘希仁遨游冯氏湖亭风雨夜作已刻始霁冒湿而前卒成胜赏呈同游诸公","f":"七言律诗","c":["湖山夜雨催春急，莺燕无声曙犹滴。","东风似是惜春归，淡扫阴云漏初日。","从来晴好雨亦奇，雨晴沓至添华滋。","人间盛事常不满，逢欢便作快心时。"]},{"t":"金兰竹石图为王廷光佥宪题","f":"古风","c":["瑶砧玉杵镠霏皎，凤膏腻滑狸毫绕。","都将丽水岸头沙，洒作湘皋畹中草。","灵均佩重络索乾，湘妃菊衣秋染单。","琅玕郁密错刀碎，鸾翎旖旎商飙寒。","君不闻同心之利坚可断，请看南山黄石烂。"]},{"t":"林良九鹚图","f":"七言古诗","c":["番禺画史何好奇，以鹭作路思作鸶。","孤为一世功名路，九拟鲁论君子思。","古来工艺皆有谏，此画于人亦深鉴。","翔集低昂敛鸣缩，舒近时临容止变。","举者忽下去忽归，半窥鱼跃半防机。","藏形不向青边立，蔽影多从白处飞。","寒塘浅水黄芦叶，暂寓旋消鸿踏雪。","人物虽殊戒虑同，座右箴铭为谁揭。"]},{"t":"戴文进山水为王君载题","f":"七言古诗","c":["朝阳出海东方明，岩西宿霭和烟横。","林空花落春欲暮，时有戴胜桑间鸣。","小舟一叶行还舣，载得图书满蓬底。","山光水色不胜情，未转崖阴似千里。","西湖歌舞日悠悠，锦缆牙樯总贵游。","安得荒閒如此地，与君同泛米家舟。"]},{"t":"谢杭医夏时彦","f":"七言古诗","c":["钱塘名医夏克和，我曾倒屣邀经过。","当时橘井深几许，至今孙子扬馀波。","乌金素服黄丝带，金匮青囊皂油盖。","肩舆朝出暮归来，常有乡人候门待。","友竹高人王瑞之，秋来遗我双鱼书。","书言女弟膺剧疾，病缠弱女眠将徂。","世芳太守怜弟妇，仓皇共访回生手。","感君匕剂起沈痾，五月春阳转枯朽。","白头有妺复有甥，太守兄弟家和平。","伊谁大惠忽致此，何以上报琼瑶瑛。","烦君为谢殷勤意，新章早托鳞鸿寄。","赠金自古不如言，交义由来迥忘利。","老我方洲笔砚荒，愧无佳句为传扬。","惟应子益遗书在，不用当时玉局方。"]},{"t":"捕鱼图","f":"古风","c":["商船竟夕发，莲棹怀晨游。","劳欢两难久，不及渔家舟。","三江风月五湖景，妇子相随到白头。"]},{"t":"江天欲雨图为阴佥宪题","f":"七言律诗","c":["大山昏冥小山黑，万树迷林江变色。","老龙吸波倦出海，少女驱云未行急。","白日昼隐西郊阴，欲雨不雨愁人心。","传岩有客晏犹卧，莫待旱极方为霖。"]},{"t":"画石谷图送吴提学升云南宪使","f":"七言律诗","c":["石谷山头云昼开，石谷山下泉萦回。","谷中主人欲高卧，霹雳一声惊梦回。","六经膏泽已渐被，四方霖雨迟滋培。","大川舟楫小如苇，惟有图籍江南来。"]},{"t":"北行别友","f":"五言律诗","c":["去去青云路，何时更盍簪。","西风游子恨，落日故人心。","报国凭三策，论交薄万金。","寥寥尘境外，诗酒卧东林。"]},{"t":"送黄掌教","f":"五言律诗","c":["泮水官初满，临岐意黯然。","风云千里道，雨露九重天。","硕学推程颢，清才数郑虔。","愿言行莫缓，台阁正求贤。"]},{"t":"张世清爱竹轩","f":"五言律诗","c":["辞官归故里，种竹已成林。","扫叶容春笋，编篱护晚阴。","清风如有意，明月本无心。","几度临轩坐，烟消綵凤吟。"]},{"t":"寄刘珙弟兄","f":"五言律诗","c":["不见诸贤久，空悬每日思。","大兄膺就业，叔子尽能诗。","岁月嗟长往，功名未有期。","自怜游泮水，空忆少年时。"]},{"t":"领举别武林主人","f":"五言律诗","c":["别业幽栖处，攀缘及上方。","地深松叶暗，天近桂花香。","馆客逢华荐，居人馈玉觞。","青云从此去，回首意难忘。"]},{"t":"题閒居诗卷","f":"五言律诗","c":["一廛吾所受，三径旧尝游。","自有閒中乐，其如物外求。","烟霞居散地，人事付虚舟。","见说轩中客，而今好白头。"]},{"t":"绿阴清昼堂","f":"五言律诗","c":["山中有高士，结屋住岩丘。","树密乌声乱，林深鹤梦幽。","云来疑向夕，风度欲惊秋。","何日寻三径，相期避暑游。"]},{"t":"送安二兼简令兄仁远","f":"五言律诗","c":["故人不可见，令弟早相知。","文采京华自，威仪伯仲推。","云深江树黑，天远雁书迟。","若问同袍者，悲凉比旧时。"]},{"t":"寄崔惟正","f":"五言律诗","c":["瘴海风烟息，江关别意长。","思亲愁未了，忧国意难忘。","一将城东壁，孤军历异乡。","功名当此际，慎莫厌风霜。"]},{"t":"齐寿为沈秋官作","f":"五言律诗","c":["世治忧虞外，身閒疾病稀。","秋风双白鬓，春雨两斑衣。","结发恩长满，齐眉愿不违。","同年复同老，鸾凤竟于飞。"]},{"t":"寄刘世经","f":"五言律诗","c":["一别隔千里，天涯日日心。","草深兰畹路，云满薜萝阴。","往事翻成梦，孤怀只自吟。","相思不相见，情到忽沽襟。"]},{"t":"送王给事使满刺加","f":"五言律诗","c":["圣主重遐荒，天书命夕郎。","楼船浮瀚海，冠服被蛮方。","岛屿三韩近，风云八表长。","兹游未可倦，重译又来王。"]},{"t":"送人冠带还吴中","f":"五言律诗","c":["自领公车召，十年今始归。","忽惊文采别，未觉鬓毛非。","落日迷乌鸟，春风动锦衣。","慈亲正强健，此乐愿无违。"]},{"t":"送常州王经府","f":"五言律诗","c":["三年劳赞府，千里觐长安。","政为传家熟，清因近俗难。","烟云江浦别，风雨郡斋寒。","却爱难兄弟，声华总未阑。"]},{"t":"思亲","f":"五言律诗","c":["记得高堂别，俄惊信息稀。","梦随青草极，目断白云飞。","晚色应催鬓，新愁欲满衣。","庭闱有难弟，非是莫忘归。"]},{"t":"题赤壁图二首 其一","f":"五言律诗","c":["孤棹临江发，中流晚色开。","相看今夜月，曾照几人来。","世事更棋局，浮生落酒杯。","扣舷清兴发，况是洞箫催。"]},{"t":"题赤壁图二首 其二","f":"五言律诗","c":["吴魏忽已古，江山遗至今。","年华互流易，诗酒重登临。","宦达悲前事，清游契宿心。","无端孤鹤梦，回首夜沉沉。"]},{"t":"和杨同府閒云晚兴","f":"五言律诗","c":["本是无心出，归来晚更閒。","风高防远散，雨小幸时还。","淡薄秋林外，寒停夕照间。","同行五色伴，岁尽未还山。"]},{"t":"题刘曜卿画","f":"五言律诗","c":["青山回北里，白水绕西邻。","世路悲寥落，烟霞爱隐沦。","柳边垂钓者，花下抱琴人。","不是怀长往，明时蚤乞身。"]},{"t":"挽刘孟庸","f":"五言律诗","c":["衣冠归旧族，儒术自皇元。","落日迷沧海，青山满故园。","衰麻悲令子，期杖哭遗孙。","海外诸朋友，伤心入梦魂。"]},{"t":"题王子久画","f":"五言律诗","c":["地域分吴越，河山阅古今。","江空寒雁下，天远戍城深。","宦达悲长往，暌违负此心。","何当随钓叟，归卧北岩阴。"]},{"t":"题画","f":"五言律诗","c":["绿水明遥浦，清峦发曙光。","舟人迷蜀道，估客望沅湘。","近渚江蓠熟，盘云晓雁翔。","悬知登眺日，怀古使心伤。"]},{"t":"菊乐","f":"五言律诗","c":["未发先期赏，临开不倦游。","杜陵嗟有泪，彭泽故多愁。","诗化寒香淡，情甘晚节优。","宜男空自好，对此共忘忧。"]},{"t":"寄吴兴前辈","f":"五言律诗","c":["怀人不可见，名誉重相传。","诗酒閒居乐，箕裘令子贤。","莺声茆屋雨，草色暮山烟。","惆怅天涯路，吟成倍黯然。"]},{"t":"挽富太守","f":"五言律诗","c":["不识荆州面，常闻窦老贤。","一官成白首，三世共青毡。","夜月磻溪路，春风杜曲田。","伤心怀往事，草色自年年。"]},{"t":"送张琏下第还大兴","f":"五言律诗","c":["共是天涯客，那堪复送君。","感时悲贾谊，下第惜镏蕡。","沧海沤波远，青山鸟道分。","声华久自著，聊复叹离群。"]},{"t":"为姜用贞题梅","f":"五言律诗","c":["海宇年芳尽，孤标晚更奇。","不缘风雪里，那见岁寒姿。","止渴惭无补，调羹已有期。","逢人如有便，莫负陇头思。"]},{"t":"挽人母亡","f":"五言律诗","c":["萱亲不可见，令子竟何依。","落日啼乌鸟，晨风动綵衣。","伤心看陇树，清梦引慈闱。","为问王孙贾，谁应望汝归。"]},{"t":"曹以安仙桂堂","f":"五言律诗","c":["华屋临仙境，高标远世尘。","谁移天上种，为有月中人。","香和金兰远，阴连玉树新。","于今堂下景，并入杏园春。"]},{"t":"送张璆二首 其一","f":"五言律诗","c":["客里相逢好，临期益惘然。","归心吴苑月，乡梦楚江烟。","云水经千里，星河共一天。","重来应未卜，尘榻为谁悬。"]},{"t":"送张璆二首 其二","f":"五言律诗","c":["五月都门道，长歌送远归。","北来青草歇，南望白云飞。","久病惭余拙，高怀似尔稀。","江湖旧游事，此别定多违。"]},{"t":"世德堂","f":"五言律诗","c":["不见高阳里，华堂似太丘。","九州垂远裔，千载继遗谋。","婚冠酬嘉会，登歌集胜游。","犹疑群从夜，星象动高秋。"]},{"t":"登方洲一笑山","f":"五言律诗","c":["徙倚出前除，登临极夜初。","月高墙影尽，风淡树阴疏。","步缓行堪久，歌阑思有馀。","瀛洲在天上，吾复爱吾庐。"]},{"t":"贫乐窝为王本正作","f":"五言律诗","c":["陋巷无馀地，破庐常见天。","往来浑不觉，老去欲忘年。","世味閒中豁，冥怀澹处便。","浮云门境外，诗酒只陶然。"]},{"t":"岁寒图","f":"五言律诗","c":["松竹有晚质，野梅寒共芳。","秾华看又歇，疏冷故如常。","庙用期同调，居閒欲并藏。","相知自相久，非是别炎凉。"]},{"t":"咏竹寄所知","f":"五言律诗","c":["地僻种元少，年深生渐滋。","向无当路笋，时有出林枝。","晚翠迟堪并，春红近亦宜。","阴森聊自尔，惭负雪霜知。"]},{"t":"哭刘缓斋","f":"五言律诗","c":["横涕强吞声，愁怀百倍生。","一家摧柱石，七县失耆英。","零落春秋笔，虚微月旦评。","惟应天上月，清澈似君情。"]},{"t":"竹鹤老人画为徐时用题","f":"五言律诗","c":["山水蔼清妍，吴东三月天。","雨中闻社鼓，树里见炊烟。","诗景谁家屋，閒情野渡船。","无人共登泛，斜日下长川。"]},{"t":"雪中偶兴","f":"五言律诗","c":["晴雪万山深，苍茫晓尚阴。","泉声来绝涧，寒气积疏林。","尽道丰年兆，谁同卒岁心。","灞桥驴背客，诗思正相寻。"]},{"t":"为杨廷献题画六首 其一","f":"五言律诗","c":["山色青无际，溪流绿渐深。","淡烟依远岫，疏雨过平林。","不见轮蹄迹，惟闻钟磬音。","何当去城市，来此极招寻。"]},{"t":"为杨廷献题画六首 其二","f":"五言律诗","c":["僧舍烟云表，人家木石中。","乱山迷远近，流水绕西东。","犬吠穿萝月，猿鸣落叶风。","曾逢隐人说，庐阜路相通。"]},{"t":"为杨廷献题画六首 其三","f":"五言律诗","c":["度壑飞流急，缘溪狭径长。","松杉围古寺，鸥鹭下回塘。","旧讶周颙隐，今无贺监狂。","惟馀林下叟，淳朴似虞唐。"]},{"t":"为杨廷献题画六首 其四","f":"五言律诗","c":["山峻容过鸟，溪深隐钓舟。","平生不到处，今日偶来游。","迤逦踰青障，招寻近翠楼。","桃花流水暮，归路使人愁。"]},{"t":"为杨廷献题画六首 其五","f":"五言律诗","c":["路僻无忙步，林空有远情。","幽寻行复坐，诗绪乱还清。","水到荒矶绝，云依野树生。","何时休世念，来与尔同盟。"]},{"t":"为杨廷献题画六首 其六","f":"五言律诗","c":["名郡浙东西，耶溪与霅溪。","水平吴地落，潮长越山低。","杨柳藏鸦密，芙蓉隐棹齐。","何当寻贺监，来往日攀跻。"]},{"t":"成化甲辰七夕立秋有作","f":"五言律诗","c":["立秋逢七夕，不减岁朝春。","天上佳期协，人间俗事新。","炎凉俄代序，时节并催人。","萧瑟梧桐叶，相随野鹊频。"]},{"t":"闻萧姨讣慰内","f":"五言律诗","c":["只记生离日，那知死别年。","素怀常自省，真信托谁传。","姊妺双成念，夫妻未了缘。","从今东海月，空照蓟门烟。"]},{"t":"水竹图","f":"五言律诗","c":["漠漠孤烟合，盈盈一水深。","汗青谁涉采，猗菉自行吟。","野色将秋思，江声并夕阴。","可怜桃李月，风雨断幽寻。"]},{"t":"松泉轩","f":"五言律诗","c":["松叶缘溪密，山泉夹岸流。","云深常蔽户，石碍仅通舟。","鹤宿庭中月，厨分涧底秋。","曾逢轩下客，为说似玄洲。"]},{"t":"五色牡丹","f":"五言律诗","c":["五色名皆具，千金价不赊。","相看真似锦，比美更无花。","瑞凤衔天诏，祥云夹日华。","沉香亭久废，变态更谁家。"]},{"t":"挽宋举人","f":"五言律诗","c":["四举皆不偶，一生良苦辛。","贫无青眼客，死负白头亲。","牢落愁中事，悲凉梦里身。","生平清谊在，肠断故交人。"]},{"t":"竹林七贤","f":"五言律诗","c":["深竹暗浮烟，群公乐事偏。","高情动寥廓，清论入微玄。","岂是巢由侣，何如沮溺贤。","其谁匡典午，勋烈照遗编。"]},{"t":"坡翁雪月二竹 其一","f":"五言律诗","c":["岁晏暮山深，潇潇雪满林。","影偏银凤下，声细玉龙吟。","独抱平生节，谁同末路心。","惟应松柏树，寒日共萧森。"]},{"t":"坡翁雪月二竹 其二","f":"五言律诗","c":["明月照幽篁，天空夜气凉。","繁阴连密地，清影乱疏行。","雨雪伤迟暮，风烟怯老苍。","何如今夜景，潇洒胜浮湘。"]},{"t":"至德清有作","f":"五言律诗","c":["野树荒烟路，重来十五年。","溪山如有待，人物故依然。","渔火明寒浦，菱歌起暮船。","长桥今夜月，桑梓影重圆。"]},{"t":"酬张篪用来韵","f":"五言律诗","c":["自废登山屐，长怀漉酒巾。","风云游子暮，鱼鸟故园春。","听雨兴思远，临池得句频。","林泉高致在，词翰近尤新。"]},{"t":"舟次济宁遇雨寄孙廷昭大参","f":"五言律诗","c":["一自同官后，于今又几年。","相逢真偶尔，分手各依然。","旧事凭谁问，新诗觅雁传。","天涯不可极，烟雨过前川。"]},{"t":"草庭","f":"五言律诗","c":["幽亭何寂阒，芳草不知名。","花落东风淡，莺啼暮雨晴。","閒中随意绿，空里过愁生。","惟有濂溪趣，年年任化成。"]},{"t":"忆母","f":"五言律诗","c":["慈母殁七载，痴儿尚一身。","天涯常有月，堂北更无暾。","虚室鸡群散，荒园野苧贫。","平生勤苦事，日远益悲辛。"]},{"t":"唐安八景为尹朴之赋 其一 东湖夜月","f":"五言律诗","c":["云净水悠悠，空明一色秋。","夜凉珠泪重，风淡桂香幽。","放浪袁宏渚，清真庾亮楼。","其谁泮宫里，登屋候西流。"]},{"t":"唐安八景为尹朴之赋 其二 高阁红梅","f":"五言律诗","c":["寂阒古城东，犹遗雪后红。","人无前日兴，花异旧时容。","远道凭谁寄，新词愧未工。","绿阴高阁下，零落负春风。"]},{"t":"唐安八景为尹朴之赋 其三 天目晓钟","f":"五言律诗","c":["山闇树冥冥，潮音振海生。","断依残漏尽，喧杂曙乌鸣。","远梦惊长乐，迷途想化城。","如何长往客，犹著夜衣行。"]},{"t":"唐安八景为尹朴之赋 其四 市桥官柳","f":"五言律诗","c":["风暖乳莺啼，春来处处齐。","晴连官道狭，寒映酒帘低。","摇落应相待，繁华莫自迷。","犹胜离别恨，生长灞桥西。"]},{"t":"唐安八景为尹朴之赋 其五 西江晚渡","f":"五言律诗","c":["天晚路悠悠，归心急暮投。","水声喧语笑，人影乱浮沤。","谁击中流楫，犹閒野渡舟。","济川须及蚤，斜日下沧洲。"]},{"t":"唐安八景为尹朴之赋 其六 白塔斜阳","f":"五言律诗","c":["野色荒凉处，山空日未沉。","僧归黄叶寺，犬吠白云林。","塔影凌秋霁，钟声送夕阴。","无因驻清景，馀兴得幽寻。"]},{"t":"唐安八景为尹朴之赋 其七 前村牧笛","f":"五言律诗","c":["沓霭山村静，悠扬草路遥。","调高初上陇，声近渐临郊。","落日凝寒岫，悲风动柳条。","太平民事好，日日换新谣。"]},{"t":"唐安八景为尹朴之赋 其八 岷山晴雪","f":"五言律诗","c":["古澹色常在，苍茫势欲崩。","阴风吹不尽，寒日照还凝。","夏迹怀神禹，唐章重少陵。","丰年欣有象，佳兴会堪乘。"]},{"t":"龙江八景为康佥宪题 其一 南亩农耕","f":"五言律诗","c":["沃土饶生意，芳村托比邻。","西城初卒岁，东作又乘春。","食力真吾事，全生仰至仁。","此乡深化育，应有带经人。"]},{"t":"龙江八景为康佥宪题 其二 北山儒隐","f":"五言律诗","c":["盛世多才逸，山居近市喧。","不矜高士节，聊托野人群。","弦诵消寒暑，柴桑见子孙。","如何冥寂士，薄暮起移文。"]},{"t":"龙江八景为康佥宪题 其三 石桥秋月","f":"五言律诗","c":["白石卧沧波，冰轮度玉河。","地高秋影重，天近夜凉多。","清赏谁将共，幽怀奈尔何。","会逢题柱客，同和谪仙歌。"]},{"t":"龙江八景为康佥宪题 其四 龙穴晓云","f":"五言律诗","c":["神物何年化，行云日霭然。","灵氛迷石洞，翔影落沉渊。","岂是无心出，何因有梦传。","田家镇相望，霖雨自年年。"]},{"t":"龙江八景为康佥宪题 其五 尖峰樵唱","f":"五言律诗","c":["云重碧山深，行歌度远林。","回风传逸响，空谷振流音。","劳苦还相和，招呼拟共寻。","闻歌尽回首，谁会买臣心。"]},{"t":"龙江八景为康佥宪题 其六 横浦渔舟","f":"五言律诗","c":["疏柳系扁舟，年年水上头。","雨晴人共发，风急夜相留。","酒伴多同醉，船居未解愁。","此生聊复尔，何用著羊裘。"]},{"t":"龙江八景为康佥宪题 其七 山寺晴岚","f":"五言律诗","c":["缥缈带春霏，山深野寺微。","淡随香霭散，浓映雨花飞。","困鹤惊茶灶，閒僧闭竹扉。","明朝去游览，拟著薜萝衣。"]},{"t":"龙江八景为康佥宪题 其八 独冈晚照","f":"五言律诗","c":["孤绝群山外，斜阳落未沈。","馀光迷鸟阵，流彩入枫林。","旷望愁将夕，昏黄思不禁。","桑榆景犹好，谁肯惜分阴。"]},{"t":"梦刘公瑞","f":"五言律诗","c":["形影久云绝，连宵频梦君。","布衣仍潦倒，病发乱缤纷。","似别惊相见，将言悄不闻。","平生最深契，梦断一销魂。"]},{"t":"送陈知县","f":"五言律诗","c":["共说难兄弟，才华信合并。","龙光双剑白，鹤梦一毡青。","擅学诸王字，能通大戴经。","鸣琴花县日，春满卓公庭。"]},{"t":"旧朝靴","f":"五言律诗","c":["记得初成日，先朝禁直臣。","动移当辇毂，步履上星辰。","待漏清霜满，乘春玉镫新。","旧缝时绽裂，犹有玉阶尘。"]},{"t":"戊辰中秋日得舍弟归信已至江口","f":"五言律诗","c":["宦迹茫无际，归期定已闻。","素怀同月满，积思共秋分。","汉傅功名异，眉翁骨肉存。","白头俱永感，临见却销魂。"]},{"t":"吴孟章自乐山八景 其一 野仙居","f":"五言律诗","c":["自有丹丘地，疑逢萼绿华。","绕门多槲叶，临水尽桃花。","不类人间世，真成方外家。","平生出尘想，蓬褐更清嘉。"]},{"t":"吴孟章自乐山八景 其二 老农窝","f":"五言律诗","c":["莘野无馀业，成都有薄田。","茅檐容犬宿，草具近牛眠。","炊借邻家灶，烹分土窟泉。","西成与东作，岁岁此盘旋。"]},{"t":"吴孟章自乐山八景 其三 留云亭","f":"五言律诗","c":["山近气常聚，林深风漫吹。","非因朝作梦，因为雨催诗。","窗幔垂还入，炉薰散不移。","从龙今出岫，舒卷共相宜。"]},{"t":"吴孟章自乐山八景 其四 得月涧","f":"五言律诗","c":["一碧净无尘，清秋月满轮。","天空光乱水，风荡影移人。","举酒邀何及，登楼赏厌频。","婵娟长在目，幽绝异通津。"]},{"t":"吴孟章自乐山八景 其五 引泉渠","f":"五言律诗","c":["疏凿近山陂，开云导玉脂。","岸回斜沁圃，石矗细通池。","溪雨涨来急，野花流到迟。","因之想清渭，欲访郑当时。"]},{"t":"吴孟章自乐山八景 其六 青华洞","f":"五言律诗","c":["地远芳林匝，岩开侧径纡。","云扉风钥静，罗幔月灯孤。","偶此寻丘壑，凭谁入画图。","曾逢异人说，深处似蓬壶。"]},{"t":"吴孟章自乐山八景 其七 紫烟台","f":"五言律诗","c":["突兀承苍汉，空蒙生紫烟。","登临飞鸟上，望到夕阳边。","气接云林洞，光涵月涧泉。","香炉峰下景，同此类超然。"]},{"t":"吴孟章自乐山八景 其八 蠹鱼轩","f":"五言律诗","c":["墨气浓侵辨，虫痕细绕边。","自因当膝破，无复可人悬。","竹污消遗简，芸香落断编。","茶搜并日晒，莫笑腹便便。"]},{"t":"云峰东麓","f":"五言律诗","c":["生孩寻失父，成葬荷尧夫。","天启三公地，人嗟五父衢。","西原乔梓合，北陇凤鸾孤。","想见焚黄日，还应哭幼雏。"]},{"t":"山溪晚兴","f":"五言律诗","c":["树色逢秋淡，山光薄暮佳。","吟看风堕叶，坐觉水生花。","野景周遭在，幽情一倍加。","日斜人不见，惟有过林鸦。"]},{"t":"翠岩","f":"五言律诗","c":["松柏连崖岫，轩窗匝薜萝。","门临苍玉案，人在绿云窝。","路入三茅洞，行经七叶坡。","日斜天宇净，空碧罩青螺。"]},{"t":"半閒","f":"五言律诗","c":["动里心常静，忙中乐自由。","租庸长预了，子姓早分忧。","事办多临弈，耕馀便出游。","何如贾秋壑，名地总虚浮。"]},{"t":"送侯方伯赴河南","f":"五言律诗","c":["圣主念生民，雄藩列重臣。","金章辞玉阙，宝马曳朱轮。","南粤仁恩在，中区事业新。","会看嵩岳里，幽谷发阳春。"]},{"t":"赴汀","f":"五言律诗","c":["频年湖海上，妻子倦相随。","道在贫非病，才疏远更宜。","依违真自耻，得丧任时为。","独有严亲在，临行泪雨滋。"]},{"t":"舟过富阳","f":"五言律诗","c":["离家才十日，乡思渐多违。","江近村居少，山高石路危。","野人惊客至，水鸟傍船飞。","何处桐庐县，苍茫对夕晖。"]},{"t":"登龙游翠光岩","f":"五言律诗","c":["孤棹舣寒汀，无人独自登。","积苔迷鸟篆，斜日照鱼罾。","湍急声如振，崖高势欲崩。","客游那可驻，云重树冥冥。"]},{"t":"严州道中","f":"五言律诗","c":["云路缘江转，舟行夕照中。","水清深见石，山近欲挨蓬。","意与寒林澹，情随野望通。","閒呼小儿女，到处一从容。"]},{"t":"云谷草堂","f":"五言律诗","c":["閒云深谷里，寂寂隐茆庐。","昼榻疑朝暝，晴檐似雨馀。","有溪通野艇，无路入安车。","山犬俄然吠，人来问起居。"]},{"t":"宋宗鲁七咏 其一 河渠春涨","f":"五言律诗","c":["积雨夜初歇，河渠向晓深。","岸平芳草没，风漾白鸥沈。","浩荡怀殊泽，澄清共此心。","龙门知远近，临眺一长吟。"]},{"t":"宋宗鲁七咏 其二 禾黍秋风","f":"五言律诗","c":["秋风村巷起，禾黍远依微。","古道无人过，晴空有雁飞。","已堪酬岁事，应欲问寒衣。","但得丰年乐，莼鲈慢忆归。"]},{"t":"宋宗鲁七咏 其三 柳岸晴烟","f":"五言律诗","c":["杨柳绿成蹊，笼烟水面齐。","啼莺深不见，骢马只闻嘶。","初日光犹暝，回风影渐低。","吟行易成趣，归路未应迷。"]},{"t":"宋宗鲁七咏 其四 槐庭清昼","f":"五言律诗","c":["密树荫虚堂，高林昼日长。","疏花閒自落，幽梦觉还忘。","宦达怀先志，栖迟惜众芳。","栽培各有待，非是学三王。"]},{"t":"宋宗鲁七咏 其五 蔬园剪雨","f":"五言律诗","c":["春山逢夜雨，剪韭入荒园。","绿润茨菰饭，寒生苜蓿盘。","时穷聊自给，身在任加餐。","肉食知谁补，齑盐重尔存。"]},{"t":"宋宗鲁七咏 其六 蓬户书声","f":"五言律诗","c":["幽人读书处，茆屋住林坡。","灯影留残月，书声隐薜萝。","风尘谈铗语，烟雨饭牛歌。","今日青云路，飞腾事若何。"]},{"t":"宋宗鲁七咏 其七 兰山雪色","f":"五言律诗","c":["穷阴连朔漠，积雪满山城。","不辨峰峦气，空闻涧壑声。","净涵书幌白，寒觉布衣轻。","怅望平林外，苍茫烟雾横。"]},{"t":"三鹭图","f":"五言律诗","c":["老树寒塘里，孤栖境最宜。","双行良有待，独立已多时。","跂足身将下，翘翎眼正窥。","画图深意别，托物重兴思。"]},{"t":"冷斋为僧作","f":"五言律诗","c":["寂境世缘绝，虚堂人迹稀。","厨空常遇食，岁尽或留衣。","窗月澹如水，薜萝沿入扉。","炎凉自有分，不是学寒微。"]},{"t":"登伍公庙东轩小酌","f":"五言律诗","c":["地迥廛居远，天空眼界明。","雨来江变色，风急树添声。","渺渺怀贤思，依依恋旧情。","酒阑人尽去，犹自立檐楹。"]},{"t":"醉渔","f":"五言律诗","c":["一棹清江曲，人称是醉渔。","酣馀逃物色，醒独感糟餔。","适意聊凭酒，生涯不为鱼。","陶然云水窟，高枕即吾庐。"]},{"t":"湖山烟雨图","f":"五言律诗","c":["曾见隐人说，湖山雨亦奇。","常因游荡冗，独觉静閒宜。","惨淡玄晖画，苍茫子美诗。","欲穷幽爽趣，坐待晚晴时。"]},{"t":"闰九月张用文宅赏菊","f":"五言律诗","c":["红芳骄白发，素质笑青娥。","晚色浓还淡，秋香寒更多。","赏心能几许，衰节欲如何。","安得常逢闰，年年两度过。"]},{"t":"为王瑞之题梨花图","f":"五言律诗","c":["西阁睡初觉，东君信已通。","莺声闭门雨，人影隔帘风。","病体娇不语，诗愁閒更浓。","无端肠欲断，云破月朦胧。"]},{"t":"竹泉","f":"五言律诗","c":["绿竹荫方洲，泉深竹更幽。","平安应永茂，沈静自长流。","秀并孤山晚，清分合涧秋。","凉风与华月，涵映共优游。"]},{"t":"阎文振马嵬八景 其一 杨妃荒冢","f":"五言律诗","c":["幸极多生变，恩深不到家。","宁归掖庭狱，得祸后宫斜。","鬼火消寒雨，魂香散落花。","犹胜莫皋妇，青冢乱胡沙。"]},{"t":"阎文振马嵬八景 其二 金城古寺","f":"五言律诗","c":["主家门第尽，僧寺树林荒。","色相真成幻，豪华未可常。","法轮回现灭，劫火变炎凉。","却笑浮生众，犹因佛老忙。"]},{"t":"阎文振马嵬八景 其三 北原春意","f":"五言律诗","c":["东风吹野草，春意忽依依。","烧迹绿初满，樵痕青尚微。","雨肥惊发遍，霜重较添稀。","为尔增惆怅，飞香欲上衣。"]},{"t":"为沈履德题水仙","f":"五言律诗","c":["夜玉笼金淡，春罗撷带柔。","湘皋留佩别，洛浦弄珠游。","地美姿容净，林孤气韵优。","无因坐芳艳，聊尔伴吾幽。"]},{"t":"寄陈彦章","f":"五言律诗","c":["一从分别后，梦想镇悠悠。","路远知难见，书来看转愁。","归舟烟月冷，故宅菊花秋。","物色将离思，年年江水流。"]},{"t":"雪泉","f":"五言律诗","c":["积素晚逾白，飞流寒更清。","阳和通地泽，云液晃空明。","不断平林色，遥闻落涧声。","最堪清夜永，吟待月华生。"]},{"t":"詹贰教望云思亲卷","f":"五言律诗","c":["闽海云飞处，严慈隔九泉。","天涯孤影在，客里寸心悬。","泪逐回风落，魂随去鸟旋。","微官是何物，常自别遗阡。"]},{"t":"荆妇堕齿有感","f":"五言律诗","c":["视舌知柔在，论心觉汝良。","动摇勤吐哺，疏豁厌糟糠。","未老何嗟及，无儿重此伤。","平生恩义在，诸妾共沾裳。"]},{"t":"为严仁远题兰","f":"五言律诗","c":["共说江皋种，元来是国香。","援琴人在鲁，糿佩客迷湘。","古调终难继，高怀不可忘。","谢庭春事好，三世见流芳。"]},{"t":"卧云","f":"五言律诗","c":["闻有西方士，幽居在白云。","日高窗漏曙，风静榻馀薰。","寝息收龙雨，冥栖伴鹤群。","悠然半间屋，无地著尘氛。"]},{"t":"竹庄","f":"五言律诗","c":["西村耕隐处，菉竹似云屯。","九曲不知径，千竿方到门。","幽期分少室，美盛亚淇园。","为问平安信，传芳见子孙。"]},{"t":"雪江为僧文秀题","f":"五言律诗","c":["澄静秋来水，苍茫腊后天。","空花迷浦树，远色见林烟。","冻绝横流潦，寒无泛浪船。","夜深清不寐，月到寺门前。"]},{"t":"瀛洲为锡山杨秀才作","f":"五言律诗","c":["曾到瀛洲路，清孤绝点埃。","浪香鱼易化，月爽桂长开。","壮志英雄步，弘文馆阁才。","升腾各有地，何必扣蓬莱。"]},{"t":"爱水","f":"五言律诗","c":["有美渊源士，名溶字净夫。","平生慕清润，重尔乐涵濡。","放浪怜三峡，深沉快五湖。","由来称知者，情好一尘无。"]},{"t":"送吴览用之还休宁","f":"五言律诗","c":["尊酒分携后，星霜七载间。","壮怜吾白首，少觉尔苍颜。","杜曲花时醉，山阴雪夜还。","来疏归转急，情绪各相关。"]},{"t":"梅野","f":"五言律诗","c":["东阁寻诗远，西湖载酒频。","惟应閒旷处，得老岁寒身。","地广冰霜伴，天空水月邻。","不须携杖探，满眼是阳春。"]},{"t":"为高宪副题画二首 其一","f":"五言律诗","c":["草尽白石露，林幽苍藓生。","不移君子节，如有故人情。","明月照秋影，凉风吹夜声。","凤川千亩废，顿觉数竿清。"]},{"t":"夏大卿西湖六会卷后","f":"五言律诗","c":["步屧苏堤净，寻玄瑞石遥。","蓬山小无暑，岩月满随潮。","宝石登天近，瀛梅候雪消。","太平游览遍，歌咏记清朝。"]},{"t":"雪屏","f":"五言律诗","c":["辟凿玄工旧，彰施素质齐。","天寒云母淡，风静玉花低。","银烛秋光尽，金闺雀影迷。","筠床吟对晚，欲与鹤同栖。"]},{"t":"芝田为嘉禾医士谈景阳题","f":"五言律诗","c":["曾到悬壶处，琼芝遍玉田。","居安灵气聚，济博寿徵全。","培藉松苓土，滋分石乳泉。","不耕尝自足，医道本通仙。"]},{"t":"桂岩","f":"五言律诗","c":["峻绝春芳少，高寒晚植荣。","人如月中下，地胜却林清。","书榻飘香落，琴坛倒影横。","岩头有云路，留待看花行。"]},{"t":"知休堂","f":"五言律诗","c":["世路终无尽，浮生总未然。","蚤停登峻马，急系下滩船。","富贵閒方了，功名退始全。","中山千日酒，不及醒时眠。"]},{"t":"重过月塘留题","f":"五言律诗","c":["幽居邻古寺，清兴每堪乘。","卧榻闻经梵，书窗映佛灯。","地偏稀有客，门静似无僧。","十载重相过，空缘却未凭。"]},{"t":"乌程贰教李春夫四首 其一 桥门奉侍","f":"五言律诗","c":["禄养知何日，依亲未可期。","聊凭菽水奉，得便寝兴时。","风木丘吾感，公庖考叔遗。","三年不归者，此意竟何思。"]},{"t":"乌程贰教李春夫四首 其二 泮宫迎养","f":"五言律诗","c":["木铎晨初举，亲舆暮已过。","禄嗟升斗薄，养比鼎裀多。","化雨连桥梓，文风振蓼莪。","不须经史训，身教易渐摩。"]},{"t":"乌程贰教李春夫四首 其三 西江考艺","f":"五言律诗","c":["奎壁腾辉蚤，钧衡入聘新。","由来斲轮手，解识运斤人。","剖璞求良玉，扬澜起伏鳞。","至今天上榜，多是鹿鸣宾。"]},{"t":"乌程贰教李春夫四首 其四 竭力荣亲","f":"五言律诗","c":["艺圃春芳盛，研田秋穑成。","都将一官俸，并作二亲荣。","带缓乌纱称，袍宽綵绣明。","推封事难必，随力报深情。"]},{"t":"为张士明题沈石田画","f":"五言律诗","c":["故人何处所，诗画转风流。","一雁斜阳晚，孤篷野水秋。","偶随云共往，时与月同留。","此外应无累，年高未白头。"]},{"t":"南谷僧真率处","f":"五言律诗","c":["荒径草生满，空堂夜不关。","焚香修竹里，絓衲野藤间。","淡朴堪离俗，疏慵始称閒。","客来无所事，瀹茗对前山。"]},{"t":"送余大尹","f":"五言律诗","c":["山郭惠风和，湖田好雨过。","鸣琴初住响，行旆又闻歌。","赴阙心应重，怀民梦亦多。","旌褒垂已及，天诏有馀波。"]},{"t":"黄山盛节妇挽诗","f":"五言律诗","c":["旌显非初望，归全是宿心。","痛怜双孺在，笑入九原深。","剑及延平化，珠还合浦沈。","生荣死更好，乡国有徽音。"]},{"t":"雪渔","f":"五言律诗","c":["放浪原无定，苍茫任所之。","一蓑堪入画，独钓雅宜诗。","清绝将谁偶，幽奇只自怡。","也知鱼不食，趣在水寒时。"]},{"t":"题陈白沙赠僧古渊诗后","f":"五言律诗","c":["西墅开馀景，东山异物华。","桓荣方在国，韩愈已辞家。","吟刻云扉竹，閒烹石鼎茶。","忘形忽相遇，不用具袈裟。"]},{"t":"南谷","f":"五言律诗","c":["渭水来何处，相传此谷中。","清深原地美，流洽出泉蒙。","自与沟渠异，何因鸟鼠同。","怜君重名义，知本意无穷。"]},{"t":"松月轩","f":"五言律诗","c":["丹房无所有，松月净林坡。","寒径春芳动，晴窗夜色多。","删繁容桂影，倚曲看金波。","共是无情物，玄虚意若何。"]},{"t":"南溪小隐","f":"五言律诗","c":["小隐南溪上，悠然世虑忘。","西来山气爽，东去水流长。","午日停诗舰，薰风满钓航。","北窗时一卧，人物似羲皇。"]},{"t":"送邢把总","f":"五言律诗","c":["世胄才相继，边荒借远过。","秋清閒虎旅，海晏息鲸波。","按辔消吟兴，投壶听雅歌。","太平功业早，胜算欲如何。"]},{"t":"萝薜山房","f":"五言律诗","c":["绝壑垂萝处，閒居称野心。","瑞烟凝古色，华月烛浮阴。","最爱琴书净，何烦花木深。","依栖聊自得，清淡胜东林。"]},{"t":"题晓岑卷","f":"五言律诗","c":["山居高寂景，最爱乍明天。","西岭月犹在，东林人尚眠。","晨光佳胜夕，朝气爽通玄。","日午红尘动，清华不似前。"]},{"t":"梅林小隐","f":"五言律诗","c":["老树荒林下，閒居意若何。","西湖防物色，东阁废吟哦。","径有幽人探，门无驿使过。","时时风雪里，携鹤步寒坡。"]},{"t":"宿玄真与故人叙旧","f":"五言律诗","c":["旷望三秋别，浮游百感身。","可怜前度客，不见旧时人。","老病催年尽，荣华过眼新。","直须同畅饮，一醉尚青春。"]},{"t":"槐庭","f":"五言律诗","c":["共说幽庭里，槐阴蔼绿云。","郤林通桂影，谢砌逗兰芬。","驷马高门启，三公旧业闻。","堂中无所见，犹记老坡文。"]},{"t":"乐生堂为张汝声题","f":"五言律诗","c":["传得全婴术，提携日满门。","滋调同乳哺，和育似春温。","药施君臣剂，功深父母恩。","好移堂下杏，栽植近东垣。"]},{"t":"怀山堂诗赠医士","f":"五言律诗","c":["自是宾贤偶，由来治理宜。","都将良相业，敛作上工医。","内鉴悬金匮，心田产玉芝。","静山门下客，十病九怀思。"]},{"t":"病中述怀","f":"五言律诗","c":["偪仄幽栖处，衰迟鹤瘦翁。","伏经嗟有授，莱綵念何穷。","松映远林月，竹摇清昼风。","惟应旧山景，长与老怀同。"]},{"t":"挽乐义王公夫妇二首 其一","f":"五言律诗","c":["海邑誇名族，清时乐永年。","壶觞元亮宅，书画米家船。","门第多□梦，儿孙总象贤。","一从鸾鹤化，相忆每凄然。"]},{"t":"陈世用给事母挽诗二十韵","f":"五言古诗","c":["秦晋欢盟早，熊蛇吉梦全。","最深姑舅爱，兼为族人怜。","鸾凤威仪重，蘋蘩礼数专。","清真生合浦，温瑩照蓝田。","中馈烹调惯，通宵补缀便。","曾陪伯鸾语，识得孟光贤。","不愧关睢什，犹疑葛藟篇。","文孙初及第，令子夙超迁。","夜雨惊炊臼，悲风入断弦。","可怜黄屋诰，不到白头年。","医扁今为土，巫咸已上天。","膏肓不可问，脩短竟难宣。","迤逦瑶池燕，招摇玉洞仙。","麻姑留宿驾，王母授真诠。","恩念俱牢落，尘缘总弃捐。","深情空戚戚，清泪转涓涓。","薄奠馀三鼎，荣光贲九泉。","已酬尊养愿，其奈别离牵。","魂梦应何在，音容益黯然。","云迷淮海月，霜冷越江烟。","懿行新成传，贞铭已就镌。","孤坟在何许，千里卜牛眠。"]},{"t":"韩方伯母挽诗","f":"五言古诗","c":["世泽传邹国，休声启相门。","三迁遗教在，诸族母仪尊。","婉娩胡然在，柔嘉重尔存。","良人留粉署，令子起青云。","明镜秋光冷，慈帏夜色昏。","可怜春草念，不返夜台魂。"]},{"t":"哭内十二韵时年十七","f":"五言古诗","c":["笄总承归聘，青春媾悯凶。","褰帷惊落雁，属纩怨乘龙。","夙抱衾裯苦，未遑组织工。","弦琴悲窈窕，中馈失仪容。","垂绝啼沾臆，临危噎抚躬。","平生怀冀缺，今日愧梁鸿。","弟妹江关外，姑嫜疾疫中。","宗姻稀袒免，馀服杀期功。","陇庙馀班祔，箕裘冢命空。","永怀愁不寐，长恸意无穷。","草绿閒门雨，花明后苑风。","年年桃李树，凄绝旧行踪。"]},{"t":"刘公秉望云思亲六韵","f":"五言古诗","c":["极目云飞处，伤心汉水阳。","氤氲迷陇树，杳霭护祠堂。","渐逐悲风起，低随落日黄。","梦魂怀屺岵，涕泪满羹墙。","寥落经秦岭，凄凉忆太行。","家山死别处，不及在他乡。"]},{"t":"郜文晖杏雨轩八韵","f":"五言古诗","c":["最爱知时雨，幽居杏子林。","遍滋枯瘁质，潜布发生心。","一郡怀芳润，千家沐浸霪。","药阑春正好，橘井晚来深。","化泽应同溥，斜风莫乱侵。","种花人冒湿，问酒客迷阴。","国手怜非相，时名愧作霖。","愿驱收谷虎，蓑笠此投簪。"]},{"t":"送陈理之袭职还温州二十韵","f":"五言古诗","c":["督府元勋在，名藩阃制崇。","祖孙俱挺萃，父子尽登庸。","台阁丹青古，河山带砺同。","兼资文武略，翊赞圣神功。","信是箕裘美，生当化运隆。","自天承宠命，随地答宸衷。","驰志燕山北，还家浙水东。","建牙归旧镇，抗节赞元戎。","气压干城器，机深国士风。","暂辞莱子服，重挽楚人弓。","鹰隼飞扬外，熊罴指顾中。","安危都注意，战守欲全工。","坐觉烟尘净，行看瘴海空。","此期知不忝，良会惜难逢。","宧况清秋月，离怀远塞鸿。","婵娟共千里，聚散等孤篷。","酒尽情难尽，诗穷兴未穷。","悠悠忠孝愿，到处与君从。"]},{"t":"作古木图题寄刘廷信都宪十韵","f":"五言古诗","c":["郁郁中山木，生来夐绝伦。","栽培元得地，挺拔易逢春。","秀美藏中盛，英华发外新。","苦心终自保，直节待时伸。","独立冰霜后，清当雨露辰。","乔然超桧柏，俯若庇荆榛。","荐庙升华栋，为舟绝要津。","用因材大晚，事类梦求亲。","霁月岩廊表，春潮野渡滨。","甘棠不重见，凄断旧游人。"]},{"t":"梦萱八韵","f":"五言古诗","c":["萱亲不可作，魂梦每相随。","寂寞知何自，苍茫忽见之。","虚中闻叹语，空里见容仪。","多在倚门处，或逢携幼时。","都忘形隔绝，犹学旧娇痴。","委曲生前话，凄凉觉后悲。","留连长及旦，定省已无期。","莫说忘忧事，年来鬓已丝。"]},{"t":"送张佥之广东八韵","f":"五言古诗","c":["侍御才堪重，名藩借远行。","功高柱下史，官次省中评。","不懈澄清望，尤深讯鞠情。","羁怀连百粤，王事促修程。","问俗逢蛮堡，观风驻海城。","黄风深蔽马，白水净摇旌。","驿馔盘游饭，人输谷董羹。","豺狼易相辟，还欲访柴荆。"]},{"t":"李侯潮月图十韵","f":"五言古诗","c":["金水相生候，风烟既肃天。","夜分方盛大，秋半正清圆。","鳌背冰轮涌，蛟宫玉鉴悬。","星槎通桂殿，兔窟动龙泉。","势合阴精满，光摇气母旋。","大观同俯仰，佳景洞黄玄。","想见升沉际，回思合辟年。","诗工形不尽，画好思难传。","紫塞机堪速，丹心苦益坚。","因之崇显泽，文武继才贤。"]},{"t":"送僧归族十二韵","f":"五言古诗","c":["早涉真如境，旋闻博大风。","自从心有主，顿悟道非空。","典则羲农祖，诗书孔孟宗。","无为先有作，去惰始来功。","夷夏终天异，君亲亘古同。","是谁循错误，随处被牢笼。","欲破胶缠固，须凭识见崇。","力能排闼走，事胜倒戈攻。","近似兼人勇，相将盖世雄。","星流还拱北，澜倒竟回东。","复志三纲里，全身四业中。","能言距杨墨，于尔亦何庸。"]},{"t":"菜庵八韵","f":"五言古诗","c":["閒居无异卉，蔬植绕柴荆。","稼圃真吾事，齑盐藉尔营。","春烟芸麦秀，夜雨剪松明。","色瑩青藜饭，香兼玉糁羹。","馑思挑野俭，贫念采薇清。","淡薄堪长往，肥甘负远名。","可应存晚节，聊复任平生。","见说庵中客，年来百事成。"]},{"t":"廿六日复陪诸公游灵隐寺留题祥上人所十二韵","f":"五言古诗","c":["峻拔天垂秀，盘回地拱灵。","神峰腾北道，法界控南屏。","龙雨周三笠，鹏风合四溟。","楼台出霄汉，钟鼓隐雷霆。","咒食猿窥洞，闻经鹤避汀。","迷途登觉路，佳客借閒庭。","风帽秋曾落，云车晚再停。","黑头全变白，红树几还青。","踪迹迷鸿雪，光阴换鸟星。","谁知陶令醉，总是屈原醒。","旧事惊还问，新词厌复听。","凭吹剑头吷，题向冷泉亭。"]},{"t":"题淇澳晚节诗册寿王瑞之十二韵","f":"五言古诗","c":["星纪初周岁，风烟欲暮秋。","乾坤元并育，人物故同流。","汗简功仍在，纶竿志未投。","诗堪通比兴，居可事藏修。","不断平安报，终无代谢忧。","自招三径友，独迈七贤游。","樗栎材非偶，冈陵寿可侔。","椿阴交嶰谷，桂馥逗湘洲。","凤实金花结，龙孙锦箨抽。","园红低托荫，涧翠郁添稠。","老节俄生肘，清标直到头。","凭诗吴下颂，笺入卫风收。"]},{"t":"为王廷彦咏菊","f":"五言古诗","c":["细柳春营远，名花别墅幽。","生无桃李态，性本蕙兰俦。","干直偏宜挺，香清不厌浮。","根孤宁近石，叶老不随流。","冷节依然在，年芳重尔留。","荣兼汉公寿，饥慰楚臣忧。","苦竹映寒色，斜阳生暮愁。","偶为三径别，空负一年游。","彭泽真成晚，龙山别是秋。","所嗟生地迥，情会两悠悠。"]},{"t":"溪隐卷为秀水陈嘉言题","f":"五言律诗","c":["茆屋寄沧洲，溪深事事幽。","门无题凤客，岸有钓鱼舟。","放浪非狂士，浮沉混俗流。","犹疑人物色，不复被羊裘。"]},{"t":"休宁吴氏保训楼","f":"五言古诗","c":["奕奕千金训，峨峨百尺楼。","祖宗存世泽，嗣续赖贻谋。","尊阁图书并，收藏拱璧侔。","高登今有自，俯坠可无忧。","不敢希天禄，还应过邺侯。","是谁居末裔，为我踵前修。","无恤心常切，玄成业未优。","也须怀卜筑，岂独守箕裘。","孔壁遗经在，韩文败箧留。","一椽当重惜，只字莫轻投。","覆载真成耻，尘埋亦自羞。","好知垂后意，继述亘千秋。"]},{"t":"窗友张彦晖老未有字甚非古义予惟善不可以老辞过不可以老遂因字以士明为诗以寓箴儆","f":"五言古诗","c":["白发见重孙，名称尚未分。","是谁司冠礼，率尔缺仪文。","父命元当重，宾言已莫闻。","直须存古道，慎勿蔽时氛。","远迈工商业，高攀睿哲群。","因之坚晚节，风采抗浮云。"]},{"t":"周德辉景褚亭","f":"五言古诗","c":["已读昭忠录，重登景褚亭。","案头存史传，座右著心铭。","仰渴西江水，瞻尊北斗星。","守官思对御，还笏想惊廷。","馀力师文翰，高风企典刑。","居常形梦寐，动若接灵英。","斋宿严禋祀，炉燔播德馨。","封章意斯在，肯搆及千龄。"]},{"t":"姑苏吴氏佳城八景","f":"五言古诗","c":["窈窕双亲墓，风光尽可伤。","秋霜行浒墅，春雨泊横塘。","桥月影沉梦，寺钟声断肠。","狮山迷望翠，虎阜映愁苍。","岩照情随夕，湖波泪共长。","直须从葬日，心景两相忘。"]},{"t":"酬牛廷理八韵","f":"七言古诗","c":["文韬武略擅时英，亲奉除书下玉京。","黄阁才华新黼黻，锦衣人物旧簪缨。","登坛虎卫承恩蚤，射策龙门锡命荣。","两浙风尘行处息，九重日月望中明。","雄驱欲问云中骑，保障偏临海上城。","横槊吟成朝戏马，运筹奇出夜谈兵。","回天空有潼关梦，报主无由朔漠行。","欲问辕门歌吉甫，愿陈威德济苍生。"]},{"t":"寿刘叔温父八韵","f":"七言古诗","c":["东风吹暖到溪山，昨夜青牛已度关。","天上功名轻脱屣，壶中甲子类循环。","新春年谱须重纪，旧日诗笺手自删。","三世箕裘诸子贵，百年诗酒一人閒。","时开露积留人饭，自署遗经觅主还。","雨露有恩垂凤敕，林泉无梦入鹓班。","广文道出羲皇上，高士名存伯仲间。","好记遐龄千万载，岱宗高亘水潺湲。"]},{"t":"忆园梅十四韵","f":"七言古诗","c":["一从丘壑旷经巡，清赏依依感慨频。","竹杖芒鞋孤旧约，石田茅屋误芳邻。","冥怀邂逅琴樽远，浪说调羹鼎鼐亲。","喜有心期谐冷淡，耻因滋味较酸辛。","时逢杜老愁兼绝，诗许林逋句独新。","东阁凭阑空有赋，西湖放鹤更何人。","影迷白玉堂边月，香尽罗浮岭外春。","魂断素娥精欲落，梦回青鸟思无因。","繁华到处人长满，路径无媒草共湮。","清白欲随天地老，孤高甘守雪霜贫。","窗前夜到疑珠箔，墙角风多怅玉尘。","自是穷檐堪索笑，不胜羌笛解伤神。","家怜吴镇庵居好，画觉元章翰墨真。","老我归来清赏在，乱山寒秀对閒身。"]},{"t":"题画八韵","f":"七言古诗","c":["霄汉谁能问布衣，招寻偶复此相依。","溪山待老嗟行迈，名禄关心悟昨非。","树密林猿当径下，春閒江鸟向人飞。","舟经浩荡行将没，家入苍茫晚未归。","满地荒烟迷蔓岭，乱峰寒日照柴扉。","望穷尽处情兼远，坐到忘言思转微。","幽事独怜西涧草，清狂不种北山薇。","只应李愿归盘谷，人物于今一笑稀。"]},{"t":"为陈彦章题夏圭山水图五十韵","f":"七言古诗","c":["睡起虚窗拂素缣，是谁幽思发红纤。","毫端老健超能品，胸次清淳似古廉。","荆浩源流归险劲，范宽家法转精严。","韶光荡漾晴堪挹，元气淋漓润欲沾。","浓酝松薰滋玉兔，淡和花滴贮铜蟾。","山连巴蜀星霄近，水接荆吴分野兼。","缩地只疑传费诀，剪江应复用并镰。","左萦右绕全归海，东接西盘远际崦。","百浦一潮同橐籥，重冈千仞锁钩钤。","孤烟障岭浮将散，断石边崖侧渐阽。","岚霭半笼深嶂曲，黛痕斜抹远峰尖。","空潭潦尽清涵练，大麓泥深赤露磏。","鸣濑合流疑滑滑，乳鸦交翼想鹣鹣。","巢歌松鹤惊蓬狖，穴露蒿狐覆黍粘。","村犬有声穿碧筱，渚鸥和影落苍兼。","菰蒲荫密鱼依笋，榛莽丛深雉狎岩。","居近回塘驯野鸭，池通活水纵游鳒。","腴田报社禾初稼，高陇闻歌麦又蔪。","何处桑榆迟夕照，谁家门户得朝暹。","滩舂尽日鸣残碓，茆屋经冬脱故苫。","诸葛庙前千尺柏，杜陵堂外百年楠。","青摇败牖萝悬壁，绿遍閒庭竹蔽檐。","阴径莓苔荒宿荠，废园芜草没幽蔹。","岩坳扫砌云随帚，谷口停车树碍襜。","兰艇归迟争荡桨，荷亭坐久起掀髯。","汀州晚色催渔网，篱落秋香上酒帘。","桥板压波溪雨涨，船篷逼岸浪风添。","画中对景身如即，物外逢人梦亦忺。","小蹇凌兢思孟老，素琴潇洒类陶潜。","行怜红叶吟迂辔，瘦怯黄花醉下帘。","胜境可耕还可钓，茂林宜冷更宜炎。","贫嗟孺子长忧食，困惜坡翁不奈痁。","繁弱就韬弓㢮彀，干将沉匣剑藏铦。","心期落魄谁将许，态度疏狂众所嫌。","点检壮游悲往迹，摩挲老目寄遐瞻。","寻僧古寺已逢贾，卜宅名区已扣詹。","短策扶携灵运屐，残编零落邺侯签。","绝交书在从头写，招隐诗成信口占。","剩有馀篇充酱瓿，都无佳句付泥杴。","情怀去住栖芦雁，仕路艰难上竹鲇。","樗栎分甘侪草木，莼藜望不到梅盐。","病躯早解今非昔，世味重教苦作甜。","献纳非材羞押阖，太平多士笑飞钳。","山河带砺功难并，泉石膏肓兴未厌。","万事兴亡棋换局，一生明暗镜随奁。","行藏偶与时相际，荣辱分从手自拈。","日月飞腾双驿骑，乾坤俯仰一闾阎。","红尘劳役閒方了，白发光阴懒更恬。","势到急流宜有勇，机当退步复何谦。","惟馀后乐先忧念，抚卷令人愧仲淹。"]},{"t":"送孙先生归沐阳八韵","f":"七言古诗","c":["一从立雪过严冬，海北天南意万重。","鲁国书生多未化，关西夫子更难逢。","是谁惭负昌黎教，无地开陈安定功。","自古浮云能蔽日，于今死草又生风。","乡山归去冥鸿远，身世閒来野鹤同。","收拾青毡付儿子，提携绿酒醉邻翁。","名全更觉斯文重，道在何妨旧业穷。","惟有当时恩义在，天涯此别叹西东。"]},{"t":"刘廷信母遗德诗十六韵","f":"七言古诗","c":["生传徽懿死传芳，一节端居四十霜。","细读铭文知往事，漫凭哀些发潜光。","柔嘉不愧千金子，窈窕真堪百两将。","侍膳北堂尊俎具，采芳南涧藻蘋香。","声和琴瑟辉联玉，梦协熊罴喜弄璋。","自古物情妨两大，从来女事惜偏长。","惊看明月台前镜，破作龙泉匣底钢。","漏促鸡鸣连夜杼，灯移儿影上空床。","到门惟有遗金妇，感旧时来乳哺娘。","教养渐收贫古业，婚丧已尽嫁时装。","居幽眇若微尘寄，值乱几如断梗亡。","沟壑心期惭未了，铅华颊舌笑空狂。","荆钗短发何年白，宿草孤坟卒岁黄。","本为良人存世祀，不劳明府乞恩章。","忧伤太早生多病，冻饿全经死亦常。","千古东屏山下路，烟云星斗共苍茫。"]},{"t":"为干景瞻题唐高骈山亭夏日诗画十韵","f":"七言古诗","c":["碧山亭馆抱回塘，门巷阴阴夏日长。","新竹过林梢碍柳，野藤缠树叶迷霜。","炉香细引蔷薇架，庭草阴连薜荔墙。","画栋云閒天伏暑，疏帘风急雨生凉。","棋声落枕醒幽梦，楼影沉波近夕阳。","临水独垂盘谷钓，采莲新办越溪航。","何人隔竹敲茶臼，有客携琴问草堂。","望远欲穷千里目，吟馀空费九回肠。","功名自许今犹未，寒暑催人老又将。","会整旧书归旧隐，故园松菊晚苍苍。"]},{"t":"题石菖蒲六韵","f":"七言古诗","c":["一室萧然景最清，小池丛石细蒲生。","日长自觉閒情好，书罢还宜倦眼明。","行见有花昭上瑞，不须多节表虚声。","频呼稚子添新汲，静据胡床看晚晴。","楚畹幽期空自许，谢庭佳致蚤同盟。","凭君莫话崇高事，已伴琅玕进玉京。"]},{"t":"送陈太常致政十韵","f":"七言古诗","c":["都门饯别马騑騑，家在千山去路微。","一代衣冠嗟独往，两京词赋见应稀。","秋风送客浮云尽，江水迎人野鸟飞。","共说太丘閒更好，却嫌彭泽晚才归。","已将素学酬明主，犹有丹衷念琐闱。","尘梦觉来惊复定，物情閒后是成非。","门无候吏敲残漏，夜有邻翁款竹扉。","身世忽从何处落，功名始觉此心违。","林间倚杖看桑梓，雨外行歌种蕨薇。","莫为容台惜遗老，汾阳子婿尽朱衣。"]},{"t":"为王用诚题画十二韵","f":"七言古诗","c":["千里云峦际碧天，千村景色晓茫然。","上方楼观山间寺，远墅桑麻谷口田。","危石断桥人迹少，阴崖飞瀑水声连。","寒凝晻霭风光淡，暖入蘼芜草色妍。","门巷未经车马到，林泉宜有画图传。","隆中旧事遗梁甫，松下清斋学网川。","愧我已非盘谷侣，凭谁重和草堂篇。","机深转觉身多伴，心远从知地自偏。","无数尘缘消物外，几多佳趣到閒边。","垂竿薄暮临池坐，待月清秋傍石眠。","布袜青鞋从此始，草衣木食永相便。","何当共约归休日，縻禄犹须二十年。"]},{"t":"荣寿堂八韵为吴瑜壁都宪赋","f":"七言古诗","c":["九重封敕下明光，寿域阳和满画堂。","椿树润分萱砌绿，桂枝高倚柏台黄。","诗书已遂菑畬念，灯火全抛绩纺忙。","老去丰荣浑自得，年来行坐觉如常。","鱼轩豸服身同贵，鹤算龟龄日共长。","裀鼎几人能侍养，冈陵终古愿无疆。","百年伉俪云端凤，一世心期镜里霜。","为想堂前拜嘉庆，紫泥香透綵衣裳。"]},{"t":"哭刘公秉八韵","f":"七言古诗","c":["与君兄弟最多情，谁道中年两变更。","闻病只疑吟太苦，讣传浑似梦频惊。","心灰冷对寒灯烬，泪血潜随夜雨声。","人远北山孤鸐侣，天荒东海哭鸥盟。","青衫老我疏良会，白首怜君误此生。","望断夕阳云影散，魂迷池草月华明。","苍天竟负仁人寿，白石空题处士名。","吊罢灵帏见孤子，不胜清怨重沾膺。"]},{"t":"送杨太守六韵","f":"七言古诗","c":["关西清白旧相传，政事文章继两全。","仕路风尘将白首，客怀冰蘖尚青毡。","气凌华岳群峰下，志薄秦关百战前。","秋水月明霜满地，春风冻解日行天。","谁家陇亩无桑谷，到处民居有诵弦。","老我病归思借寇，重来未卜意萧然。"]},{"t":"挽王侍郎封公二十韵","f":"七言古诗","c":["蒿里歌残薤露终，百年遗响托悲风。","桥门倡义英声在，粉署谈兵旧迹空。","八座知名深赞画，四方多故见才雄。","中朝政事推司马，南国旬宣属召公。","幽谷阳春回棨戟，名区民庶仰藩墉。","官僚尽服澄清治，寇贼全消保障功。","江汉思归逢断梗，文园多病叹飞蓬。","已将素节酬明主，欲向青山学老农。","茆屋石田归有日，玉阶金阙会无从。","少陵老去诗名重，张旭生来草翰工。","静检羲文图太极，閒挥麈尾看参同。","箕裘更喜儿孙长，门祚何惭旧业穷。","芳桂色含椿树绿，古槐阴傍草堂浓。","禹钧自信多贤子，王旦人誇似乃翁。","为羡名驹空冀北，忽惊哀鹤返辽东。","盖棺自制尧夫赞，去国谁传洓水容。","风雨关河天万里，烟云山壑夜千峰。","凄凉景物孤愁绝，生死音尘百感通。","陇上夕阳迷客土，湖南春草梦归篷。","望穷秋影黄昏雁，泣尽寒声紫禁钟。","应有碑文题故友，能无纪传载文中。","不须听此频惆怅，赠典龙章出九重。"]},{"t":"画登高望远图送郑世昌赴广州提举八韵","f":"七言古诗","c":["少长同游事业俱，中年去住忽殊途。","白云门下春风歇，赤壁江头夜月孤。","早拟骅骝空冀北，晚惊鸑鷟振东湖。","连城已剖辉山玉，按剑犹疑照乘珠。","廊庙地高行易远，田园岁尽去应芜。","病怜送客思留客，閒觉今吾是故吾。","海市风波无旧侣，江村烟雨有莼鲈。","欲知别后怀君意，尽在登高望远图。"]},{"t":"寿诗","f":"七言古诗","c":["五十七岁未衰节，三百六旬初度辰。","半世平安逢盛旦，一年佳丽属芳春。","旧游曾作青山主，此会应多白社宾。","鸿雁有声群序近，芝兰无恙物华新。","图书满屋辉前业，里巷逢人总后尘。","惊看南天犹现极，喜闻东老未为贫。","是谁为作冈陵颂，爱尔长于翰墨亲。","满眼和风一樽酒，对君疑是葛天民。"]},{"t":"贺沈维仁纳粟冠带","f":"七言古诗","c":["日月馀光照海城，翩然林壑见蜚英。","庞公素有遗安业，孺子初无近禄情。","共许良心超族党，旋闻高谊动公卿。","承家自少能知节，居富于今善处盈。","金散不移东老志，官閒何负北山盟。","也知豺獭怀酬报，为竭涓埃答治平。","宅里旌添华屋润，冠裳荣耀素袍明。","千仓万镒空如许，赢得人称长者名。"]},{"t":"题李白观瀑图","f":"七言律诗","c":["两臂束蹙肩双攒，仰首挺立如禁寒。","平生斗酒百篇兴，似为庐瀑唫盘桓。","江东无人酒船返，黄鹤放归南道远。","绝倡从来和者稀，紫烟落日香炉晚。"]},{"t":"秋日漫兴四首 其一","f":"七言律诗","c":["云物萧条拂曙开，故园东望转堪哀。","孤城海气连云合，万树秋声动地来。","麟阁功臣多际会，凤台词客惯趋陪。","蒿莱今日惊尘起，欲赋惭非宋玉才。"]},{"t":"秋日漫兴四首 其二","f":"七言律诗","c":["吴门北上是长安，万里关河客路难。","原野草荒狐兔尽，江潭风起水云寒。","无舆漫击冯谖铗，当道谁弹贡禹冠。","总为黄花能待腊，年年长向雨中看。"]},{"t":"秋日漫兴四首 其三","f":"七言律诗","c":["书剑蹉跎雨未成，登临无限故园情。","黄金台迥秋天远，白玉楼空夜月明。","篱菊不禁清露重，征衣偏觉暮寒生。","山空木落无多日，海宇春风岁又更。"]},{"t":"秋日漫兴四首 其四","f":"七言律诗","c":["风雨周行蜀道难，每回回首益长叹。","黄金易尽秋云薄，华发无情晓镜寒。","塞雁北来天漠漠，夕阳西下水漫漫。","巫山万里知何处，可待襄王梦里看。"]},{"t":"送王廷显调官入闽","f":"七言律诗","c":["迢迢旌旆度辽阳，疋马南行去路长。","龙剑乍提三尺锐，蛇弓新挽百钧强。","严霜欲度槟榔熟，瘴雨初晴荔子香。","见说皇仁同覆载，少年随处答恩光。"]},{"t":"七夕有怀刘世亨","f":"七言律诗","c":["海城吴叶堕新秋，露坐中庭夜色幽。","微月遥随银汉转，清樽不共故人游。","曾闻玉殿传灯火，更想瑶台望斗牛。","千里相思应未寝，故园南望益离忧。"]},{"t":"贺刘世经新娶","f":"七言律诗","c":["洞房花烛照新妆，此夕相逢乐未央。","鸣雁有声冰始泮，牝鸡无语夜偏长。","采蘋拂曙游南涧，奉帚平明觐北堂。","官事不违中馈好，故人从此念糟糠。"]},{"t":"赴京辞亲","f":"七言律诗","c":["几年衰薄望成名，暂得微名又远行。","夜雨萱花偏有感，西风椿树正含情。","黄金秖为书收尽，白发惟因教子生。","安得登科亲未老，綵衣光照锦衣荣。"]},{"t":"别弟","f":"七言律诗","c":["堂上双亲鬓已华，莫因年少误生涯。","弟兄鸣世怀苏氏，群从能诗忆谢家。","天阙云依丹桂子，故园春满紫荆花。","孤舟明日沧江夕，愁见征鸿落渚沙。"]},{"t":"别篱应瑞","f":"七言律诗","c":["远携书剑上京畿，身在青云去路微。","千里关河成远别，十年诗酒叹多违。","梦回野渚生春草，愁入寒云见夕晖。","何似同登龙虎榜，长安车马共轻肥。"]},{"t":"别陈敬佐","f":"七言律诗","c":["并驾青云旧有期，著鞭今为祖生迟。","秋风旅馆思悬榻，夜雨书窗忆下帷。","世道正当全盛日，功名况是少年时。","沧洲明月孤吟处，回首令人感别离。"]},{"t":"酬陈彦章见寄","f":"七言律诗","c":["几年瘴海息波涛，棨戟重临不惮劳。","塞上风云严虎卫，营中新月照龙韬。","一身许国丹心在，百世传家素业高。","见说于今戎务少，秖应词赋日挥毫。"]},{"t":"松石轩","f":"七言律诗","c":["苍松白石护玄关，福地清高不可攀。","万壑天风吟倚处，一林明月醉眠间。","蓝田玉长云根出，王母书回梦鹤閒。","为问长生如可学，愿从服饵驻童颜。"]},{"t":"济宁道中","f":"七言律诗","c":["宦情离思共依依，极目关河四顾微。","千里风云随去马，五更霜露满征衣。","山连齐鲁居人少，地接淮扬故旧稀。","自愧才华非董贾，春风何日觐彤闱。"]},{"t":"追挽刘世亨父","f":"七言律诗","c":["白头无事出田园，清议犹能动至尊。","乡里衣冠推世德，海滨营卫仰馀恩。","鹤归华表仙人化，树满荒山古木存。","往事不须频太息，传家今已见曾孙。"]},{"t":"寄刘世亨兼简诸故旧","f":"七言律诗","c":["别后逢人每寄声，自怜多病托群英。","经纶有策怀先达，科第无才愧后生。","淡月疏钟京阙梦，白鸥烟水故园情。","雍容礼乐三千辈，日近清光仰太平。"]},{"t":"山行","f":"七言律诗","c":["溪山景物曙苍苍，溪上行人路渺茫。","极浦人家依岛屿，上方楼阁蔽岩墙。","鸟边云影孤峰小，山外泉声万壑长。","安得閒身随钓艇，时时来扣远公房。"]},{"t":"耕乐为吴江士人作","f":"七言律诗","c":["宦游京国久蹉跎，老去躬耕奈乐何。","田畯有怀时见候，农人无事日相过。","污邪水满菰蒲长，高陇春深菜麦多。","几度报田归去晚，醉中犹唱饭牛歌。"]},{"t":"植兰堂为仇克明","f":"七言律诗","c":["林下深期日共忘，年来移植近中堂。","清霜入佩幽怀远，落日援琴古意长。","剩有高风存九畹，更无馀物示诸郎。","太平时节人文好，非是閒居览众芳。"]},{"t":"挽顾士行","f":"七言律诗","c":["东吴回首每伤神，千里关河百战身。","旧业已随烽火尽，白头无复故乡春。","百年谱系雕虫细，半世功名马鬣新。","闻道辽东多野葬，死生高谊更何人。"]},{"t":"刘公瑞閒居六咏 其一 春陇耕云","f":"七言律诗","c":["漠漠阴云满太空，自驱黄犊事春农。","疏狂更喜儿童长，衰薄应须畎亩功。","水色微茫春雨后，歌声迢递夕阳中。","麻衣短褐浑相似，举世无人识卧龙。"]},{"t":"刘公瑞閒居六咏 其二 寒潭钓雪","f":"七言律诗","c":["西风吹雪满秦川，寒拥丝纶上钓船。","怅望平林飞鸟外，诗怀多在白鸥边。","羊裘高节真成癖，鹤氅清风欲山仙。","最爱晚来堪入画，一蓑披向酒家眠。"]},{"t":"刘公瑞閒居六咏 其三 西轩听雨","f":"七言律诗","c":["芳草池塘夜已分，一灯疏雨转纷纷。","分明瞿峡愁中听，彷佛巴山梦里闻。","海外故人嗟久别，天涯游子忆同群。","兰缸欲尽青毡冷，落叶萧萧自掩门。"]},{"t":"刘公瑞閒居六咏 其四 菊圃秋香","f":"七言律诗","c":["郊原秋日景凄其，三径黄风晚更滋。","为惜子瞻淹宦久，故应元亮去官迟。","东篱晚节兴怀感，南国佳人入梦思。","晓露晨霜易衰歇，岁寒心事更谁知。"]},{"t":"刘公瑞閒居六咏 其五 琴室松风","f":"七言律诗","c":["朱弦疏越纸窗明，时有松风绕户生。","林谷萧条孤月满，海天空阔片云轻。","心閒自悟无弦趣，坐久疑闻太古声。","几度夜深诗梦醒，猿啼鹤唳共凄清。"]},{"t":"刘公瑞閒居六咏 其六 书窗梅月","f":"七言律诗","c":["东阁梅开绕画阑，娟娟霜月下诗坛。","山河有影冰轮满，风露无声玉树寒。","歌罢霓裳人不见，梦回首鸟思无端。","却怜此夕孤窗月，纸帐香消独自看。"]},{"t":"送应司训入广","f":"七言律诗","c":["一官初得觐宸旒，又上湖南万里舟。","碧树青山妃子庙，夕阳芳草仲宣楼。","伫闻江汉归周化，莫为沅湘吊远游。","泮水传经如有暇，好题尺牍慰穷愁。"]},{"t":"送王司训赴临江","f":"七言律诗","c":["一鹗横飞碧汉间，远持木铎下朝班。","清江小艇鸥边渡，玉笥孤峰鸟外山。","叶落疏林云谷静，草深茆屋墨庄閒。","相逢尽是抠衣者，不用昌黎老抗颜。"]},{"t":"寄妻弟王宽秀才兼刘公贽","f":"七言律诗","c":["记得年来下第时，春风偶复遇佳期。","十年灯火黄齑饭，千里风云白玉墀。","滥进已为同辈笑，成名喜慰老亲思。","金台回首频惆怅，积雨新秋好下帷。"]},{"t":"送金都运","f":"七言律诗","c":["读罢离歌怅夕晖，不胜遥念忽依依。","同时谏诤几人在，当路交游强半稀。","云满冀城双阙迥，雪晴淮水片帆归。","前修未远徽音歇，羞逐清班侍紫闱。"]},{"t":"送赵尚敏","f":"七言律诗","c":["同游京国未能还，况尔离群怆客颜。","白首心期何日尽，青云踪迹几人閒。","一官远寄湖湘外，疋马遥驰岭海间。","东道已无相识问，愁来莫上九疑山。"]},{"t":"过梅庄怀旧","f":"七言律诗","c":["野梅茆屋石阑干，白首空山几度看。","纸帐梨云春梦冷，断桥残雪暮窗寒。","风光不减当年好，诗酒犹怀晚岁欢。","却忆种花人不见，陇头无信月漫漫。"]},{"t":"题孙廷兰郎中画四首 其一","f":"七言律诗","c":["江南三月风光好，淑景分明出世间。","春水河梁天上渡，夕阳楼阁画中山。","人来茆屋鸡声午，花落疏篱草色閒。","何日追寻休沐地，云萝绝壁漫跻攀。"]},{"t":"题孙廷兰郎中画四首 其二","f":"七言律诗","c":["薰风杨柳绿成蹊，村巷无人鸟乱啼。","水漫西畴春事歇，草深南浦夕阳低。","经旬卧起门常掩，三径荒芜路欲迷。","丘壑经旬时渐少，高居应有醉中题。"]},{"t":"题孙廷兰郎中画四首 其三","f":"七言律诗","c":["云物凄凉接晚晴，西风岩谷暮寒生。","山回古寺闻猿断，落叶疏林见客行。","斜日淡依孤岫没，野鸥閒傍钓船横。","南游记得湖亭路，白石沧波万里情。"]},{"t":"题孙廷兰郎中画四首 其四","f":"七言律诗","c":["岩谷萧条草树平，万山深雪一人行。","望穷寥廓不知夜，独立苍茫无限情。","几处乡关游子梦，半林灯火读书声。","琼瑶满地天如海，欲驾灵飙访太清。"]},{"t":"方节妇兵科给事中辅之母","f":"七言律诗","c":["沧波东去断魂归，镜里孤鸾静不飞。","宗祀有灵遗腹在，闺门多难一身微。","已甘白骨埋青野，肯许缁尘上素衣。","岂料旌封能待老，此生辛苦幸无违。"]},{"t":"送黄五禧还丰城","f":"七言律诗","c":["一别东吴又十年，相逢京国共依然。","浮名世事不长好，明月心期只自圆。","归梦欲迷南去路，乡书多问北来船。","窦家兄弟俱长健，事业应须各勉旃。"]},{"t":"送董廷瑞赴南台","f":"七言律诗","c":["圣主忧民重宪臣，绣衣持斧出枫宸。","范滂久负澄清望，赵抃生怀献纳勤。","肯使豺狼当毂道，坐令枯槁发阳春。","清霜烈日江淮路，莫谓相逢有故人。"]},{"t":"送王廷器妻弟南还","f":"七言律诗","c":["共说门阑气象新，客边相见亦情亲。","说车又是临岐日，咏雪应怀远送人。","北固楼台江树晚，西湖花柳故园春。","停鸾止鹄须高振，莫谓韶华误此身。"]},{"t":"挽张布政","f":"七言律诗","c":["万里云霄早致身，清时人物旧儒绅。","四朝宠遇推良弼，一代勋名属老臣。","青琐才高天上诏，紫薇花落梦中春。","经纶未尽英雄死，海水东流夜月新。"]},{"t":"游金粟寺寄湛璇二方外","f":"七言律诗","c":["金粟名山碧海边，上方楼阁近诸天。","人推转藏闻清梵，自洗残碑认往年。","南度龙章千古在，西来象法一灯悬。","登临不见怀人处，回首孤云思惘然。"]},{"t":"寄张公裕学正","f":"七言律诗","c":["一别云霄两载过，广文诗酒近如何。","客边醉眼青犹在，镜里流年白漫多。","雅度莫逢湘水吊，高才谁和郢人歌。","秋来几度怀风采，凉月辉辉满薜萝。"]},{"t":"送孔彦旭还阙里","f":"七言律诗","c":["莱衣千里上京师，文采雍容玉树枝。","对客共称佳子弟，过庭如见旧威仪。","重辟落月人归早，野渡清霜马去迟。","四海门墙千古意，因君日日起遐思。"]},{"t":"耕隐堂","f":"七言律诗","c":["石田茆屋住山深，老去惟馀物外心。","疏雨绿苗春满地，乱蝉高柳水平林。","将芜却笑潜身晚，用晦何烦抱膝吟。","独喜故家遗业在，年年诗酒契幽寻。"]},{"t":"寄寿李郎中外父","f":"七言律诗","c":["湖山佳致百年身，一半相忘醉里春。","华诞每逢南极老，清风自拟北窗人。","镜中白发秋容澹，蓠下黄花晚节新。","有客朝回望乡拜，太山高绝近星辰。"]},{"t":"送徐尚宝致仕","f":"七言律诗","c":["绿野堂前旧雨飞，黄金台下一人归。","当时门户依然在，世路风波忽已违。","清梦尚怀西掖树，閒情多钟北山薇。","汾阳子婿俱荣盛，五十悬车世所稀。"]},{"t":"林季聪父母挽诗 其一","f":"七言律诗","c":["一经科第著材英，五转儒官羡老成。","身在世间如大梦，人从死后见平生。","功名荏苒随年尽，心事凄凉共月明。","辽鹤何须作人语，五云中有凤雏鸣。"]},{"t":"林季聪父母挽诗 其二","f":"七言律诗","c":["霄汉频随凤侣飞，年来犹自密缝衣。","青灯夜雨人何在，白发秋风子未归。","魏阙恩荣鸾诰在，浔阳消息鲊书稀。","惟馀一片陇冈石，千古清光照夕辉。"]},{"t":"竹雪斋","f":"七言律诗","c":["小斋丛竹雪深时，景物年年似有期。","赋就梁园人卧晚，寒凝嶰谷凤鸣迟。","风敲碎玉晴还好，月转冰帘夜更宜。","安得閒身无一事，芒鞋相访共题诗。"]},{"t":"送许道中致仕","f":"七言律诗","c":["千里山川入旧游，风尘满地草堂幽。","西周事业归黄阁，东鲁衣冠见白头。","鸥外渔歌孤棹雨，鸟边诗思乱峰秋。","悬知此别成长往，谁道功名不自由。"]},{"t":"陈缉熙先垄六咏 其一 吴山朝旭","f":"七言律诗","c":["曙日初逢宿雾开，馆娃宫外冢累累。","鸣鸾不见孤鸾下，晞露疑闻化鹤回。","隐映祥光辉草木，茏葱佳气满楼台。","一从埋玉高冈上，几度凌晨祭扫来。"]},{"t":"陈缉熙先垄六咏 其二 震泽秋蝉","f":"七言律诗","c":["乱峰如抱水萦回，明月当空绝点埃。","明月不随流水去，秋风无复旧人来。","思家贾客应同感，信宿渔歌莫浪催。","长夜寂寥魂已断，天光云影为谁开。"]},{"t":"陈缉熙先垄六咏 其三 光福烟光","f":"七言律诗","c":["华表西林晻霭中，霏霏拂拂梵王宫。","寒凝海日晴还暝，横入松梢远更浓。","暮景苍茫冲断雁，客愁冥漠度疏钟。","无端忽被风吹散，怅绝天涯望眼空。"]},{"t":"陈缉熙先垄六咏 其四 海云茶屏","f":"七言律诗","c":["小院名花自㫺年，先公曾此访通禅。","秖应独立凉风后，得伴长斋绣佛前。","残雪压枝云母重，暝烟浮叶凤帷鲜。","也应见物怀亲爱，时折幽芳供几筵。"]},{"t":"陈缉熙先垄六咏 其五 寄心修竹","f":"七言律诗","c":["云林幽绝绕琅玕，地接荒坟几岁寒。","宿草残碑深不见，清风明月静相干。","隆冬有笋嗟何及，古冢赓诗迹未刊。","僧化旃檀佳客去，可能日月报平安。"]},{"t":"陈缉熙先垄六咏 其六 古庙乔松","f":"七言律诗","c":["败屋长松碧藓滋，野人相见说当时。","摩挲尚记儿童戏，盘屈惟应鬼物知。","长恐风雷腾老干，每因赛社斫新枝。","近来时有辽东鹤，飞下寒梢欲语迟。"]},{"t":"送徐编修弟还吴","f":"七言律诗","c":["金兰玉树每相联，聚散无凭共一天。","芳草池塘催别梦，夜窗风雨惜芳年。","北堂燕綵黄昏话，东阁看云白昼眠。","两地应须各努力，天涯此去只潸然。"]},{"t":"为徐时用题谢廷循画","f":"七言律诗","c":["湖上春光接贵游，湖阴山水独宜秋。","林泉老我双蓬鬓，风雨还家一钓丹。","望远时登黄叶寺，采芳多伫白蘋洲。","相看独有南州士，高卧孤山百尺楼。"]},{"t":"己丑除夜","f":"七言律诗","c":["四十分符刺一州，四年归病卧沧洲。","惭随世俗论青眼，自叹功名负黑头。","身事淡如幽涧草，心情閒似曲江鸥。","炎凉冷暖年年在，每到今宵一醉休。"]},{"t":"庚寅除夕","f":"七言律诗","c":["六六光阴又九年，细将新事较从前。","风云语步都成错，冰雪心期益自坚。","隔院笙歌闻别调，满庭灯火散浮烟。","诗成留待明朝写，閒伴春风上锦笺。"]},{"t":"赵驿丞湖曲草堂","f":"七言律诗","c":["十里湖山一草堂，年来岁月坐相忘。","林间野鹤閒随杖，槛外沙鸥欲近床。","风雨夜迷和靖宅，烟花春满杜陵庄。","如何忽作青云别，三径萧条归梦长。"]},{"t":"耕学为刘侍御赋","f":"七言律诗","c":["插架诗书负郭田，此生清意满林泉。","一犁时雨春方竹，尽夜寒灯晓未眠。","访隐何人经白屋，传家有子付青毡。","年年报社人都醉，独自关门草太玄。"]},{"t":"寿靖远伯","f":"七言律诗","c":["行专鈇钺坐蕃宣，生际承平八十年。","日下五云光甲第，梦中八翼上钧天。","清时文物龟麟出，白首勋名将相全。","不用相寻赤松去，九重深念老臣贤。"]},{"t":"汀州哭崔惟正","f":"七言律诗","c":["别来三月叹蹉跎，落日惊看逝水波。","清泪欲乾还自落，羁愁未遣又添多。","英雄有死嗟谁在，欢会无期奈老何。","十五年前旧游事，不胜哀戚动邻歌。"]},{"t":"送周民表进士养病南还","f":"七言律诗","c":["走马看花未尽情，白云官舍坐澄清。","愁多顿觉归心急，吟苦谁怜渴病生。","高阁晴云舟凤远，画船秋水白鸥轻。","不须会唱阳关去，千里家山衣锦行。"]},{"t":"送薛九公子","f":"七言律诗","c":["侯家孙子擅风流，长向江湖作胜游。","一饮剩拚鸲鹆舞，百金曾买鹔鹴裘。","柔风杨柳春当座，弱水芙蓉夜满舟。","犹有故家遗烈在，时时含笑看吴钩。"]},{"t":"挽陈南海","f":"七言律诗","c":["海色苍凉宰树阴，百年人物此消沉。","杏花春雨匡庐远，茆屋秋风杜曲深。","白首一官终旧隐，清樽孤鹤费长吟。","相看惟有燕山桂，恩泽于今满故林。"]},{"t":"松崖为许处士杰","f":"七言律诗","c":["满地松阴石径斜，萧疏横似野人家。","窗涵水气秋偏蚤，座有书声地转佳。","凉逗晚风清鹤梦，冷和残雪映梅花。","岁寒节操应相待，不是閒居爱物华。"]},{"t":"李载章独鲤图","f":"七言律诗","c":["桃花春水漫滔滔，一跃龙门万丈高。","十载江湖淹物色，九天雷雨奋雄豪。","谁人见辙能怜鲋，何处垂纶欲钓鳌。","自古成材须泽世，为霖有待作波涛。"]},{"t":"归良辅六十寿诗","f":"七言律诗","c":["曈昽初日照林扉，静露心香祝太微。","半世清风将白首，一阳生气到斑衣。","物情自昔明消长，身世从今觉是非。","江使已通灵贶集，寿星中朗鹤南飞。"]},{"t":"东坡雪竹","f":"七言律诗","c":["风捲残云暮雪晴，天空野树水烟横。","凄迷望断平安信，衰薄如逢太瘦生。","月冷冰梢清入骨，霜交疏影澹无情。","岁寒物色多相似，到此方知晚节成。"]},{"t":"老君像","f":"七言律诗","c":["太史传疑迹未磨，犹龙人物更谁过。","流沙西去青牛远，函谷东来紫气多。","文字五千流绝简，虚无八九藉馀波。","元玄台下孤松老，节错根盘奈尔何。"]},{"t":"为许明夫题金碧山水图二首 其一","f":"七言律诗","c":["珠林琼岛锦江滨，桃李东风满眼春。","金碧楼台何处尽，丹青图画几回新。","中山古道多行径，北海寒波隔要津。","白发题诗思何限，少陵已是倦游人。"]},{"t":"为许明夫题金碧山水图二首 其二","f":"七言律诗","c":["佳气茏葱映海霞，乱山环翠水生华。","笙歌不空渔樵地，岩谷偏多佛老家。","金屋藏春帘结绮，锦軿迎旭扇笼纱。","太平人物欢游盛，回首芳春日易斜。"]},{"t":"送薛公子","f":"七言律诗","c":["娇歌急管送春辉，春色薰人上锦衣。","花压玉山人尽醉，云随金勒马如飞。","鲈鱼江上诗情远，燕子楼中客梦微。","此去不须成怅望，桑弧蓬矢愿无违。"]},{"t":"寿曹绣衣廷章父","f":"七言律诗","c":["海屋添筹豸拥冠，寿星光映紫微寒。","早来同甲谁相似，老去承恩古亦难。","春向百花庄上满，人从五老画中看。","列卿御史中书宅，莫道非熊梦已阑。"]},{"t":"迎碧堂","f":"七言律诗","c":["茆屋临深面面开，虚明无处著尘埃。","苍茫晚色烟中起，晃漾晴光雨后来。","静绿侵衣人傍槛，空青入座水生苔。","诗成却爱沿流咏，蘋蓼香中有钓台。"]},{"t":"寿刘侍御母八十","f":"七言律诗","c":["朝廷有道家无事，八十年来见太平。","婚嫁及时诸子在，闺门如水一身清。","龙章到日心应满，鹤发逢秋眼倍明。","如记北堂萱草畔，年年此日庆长生。"]},{"t":"相文吉裕陵进香还任","f":"七言律诗","c":["千里遥持一瓣香，钧天无路觐先皇。","翠华想像宸仪远，玉几弥留末命扬。","终古山川归永宅，九霄日月丽重光。","东风不尽昭陵泪，回首空江烟水长。"]},{"t":"贺崔千户中试","f":"七言律诗","c":["广场初日照戈矛，一骑红尘忽过沟。","弓影横开孤月满，剑光飞决白云浮。","勋名不废先公业，谈笑能分主将忧。","好趁少年能事日，玉关千里觅封侯。"]},{"t":"严侍御提学南直隶赋得骢马行春卷送之","f":"七言律诗","c":["使君骢马出康庄，千里江淮淑气长。","南国尽兴周礼乐，西京不改汉文章。","衣冠总被阳春泽，草木犹沾化雨香。","不独澄清眼前事，百年桃李在门墙。"]},{"t":"送夏大尹复任江西","f":"七言律诗","c":["昔年曾共杏园游，物候惊新野水流。","霄汉六年长在客，云山千里又逢秋。","微霜夜度吴门树，疏雨凉生楚客舟。","作邑如君应有待，不须樽酒慰离愁。"]},{"t":"题菊邻卷","f":"七言律诗","c":["风露萧条一草堂，四邻惟有菊花黄。","清连魏圃秋容澹，疏映陶篱旧宅荒。","穿径杳无鹅鸭恼，过墙犹讶蝶蜂忙。","只应晚节长亲并，不减当时碎锦坊。"]},{"t":"寄吴东升","f":"七言律诗","c":["辕门歌管振芳辰，翰墨穷工世绝伦。","铗气犹寒弹后月，笔花空晚梦中春。","盛时郎将乌纱旧，幕府儒宾白发新。","二十知名今共老，相逢不是薄游人。"]},{"t":"辰州高指挥竹轩","f":"七言律诗","c":["百战功垂万户侯，绿云高隐草堂幽。","平安不是青门日，萧瑟犹惊紫塞秋。","一枕寒声疏雨歇，满庭凉影夕阳收。","门墙远带湘江意，何日相寻乐醉游。"]},{"t":"游朱协律山房","f":"七言律诗","c":["欲寻勾漏问丹砂，因过玄都羽士家。","壶里有天迟日月，洞中无路入烟霞。","书馀别院闻清磬，坐久空林见落花。","安得闻身如野鹤，共临秋水诵南华。"]},{"t":"再游朱氏山房用前韵","f":"七言律诗","c":["九转新成玉鼎砂，洞门深锁是谁家。","鹤书一寄连沧海，凤管双吹隔紫霞。","旧雨重来前度客，东风又发去年花。","何当了却平生事，馀向山间老岁华。"]},{"t":"题菊坡秋芳图","f":"七言律诗","c":["岁序年芳似水流，栖迟风景老丹丘。","斜阳疏影和人瘦，夕露寒香伴鹤愁。","开口笑逢今日醉，满头狂忆少年游。","柴桑旧隐知谁在，烂漫残花独自秋。"]},{"t":"湖山归隐诗为周佑推官作","f":"七言律诗","c":["东湖山水绕柴桑，旧隐归来业未荒。","兰泽秋风群雁下，草堂春雨百花香。","林泉久屈周颙节，诗酒今同贺监狂。","人事已周身事遂，白头清世趣何长。"]},{"t":"寿阳武侯祖母鄞国夫人","f":"七言律诗","c":["白发朱颜迈八旬，五朝门第太夫人。","侯封庆衍曾孙蚤，伯爵人誇宅相真。","鄞国仪章金作凤，主家供具玉为麟。","洞门潭府梅花月，千古同含不老春。"]},{"t":"张侍御汾溪六景 其一 汾溪雨霁","f":"七言律诗","c":["东风吹雨过山溪，霁景无穷入品题。","花落平林春水漫，草深高岸夕阳低。","天光荡漾群鸥下，云影苍茫野棹迷。","几度临流坐忘返，夜深随月转荒溪。"]},{"t":"张侍御汾溪六景 其二 马步夕阳","f":"七言律诗","c":["路转荒村隔断湾，古桥斜日映青山。","苍茫影里长虹卧，款段声中驷马还。","枯木残鸦行客尽，野烟寒水钓舟閒。","济川功业知相待，莫道侵寻暮景间。"]},{"t":"张侍御汾溪六景 其三 凤山秋晚","f":"七言律诗","c":["凤山十里郁崔嵬，曙色初升霁色开。","万壑晴云连碧落，满林凉露湿苍苔。","霏微灏气催寒蚤，晻霭晨光入户来。","几度东篱閒眺久，悠然相对菊花杯。"]},{"t":"张侍御汾溪六景 其四 松涧鹤鸣","f":"七言律诗","c":["千尺乔松古涧隈，绿阴满地鹤飞来。","清音雅合琴中调，传信应从海上回。","孤馆昼眠诗梦醒，九皋人静客怀开。","劝君莫作辽东语，好叶韶钧入凤台。"]},{"t":"张侍御汾溪六景 其五 南馆书声","f":"七言律诗","c":["溪南书馆隔幽林，灯火通宵岁月深。","断续晓随鸡唱歇，咿唔寒共漏声沈。","饭牛辞古怀高节，弹铗歌长见苦心。","今日青云轩冕贵，还应不负买书金。"]},{"t":"张侍御汾溪六景 其六 东江渔火","f":"七言律诗","c":["落日渔舟趁晚潮，夜深渔火乱相交。","江空野水和烟汲，月黑黄芦带雨烧。","风急柳梢光欲灭，浪平沙际影还摇。","惟应南馆书窗下，夜夜青灯伴寂寥。"]},{"t":"顾文之进士养病还姑苏","f":"七言律诗","c":["飘飘词气欲凌霄，翠竹苍梧玉树标。","酒病渐疏潘岳鬓，诗怀新减沈郎腰。","杏花春雨江南梦，淡月疏星蓟北朝。","身在故乡心恋阙，未应踪迹混渔樵。"]},{"t":"寄范处恒","f":"七言律诗","c":["苍茫无路入林扃，草色缘阶竹绕庭。","满地烟霞朝采药，一天星斗夜吹笙。","兴来自拟骑鲸客，醉后多临相鹤经。","何事白云閒出岫，远携官绶下明庭。"]},{"t":"舟中与徐文海叙旧追赋旧事三首词虽婉媚意实经常总不能效丽则之言然亦非香奁体也 其一","f":"七言律诗","c":["龙髻盘云翠作翘，绣鞋尖小束轻绡。","鳞鸿附托芳心许，弟妹传呼小字娇。","彩凤竟分萧史伴，黄花瘦减易安腰。","无端却忆朱帘下，手劈云香待月烧。"]},{"t":"舟中与徐文海叙旧追赋旧事三首词虽婉媚意实经常总不能效丽则之言然亦非香奁体也 其二","f":"七言律诗","c":["曾将玉杵捣玄霜，红叶无情逝水长。","明镜已孤鸾凤影，罗衣空染蕙兰香。","东风梦觉空凝涕，秋月诗成欲断肠。","唯有谢家兄弟在，时时相见一凄凉。"]},{"t":"舟中与徐文海叙旧追赋旧事三首词虽婉媚意实经常总不能效丽则之言然亦非香奁体也 其三","f":"七言律诗","c":["能书能赋复能棋，学得功成欲向谁。","阿大中郎真有意，参军新妇竟难为。","莫思旧事成新事，相见閒时即闷时。","闻道赤绳先系足，可能重和白茅诗。"]},{"t":"追挽郑良载","f":"七言律诗","c":["君门蚤乞此身还，白首心期石壁山。","喜有文章归大雅，恨无金紫列青班。","行云逝水应何在，尘世浮生总是閒。","却爱谢庭兰玉茂，依然清誉满人间。"]},{"t":"江山胜览为维扬张明之题","f":"七言律诗","c":["万里江山接故乡，十年诗酒任疏狂。","黄河西去龙门远，清渭东来剑阁长。","一骑寒云登五岭，孤舟明月度三湘。","何当收拾天涯兴，归卧维扬旧草堂。"]},{"t":"八月十九日与张良甫宿彭城风雨有作","f":"七言律诗","c":["夕阳初挽上洪舟，邂逅彭城此夕秋。","世事关心多感慨，故人相见易淹留。","对床风雨疑前梦，举目江河念昔游。","幽话更长秋夜短，不禁钟鼓起谯楼。"]},{"t":"张道士雪崖","f":"七言律诗","c":["冬来积雪满尘崖，清赏都归物外家。","绝磴高寒春尚早，古坛虚白夜无哗。","望中乍失青城路，深处应开玉树花。","留得岁寒终古意，年年幽寂卧烟霞。"]},{"t":"登子陵祠","f":"七言律诗","c":["南游重上富春山，高节清风竟莫攀。","苗裔尚存寒士业，松堂长伴客星閒。","千山秀落双崖里，一水名高四海间。","日暮长歌山下去，隔江犹有钓船还。"]},{"t":"夜行舟中闻笛","f":"七言律诗","c":["白露青枫夜色寒，何人吹笛向江干。","风回浦溆滩声合，月落关山客梦残。","金殿几时闻旧吹，画楼何处倚危栏。","天涯早已难为听，况复怀人泪不乾。"]},{"t":"除夕风雨卧病郡斋","f":"七言律诗","c":["萧萧风雨到閒庭，愁病相兼酒易醒。","身外功名何潦倒，眼前儿女尚伶仃。","清霜客鬓随年白，芳草云山入梦青。","底事夜深眠不得，自烧银烛看医经。"]},{"t":"过皇恐滩","f":"七言律诗","c":["曾于信史见遗名，今日番从此路行。","极目烟霞迷石浪，满船风雨起滩声。","分明瞿峡西游处，彷佛梁山北去程。","独有孤臣怀国意，东流不尽故时情。"]},{"t":"寿沈廷贵母夫人张氏","f":"七言律诗","c":["封章频沐圣恩覃，眼底年华七十三。","八座功名劳主馈，九重侍从见宜男。","花迎淑气春方好，蔗近秋风晚正甘。","想到高堂称庆日，锦衣华发共清酣。"]},{"t":"送王元昭赴中都","f":"七言律诗","c":["淮西留守去何之，千里春江草绿时。","圣主有怀汤沐地，官曹不忘大风词。","投壶别野清游惯，运甓空斋独卧迟。","君是玉门班定远，可能高枕废驱驰。"]},{"t":"送薛九南游","f":"七言律诗","c":["旧家公子擅风流，十载江湖赋远游。","一饮不辞鸲鹆舞，千金新买鹔鹴裘。","神游湘水云生浦，梦觉阊门月满楼。","犹有故家遗烈在，几回含笑看吴钩。"]},{"t":"过伍公矩宅","f":"七言律诗","c":["湖头秋水映楼台，湖上荷花几度开。","西塞风烟游子返，北山猿鹤故人来。","閒谈旧事心先醉，坐惜流光晚又催。","清兴满怀消未得，欲呼渔父共馀杯。"]},{"t":"病还部议未许将北行","f":"七言律诗","c":["双鬓苍浪野兴生，静依疏柳听秋声。","一身未老心先老，万事无成病早成。","门巷萧条归似客，江湖飘泊住还惊。","如何岁晚青山下，犹有天涯未了情。"]},{"t":"咏草为刘公觐","f":"七言律诗","c":["几度阴阴几度晴，年华不改旧林坰。","风霜满野根都白，天地无心叶又青。","浓伴客愁迷远道，澹随诗思到閒亭。","蘼芜万里湖南路，一片萧疏绕洞庭。"]},{"t":"班婕好团扇图","f":"七言律诗","c":["宠辱由来事不常，佳期未必永相忘。","君恩偶为炎凉换，妾意终当箧笥藏。","粉黛香消金屋妒，熊罴梦反玉簪祥。","旧怀寥落新愁并，长信宫前草又黄。"]},{"t":"月波亭","f":"七言律诗","c":["明月流光水上头，凭栏对月思悠悠。","江湖万里何人共，天地百年今夜秋。","桂子香生翻兔药，芦花影动泊渔舟。","此情欲借清商发，抱得瑶琴不自由。"]},{"t":"丙戌除夕舟次富阳","f":"七言律诗","c":["三百九旬今夜尽，四十二年明日来。","功名荏苒老将至，红尘汨没朱颜催。","庭帏咫尺如万里，飞梦复绕黄金台。","明年今夜知何处，卧听寒潮心转哀。"]},{"t":"和陈彦章见寄用钱学士原韵二首 其一","f":"七言律诗","c":["蚤期功业誓河山，未到封侯惜暂閒。","飞将霸陵逢醉尉，孟尝函谷滞晨关。","和烟芳草凝愁发，带雨寒潮载梦还。","身在江湖心魏阙，几回寒暑念民艰。"]},{"t":"和陈彦章见寄用钱学士原韵二首 其二","f":"七言律诗","c":["草堂尊酒对南山，身外功名似梦閒。","老我病辞青琐闼，看人生出玉门关。","垂杨野渡虚舟泊，古木荒林倦鸟还。","离合悲欢总回首，可应头白尚多艰。"]},{"t":"戊子除夕","f":"七言律诗","c":["前年此夕泊钱塘，去岁寒灯卧草堂。","客路风霜閒亦扰，故乡诗酒病还狂。","送穷漫学车船戏，逐疫新翻傀儡装。","最喜家门尽强健，綵衣称庆醉椒觞。"]},{"t":"雪中偶书","f":"七言律诗","c":["江南三白兆丰年，最好湖山晚霁天。","沽酒欲迷归市路，捕鱼还见出浜船。","云连野色和烟暝，人共梅花待月圆。","不是梁园词赋日，也随清景一陶然。"]},{"t":"许廷冕留咏亭","f":"七言律诗","c":["曲水流觞事不迷，山亭浑似浣花溪。","情閒野渡舟横晚，思入空梁燕落泥。","谁向松间寻旧作，自从竹下刻新题。","山灵不管诗人倦，草绿烟明鸟乱啼。"]},{"t":"采芳艇","f":"七言律诗","c":["十里湖山一叶舟，年芳荏苒水东流。","闻歌白苧聊相和，欲采青蘋不自由。","杜若洲空逢断荇，菰蒲渚浅趁轻鸥。","涉江风雨芙蓉老，远道深秋已倦游。"]},{"t":"再游宝所","f":"七言律诗","c":["负郭岩扉敞石坛，上方门径绕层峦。","楼观海日夜先曙，竹引湖风夏亦寒。","林外歌声泉出谷，水中人影钓扬竿。","何当雪月烟花候，来共山僧信宿看。"]},{"t":"范德章金台对雨诗卷","f":"七言律诗","c":["南北追携共一身，对床风雨夜纷纷。","醉疑瞿峡愁中卧，寒忆巴山梦里闻。","白发孤灯人望远，绿波芳草雁离群。","何年得似彭城会，剪烛论诗坐夜分。"]},{"t":"雪村书舍","f":"七言律诗","c":["积雪空林晚乍晴，小窗孤榻罢韩檠。","光摇竹简芸窗净，寒入梅花纸帐清。","坐久却疑更漏断，夜深兼借月华明。","洛阳旧隐如相问，为报袁安素业成。"]},{"t":"送刘绣衣兄还江西","f":"七言律诗","c":["黄金台下驻春晖，千里江山疋马归。","淮浦东风芳杜合，楚江烟雨鹡鸰飞。","重来会见声华著，此去无令信息稀。","独有惠连伤远别，天涯回首各沾衣。"]},{"t":"为丰参议题柳岸春风","f":"七言律诗","c":["林塘三月柳依依，摇飏东风近竹扉。","旋逐歌声飘舞席，淡随春气入罗衣。","落花满路啼莺歇，芳草凝寒燕子飞。","自是平泉行乐处，风光不与赏心违。"]},{"t":"送徐用济太守还金溪","f":"七言律诗","c":["飞盖云随画舫还，不须童稚候柴关。","南州旧隐文章显，中世高风富贵閒。","松竹未交秋节后，桑榆犹在午阴间。","年芳正好故人去，一曲清湖绕碧山。"]},{"t":"和王瑞之旅怀见寄","f":"七言律诗","c":["万卷图书一苇航，不因流落滞遐方。","行迟秖为山留坐，閒绝惟应酒送忙。","旅馆风烟多胜日，故园桑梓未斜阳。","秋来亦有归飞燕，王谢堂高是异乡。"]},{"t":"山水图","f":"七言律诗","c":["水车声急绿阴肥，水漫鱼罾白鸟飞。","斜白照林停晚牧，新蒲近渚映春衣。","采莲歌唱时将及，竞渡风光事已非。","望断五湖舟去远，月明应有市船归。"]},{"t":"为吴方伯写海天秋望图","f":"七言律诗","c":["老树荒山海上头，碧天沈水不胜秋。","乾坤定位东南缺，江汉朝宗日夜流。","人世劳生真渺粟，仙家何处是浮丘。","凌虚不见扬尘处，风送云涛起蜃楼。"]},{"t":"画秦山书屋图","f":"七言律诗","c":["茆屋幽深草树中，早来心迹暮还同。","锥毛有铁词峰隐，灯壁无邻眼照空。","桂殿秋香天外月，龙门春涨海边风。","惟应诗画消长日，惭负赓歌作绘功。"]},{"t":"云山访隐图","f":"七言律诗","c":["独向青城访隐君，岩扉深杳路氤氲。","山翁采药不知处，童子迎人犹闭门。","斜照入林松影乱，回风出涧水声分。","晚来再问经行地，指点春峰顶上云。"]},{"t":"雪窗夜读图为沃饶文裕","f":"七言律诗","c":["万树阴沈雪乍晴，两峰寒寂涧流声。","玉京有路春何处，银海无波几变更。","明月到窗松火尽，斜风穿榻苧帏轻。","残编未了清无寐，不为梁园赋不成。"]},{"t":"送于宪使致仕","f":"七言律诗","c":["乱山孤骑大江船，跋涉艰危二十年。","一代凤麟天下士，四方霖雨梦中贤。","黄金台古安车远，绿野堂空昼锦旋。","留得清忠表台谏，娟娟秋月照霜天。"]},{"t":"竹溪书屋","f":"七言律诗","c":["竹林书舍语溪头，万玉丛深一水流。","凉气入帘湘帙润，绿阴当户石床幽。","偶乘淇澳诗人兴，又起沅湘旅夜愁。","雅颂不忘清节在，春风行见凤来游。"]},{"t":"墨梅","f":"七言律诗","c":["淡烟寒水野桥边，风景依依似腊前。","远道荒凉迟驿使，空山摇落见流年。","凭阑东阁春当座，载酒西湖月满船。","羌笛何须怨三弄，青青如豆更堪怜。"]},{"t":"为牛文振题墨梅飞白竹二首 其一","f":"七言律诗","c":["林谷无媒草蔓缠，岁寒心事只依然。","长因远道逢人寄，忆得空山独夜眠。","随处月明容野梦，几分春色上吟肩。","别来风雨频摇落，犹自幽閒是往年。"]},{"t":"为牛文振题墨梅飞白竹二首 其二","f":"七言律诗","c":["风度长疑带雪看，凭谁留兴入轻纨。","素鸾有影当窗见，清籁无声特地寒。","霜落渭川秋惨淡，月明湘水夜迷漫。","平生雅操今犹在，颜色萧疏节未残。"]},{"t":"席间答景瞻景章诸同游","f":"七言律诗","c":["二十五老不常好，三百六旬如掷梭。","镜中白发已如此，湖上青山将奈何。","清会有诗兼有酒，佳人能舞复能歌。","从来得丧都如梦，何必惊誇春梦婆。"]},{"t":"题乾坤一草亭","f":"七言律诗","c":["杜陵野老身如寄，家住千山独掩扉。","万事浮沈遗搆在，百年离合旧邻非。","乱山风雨催吟尽，永夜星河照影微。","不独南阳卧龙事，子云词赋未应稀。"]},{"t":"题魏尚书和周彦充诗","f":"七言律诗","c":["客窗孤榻坐新凉，展卷超然古意长。","韩魏从来重师鲁，苏公早已识元章。","百年人物归吴越，千古文章迈汉唐。","见说东园老无恙，西风寒并菊花香。"]},{"t":"乙卯三月再游胜果寺书事","f":"七言律诗","c":["清霜落叶寺门前，十载重来问老禅。","胜事几回芳草歇，旧游无复盛时全。","江分吴越横通海，山近蓬莱直上□。","便欲移尊穷绝顶，不堪风雨惜残年。"]},{"t":"李汉祥退閒诗","f":"七言律诗","c":["男婚女嫁已阑珊，断送浮生作大閒。","不是逢僧聊半日，直须投老入孤山。","潮平野渡虚舟泊，日昃寒林倦鸟还。","车马自喧心自逸，满庭芳草荜门关。"]},{"t":"沈士容母寿诗","f":"七言律诗","c":["南山高拱北堂幽，五色衣裳映白头。","勿药病消元有喜，如冈寿永合忘忧。","蟠桃秀结三千岁，樛木阴深八十秋。","满目曾玄太平世，百年家庆荷馀休。"]},{"t":"黎沧洲邀饮灵隐小酌永福僧舍","f":"七言律诗","c":["灵鹫山高石窦空，冷泉亭外树茏葱。","人行绝涧春无雨，花落深林夜有风。","山水增妍词客在，衣冠寻乐故人同。","舞雩沂水歌游歇，尽说兰亭翰墨工。"]},{"t":"三月晦日游龙井","f":"七言律诗","c":["倦扶残醉过湖堤，物候催新客思迷。","桑柘林疏蚕事促，菰蒲水浅鹭行低。","泉声落涧龙渊近，山势凌空鸟道齐。","苦欲相留留不得，晚风斜日杜鹃啼。"]},{"t":"送温州挥使陈汝玉朴庵之孙","f":"七言律诗","c":["四世簪缨见祖孙，六朝鈇钺卫将军。","清英不忝千金子，雅厚元从万石君。","剑蓄灵光彻牛斗，兵凝朝气待风云。","送君不尽怀人恨，目断江东旧雁群。"]},{"t":"再游灵隐寺","f":"七言律诗","c":["三月春深日日晴，桃花未落柳阴清。","素罗衣薄松风淡，斑竹兜轻石路平。","盛世多才惭独往，客游无处写閒情。","倦来更欲缘溪步，为借寒流一濯缨。"]},{"t":"四月九日阴佥宪邀游西湖","f":"七言律诗","c":["海道行春兴未孤，南风迎节下西湖。","天分瀛屿三山地，人在潇湘八景图。","巢阁诗翁今在否，龙门游客到曾无。","相逢已尽登临乐，酒罄芳樽莫再沾。"]},{"t":"醉中用前韵寄所知","f":"七言律诗","c":["漫道西园旅况孤，一春光景四游湖。","笑辞粉绿陪歌管，戏索丹青写画图。","纵笔题诗千首易，倒囊酬客半钱无。","白头取醉应非昔，不用邻船借宿酤。"]},{"t":"为阴佥宪题画","f":"七言律诗","c":["千古江山旧物华，可人风景自清佳。","浮尘不到渔樵地，胜境元无佛老家。","石径逢秋多杞菊，水亭留客盛茶瓜。","晚来风急鸥群散，一片澄波映落霞。"]},{"t":"松鹤图","f":"七言律诗","c":["松老巢空日半矄，碧山高绝鹤成群。","三分浮雪凝珠树，一片飞琼隔彩云。","阴涧长鸣双子和，晴皋孤唳九天闻。","平生毛羽皆清白，不带蓬栖野雉纹。"]},{"t":"春意图为隐佥宪题","f":"七言律诗","c":["钧阳几日动灰葭，转眼韶光遍海涯。","发育共怜春有脚，残伤谁谓鼠无牙。","兰篁地近森将老，杞橘林阴宿未华。","一种东风生意别，月光应照不毛家。"]},{"t":"沧洲清趣卷","f":"七言律诗","c":["竹篱茅屋住沧洲，风景宜人岁序幽。","水漫鱼梁穿笱下，雨漂凫藻近窗流。","歌声夜落秦淮月，诗景凉通楚泽秋。","清浊浮沈总如许，晚将心事托虚舟。"]},{"t":"听雨为朱元素题","f":"七言律诗","c":["残灯照影倚踌躇，潇飒声中泪点俱。","衾枕夜寒身独在，池塘春草梦全无。","风凄败叶悲荆瘁，水涨平沙怯雁孤。","忽忆彭城对床事，不胜清苦一长吁。"]},{"t":"姑苏伊佥宪父寿诗","f":"七言律诗","c":["元朝元夕喜相催，吴水吴山淑气回。","人遇良时跻耄耋，境当佳处拟蓬莱。","五湖鸥鹭恩波阔，一代衣冠寿域开。","最好儿孙忠孝在，弃官终养蚤归来。"]},{"t":"稼轩","f":"七言律诗","c":["富贵功名淡欲忌，幽居无恙乐时康。","豳风世远茅绹在，莘野人非畎亩长。","白鸟近畦苗合秀，黄云映户稻生香。","不知桃李园中景，何似柴桑旧草堂。"]},{"t":"送伍举人舜广","f":"七言律诗","c":["颙颙文采下蟾宫，步历青云路几重。","秋草香闻周野鹿，春雷声促禹门龙。","连城白璧新辞璞，百鍊黄金正在镕。","此去蓬山知不远，看花应上最高峰。"]},{"t":"和于景瞻王瑞之岁暮述怀兼咏梅竹二作因以见彼此之情 其一","f":"七言律诗","c":["天时人事渐阑残，蓬户萧疏海邑寒。","世路亡羊先自息，清琴别鹤更谁弹。","青山有地堪投老，白发无人可遣安。","岁晚西湖歌舞歇，暂应容把钓鱼竿。"]},{"t":"和于景瞻王瑞之岁暮述怀兼咏梅竹二作因以见彼此之情 其二","f":"七言律诗","c":["莫看南枝与北枝，每因词赋见心期。","为怜宋老风云气，不减逋翁水月姿。","已发荣华随处赏，未开情思几人知。","一帘淡月清宵永，谁似窗前忽到时。"]},{"t":"题徐元玉莲塘胜赏词后","f":"七言律诗","c":["十里红芳载酒行，兴来谁复顾阴晴。","无端此会聊相偶，有约重来恐未成。","击楫声孤人语歇，济川名重客舟轻。","风光想像湖湘路，欲借遗文吊贾生。"]},{"t":"赠张相士","f":"七言律诗","c":["阅遍寰区二百州，江湖无处不追留。","疑从单父城边见，曾逐麻衣道士游。","黄发年中知老大，白衣丛里识公侯。","相逢为问来秋事，笑指青云一点头。"]},{"t":"张佥宪湖山行乐图","f":"七言律诗","c":["江湖情思庙堂身，行尽吴山两度春。","范老不先天下乐，苏公岂是宦游人。","菊松有待归应晚，琴鹤相忘贵亦贫。","他日悬车定何处，午桥庄上杏花新。"]},{"t":"挽孙孟玙医士","f":"七言律诗","c":["生刍束玉见无因，宿草荒烟怅望频。","转眼忽惊千古别，到头谁是百年人。","海边明月伤心夜，湖上青山掩泪春。","惟有匡庐杏花树，东风依旧岁华新。"]},{"t":"吴汝秀求先人诗集序有作","f":"七言律诗","c":["湖桥春水泊轻舠，冒雨相过重尔劳。","喜见伯温编击壤，惭非元晦叙离骚。","絷驹此夕閒空谷，鸣鹤何时彻九皋。","芳草王孙又归去，客边聊为一挥毫。"]},{"t":"再送欧员外","f":"七言律诗","c":["越水吴山近寂寥，秋来到处动歌谣。","司徒乡土簪缨表，科甲文章锦绣标。","千里星霜劳使节，九重雨露下宸霄。","元功自有玄圭锡，好副民风十二条。"]},{"t":"陈大尹秦淮书屋","f":"七言律诗","c":["短墙幽径草纤纤，流水浮光四绕檐。","藜杖近分天禄火，芸编新絓邺侯签。","鱼龙变化书连屋，奎壁森罗月满帘。","一束囊携人去后，旧帏穿榻闭清严。"]},{"t":"闻郑子高参政讣","f":"七言律诗","c":["一自同舟下第归，重联书剑上春闱。","青云得路故人散，白首还家往事非。","漫有束刍怀远道，空惊宿草闭玄扉。","伤心不似当年别，目极南天泪满衣。"]},{"t":"甲寅二月晦日雨霁会饮朱彦明庄上","f":"七言律诗","c":["林梢曙色映朝霞，沙净春堤步落花。","负郭有田清世业，高居无事野人家。","檐空剩插清明柳，山近先烹谷雨茶。","不是青春壮游处，暂随歌舞乐年华。"]},{"t":"竹鹤轩为马浩澜题","f":"七言律诗","c":["琅玕娟净羽衣鲜，彷佛湘君驾月旋。","见实何年随凤下，报安常日有书传。","烟梢滴露秋先警，雨筱惊风夜不眠。","桃李无情莺燕别，凭留声节上芸编。"]},{"t":"松石行窝","f":"七言律诗","c":["静老山林故有期，行轩移凿是何时。","阴连绝壁云孤峭，枝压浮峰雨半欹。","十载风霜寒士节，万间梁础大方姿。","陶潜已去元章远，岁晏斋空只自怡。"]},{"t":"吴栖云挽诗","f":"七言律诗","c":["人去沧洲岁几何，青山芳冢郁松萝。","生荣未尽安车召，死别犹惊鼓缶歌。","东道高怀宾客在，南州旧族子孙多。","云栖不逐秋风散，閒待辽阳化鹤过。"]},{"t":"送吴汝贵谪官入闽","f":"七言律诗","c":["旧家人物盛时贤，粉署知名又十年。","六月鹏程应一息，千金龙剑暂孤悬。","江城歇马春将尽，山馆闻鸡夜不眠。","倏忽相逢便相别，宦情乡思各依然。"]},{"t":"兰谷","f":"七言律诗","c":["石屋幽深小径斜，繁芳删尽地清华。","坛荒尚谱宣尼操，畹废犹存屈子家。","霜净独馀凋后叶，泉香时泛落来花。","南州高士元萧散，入室无人亦自嘉。"]},{"t":"题古画","f":"七言律诗","c":["山净浮云水净烟，清宁风景是何年。","沿村古道无戎马，近渚幽亭有钓船。","惨淡画图人已远，凄凉题咏世犹传。","小窗风雨无人夜，彷佛清猿到耳边。"]},{"t":"于景瞻宅赏牡丹花时已过感而有作呈诸公属和 其一","f":"七言律诗","c":["惜花无奈看花迟，孤负春风第一枝。","急景最怜将落候，芳心还忆未开时。","赏因多病难胜酒，吟到无题别是诗。","分付东君好培护，与花先定隔年期。"]},{"t":"于景瞻宅赏牡丹花时已过感而有作呈诸公属和 其二","f":"七言律诗","c":["何处相携宴牡丹，年年三月在长安。","也知白首联诗坐，不似青春把酒看。","罗幛无风香气暖，金盘有露玉容寒。","故情不逐韶华改，遍倚斜阳十二阑。"]},{"t":"钱舜举云山秋景图","f":"七言律诗","c":["百里溪山一色秋，岭云汀树共悠悠。","何人欲著閒居赋，有客将归远道游。","林外渔樵黄叶渡，水中亭馆白蘋洲。","风光满目知何处，不是吴州是越州。"]},{"t":"甲寅三月登吴山怅然有作","f":"七言律诗","c":["游适时频趣转浓，少年吟眺已成翁。","从教白发三千丈，不尽青山百二重。","海接江湖通郭水，市连丘壑碍楼峰。","登能作赋人谁是，俯送浮云散碧空。"]},{"t":"为阴佥宪题马湖府土官知府安鳌族谱","f":"七言律诗","c":["瓜瓞绵绵世泽饶，远从西汉到天朝。","山湖带砺藩垣久，江汉朝宗海岳遥。","华胄直须家谱悉，累功还见史书标。","于今四表重光被，九族都应仰圣尧。"]},{"t":"毛处士八十寿诗","f":"七言律诗","c":["寿星光彩烛南天，白发逢春八十年。","世际七朝人物泰，家传四世子孙贤。","西湖杖屦开行馆，北海尊罍列庆筵。","记取十年须一会，还应两度醉花前。"]},{"t":"赤壁图为严仁远挥使题","f":"七言律诗","c":["新秋时节又新冬，两度登临谪宦中。","歌歇洞箫清对客，梦回孤鹤醉推篷。","百年诗赋遗文在，三国江山旧业空。","聚散升沈一樽酒，尽随残雪踏飞鸿。"]},{"t":"画秋山图有题","f":"七言律诗","c":["荒烟野树满重丘，人在青山最上头。","直北关河燕月暮，向南鸿雁楚云秋。","閒登古寺寻僧话，独立危岩看水流。","莼菜时香鲈正美，西风不见季鹰舟。"]},{"t":"黎今俊沧洲卷","f":"七言律诗","c":["悠悠书剑易蹉跎，一卧沧洲岁月多。","断卷秋风回驷马，小亭春水浴群鹅。","醉醒无复江潭问，清浊何劳孺子歌。","见说云溪有图画，故人诗酒意如何。"]},{"t":"追挽何都宪祖考妣","f":"七言律诗","c":["一生丹穴一岐阳，瑞凤祥凰两颉颃。","嶰谷何年谐律吕，高冈初日焕文章。","天留落羽群雏出，人说来仪百鸟翔。","不是辽东华表鹤，双归应复五云乡。"]},{"t":"何都宪望泮楼","f":"七言律诗","c":["重庆堂西百尺楼，登临如在泮宫游。","一方礼乐观瞻便，数仞门墙眺览周。","文庙地高通月殿，泮池水满入瀛洲。","青衿故是君家物，日日凭栏望未休。"]},{"t":"何都宪重庆堂","f":"七言律诗","c":["阶下芝兰满屋香，庭前桥梓再重行。","徽名早著登科录，盛事宜标世宅堂。","敕诰定联云锦轴，儿孙齐著綵衣裳。","只应万石君家似，世德相传福履长。"]},{"t":"阙里孔远文占籍杭州年七十以夏大理贺诗求和为赋一律","f":"七言律诗","c":["落落犹存尔雅风，年高七十未成翁。","家传东鲁衣冠后，人在西湖水月中。","玉立清秋千岁鹤，云停霁晚两高峰。","不知海屋筹添未，昨夜安期有信通。"]},{"t":"四月十三日游灵隐二首 其一","f":"七言律诗","c":["清和时节最宜人，忘却东风已过春。","犹有落花随水尽，渐看幽竹出墙新。","十年壶榼嗟为客，五亩园居待卜邻。","游赏事同情趣别，前湖歌舞正通津。"]},{"t":"四月十三日游灵隐二首 其二","f":"七言律诗","c":["灵鹫峰边合涧东，风光不与昔游同。","春蚕作茧柔桑尽，社燕移巢旧巷空。","风荡泉声犹振激，雨阴山色久溟濛。","结茆便欲岩栖老，时物惊心归兴浓。"]},{"t":"武克显博古堂诗","f":"七言律诗","c":["净几明窗翰墨香，故家文物满芸房。","画图不混古今笔，简册常分品第装。","老我每因清事到，为谁重整法书忙。","从来鉴赏非时好，绝胜王家宝绘堂。"]},{"t":"江村一曲","f":"七言律诗","c":["一曲清江碧四围，江村日日净涵辉。","烟深柳色迷花坞，风急蘋香满竹扉。","巢燕飞閒应识主，汀鸥眠熟惯忘机。","不知杜甫题诗处，景物于今似此非。"]},{"t":"沈元节父母挽诗 其一","f":"七言律诗","c":["耆旧凋伤不忍闻，愁将薤露作招魂。","百年故物青毡在，半世推恩紫诰存。","高冢松梧秋冷淡，旧堂花竹月黄昏。","欲知死后生前事，满眼芝兰盛子孙。"]},{"t":"沈元节父母挽诗 其二","f":"七言律诗","c":["金藏玉蕴美相宜，景及桃夭是盛时。","箕帚分甘姑舅喜，闺门庆协圣明知。","重闱日永春何丽，樛木阴深晚更滋。","今日北堂寒雨夜，有人长恸蓼莪诗。"]},{"t":"甲寅中秋会饮张用文宅待月","f":"七言律诗","c":["何处衔杯看月圆，两峰庭院石阑边。","山河倒影冰轮满，星斗藏辉玉烛悬。","白发丹心秋几度，篮桥青琐夜何年。","醉来索共嫦娥语，谁似风流李谪仙。"]},{"t":"画雪松送柳太守北上","f":"七言律诗","c":["景物凄迷野色荒，空山岁晚见孤芳。","凌高气劲缘萝断，覆下阴深弱筱长。","根到幽玄枝亦古，心含和煦叶都香。","严寒历尽阳春布，天为王家老栋梁。"]},{"t":"送汝举人赴礼闱二首 其一","f":"七言律诗","c":["圣主重华世泰和，四门清辟启贤科。","云垂龙虎开天榜，风动麟凰廓礼罗。","小雅笙歌周宴古，大方文字汉京多。","吴江自与天池接，快见鲲腾际海波。"]},{"t":"送汝举人赴礼闱二首 其二","f":"七言律诗","c":["宾鸿时渐鹿和鸣，天路无尘野有萍。","运启六飞升帝极，文同五纬聚奎星。","雕弓中鹄犹弯矢，宝剑抟犀乍发硎。","见说禹门春未化，年来三月少惊霆。"]},{"t":"题俞章怀椿卷","f":"七言律诗","c":["肠断高林泪迸泉，萧萧风叶夕阳天。","春秋望绝八千岁，日夕愁过百万年。","有约松筠空自好，无情桥梓为谁妍。","燕山路杳人何在，丹桂寒香益惘然。"]},{"t":"白都阃携牲酒相访夜酌有作","f":"七言律诗","c":["小山斜日晚生阴，红烛青尊坐夜深。","制阃多才超武举，匡时有策起儒林。","明良自感非常遇，老病空谈未迈心。","不是春宵花月宴，也应一刻直千金。"]},{"t":"平湖吴伯谐大尹见过别后有寄","f":"七言律诗","c":["驻马琼林醉绮筵，手分霖雨下南天。","轩墀虎卫仍相待，枳棘鸾栖只暂迁。","自昔兵民同化美，于今文武见才全。","欲知茂宰清平治，胥吏无能岁有年。"]},{"t":"贺人纳粟冠带","f":"七言律诗","c":["自献籯金报治平，不因干禄为时名。","邑分十室有忠信，义出千人是俊英。","宅里旌添华屋润，冠裳荣称素衣清。","东南多少轻肥者，满执牙筹过一生。"]},{"t":"正月十三日雪","f":"七言律诗","c":["腾六回车路未遥，又随青女候元宵。","未应柳絮因风起，剩见葭灰过律飘。","阴壑冰澌鸿迹去，阳坡草茁烧痕消。","兴来便欲行吟出，十二街中遍寂寥。"]},{"t":"题画","f":"七言律诗","c":["晴山隔岸绕江流，沈绿浮青浸未收。","谷口烟萝黄鸟树，水中莎草白鸥洲。","林空宜有幽居客，川广堪容待渡舟。","南去北来人扰扰，不知何处可攀游。"]},{"t":"题秦溪八景诗册有怀朱文海","f":"七言律诗","c":["渔牧耕樵绕涧阿，四时风景逐时多。","唱闲晚犊歌停调，云破春犁雪满柯。","日落桐林海月上，岚收石屋晚钟和。","秦溪旧境年年似，物在人非奈尔何。"]},{"t":"王汉昭招饮步总管庙留题僧舍","f":"七言律诗","c":["不用湖山事远游，海城东畔小瀛洲。","谁言闹市无閒地，自觉浮生是荡舟。","梁燕岁归僧渐老，庭花时发水还流。","一觞一咏青春暮，烂醉何妨下榻留。"]},{"t":"丙辰二月雪庵上人邀饮小楼见杏花有作","f":"七言律诗","c":["何处招寻泛羽觞，高楼花近净年芳。","荒村暮雨曾沽酒，梵境春风不出墙。","老我重思曲江院，是谁今卧午桥庄。","相逢尽是凭阑者，莫道偷閒过竹房。"]},{"t":"送平湖吴伯谐大尹入觐","f":"七言律诗","c":["河阳桃李颂清宁，又唱离歌饯北行。","红日九重京阙梦，白云千里故乡情。","天颜有喜亲颜近，文选成功武选荣。","忠孝两全名位盛，壮游真不负平生。"]},{"t":"正月二日朱孟瑜宅赏灯是日有雪","f":"七言律诗","c":["爆竹烘炉炭未灰，朝元才罢赏心催。","鳌峰瑞应三呼起，火树花兼六出开。","老去喜逢春宴蚤，晦馀先借月明来。","临安旧事依然在，更待官灯上戏台。"]},{"t":"秋暮有怀杨熙春","f":"七言律诗","c":["问程知是到长沙，音信寥寥只自嗟。","孤枕客边应有梦，一身愁里似无家。","经秋古树留残照，临水荒城见暮鸦。","几度夜深寒不寐，潇潇风雨上窗纱。"]},{"t":"西林","f":"七言律诗","c":["瀼西佳致杜陵庄，曲径通幽入草堂。","日映松皋穿户淡，水流花坞过桥香。","条桑剪雨春蚕罢，败莠漂风晚稻长。","胜事不穷清赏足，直须诗画为传芳。"]},{"t":"题碧泉卷","f":"七言律诗","c":["仙家池馆绝嚣埃，一碧流泉近户来。","为爱秋清净如练，却嫌春蔓绿于苔。","迷津黑水应难濯，入海黄河去不回。","何似苍明长在目，天光云影镜中开。"]},{"t":"和徐学士琼送危昌言诗大朴之孙也","f":"七言律诗","c":["自是丹山五色雏，至今文采与群殊。","江湖浪迹惟琴剑，丘壑閒情有画图。","吴苑清霜枫叶落，楚乡寒月雁行孤。","相逢却忆先公事，惆怅才名老宦途。"]},{"t":"画云海图送于文远还新安文远时与景瞻京兆通谱以子恕奉祠而归","f":"七言律诗","c":["百年文武自高门，散合无凭世系存。","徽国衣冠遗旧范，吴山祠墓见云孙。","星辰拱极元同象，江汉朝宗会有源。","咫尺蓬莱人未见，高丘远海漫劳魂。"]},{"t":"游春图","f":"七言律诗","c":["柳陌桃溪处处和，兴阑归晚夜如何。","壶觞已罄厌厌饮，骑从行催踏踏歌。","满路风声啼鸟歇，隔墙花影月明多。","朱门未扣人先应，一点银灯出绮罗。"]},{"t":"张士明西郊野趣","f":"七言律诗","c":["数椽茅屋住西郊，野趣真成俗虑消。","临水偶垂无饵钓，登山时遇带书樵。","半村禾黍连深巷，五里轮蹄隔断桥。","闻道春城游赏歇，夕阳林下独逍遥。"]},{"t":"送蹇通判赴京","f":"七言律诗","c":["黄甲登名绣作衣，宦家中世似君稀。","提刑大振行台宪，佐郡全收侍殿威。","六月抟鹏聊一息，三年停凤又高飞。","悬知郭隗台前路，骏复天闲定不归。"]},{"t":"送王主事伯举抽分还部","f":"七言律诗","c":["数卷图书上驿船，飘飘文采似登仙。","司徒自古须经国，进士从来最得贤。","越北关津无滞贾，吴东山水有新篇。","悬知献纳丹墀里，五色云中一凤旋。"]},{"t":"送王文昭秀才还慈溪","f":"七言律诗","c":["风雅文章世宦名，西游未久复东行。","广场有藿驹难絷，清野无蒿鹿未鸣。","灯下雨声宾馆梦，江南晚色故园情。","温柔旧学如君少，落日临期老眼明。"]},{"t":"松轩为无锡杨璠题","f":"七言律诗","c":["落日长松野蔓滋，小门幽径曲通篱。","影横虚榻月当牖，风度清琴声满帷。","冰雪岁寒人共古，栋梁材大事何迟。","分明记得歌游处，白发青林有梦思。"]}]};